-- ============================================================
-- [IMPROVEMENT] Theme registry & validation
-- ============================================================
local EDITABLE_COLORS = {
    { key = "Background",   label = "Background"    },
    { key = "Surface",      label = "Surface"       },
    { key = "SurfaceHover", label = "Surface Hover" },
    { key = "Accent",       label = "Accent"        },
    { key = "Border",       label = "Border"        },
    { key = "TextPrimary",  label = "Text"          },
}
LucidUI._editableColors = EDITABLE_COLORS

-- Auto-fill missing keys from Default so no theme ever crashes.
local function ValidateTheme(t)
    local d = LucidUI.Themes.Default
    local out = {}
    for k, v in pairs(d) do out[k] = v end
    for k, v in pairs(t) do out[k] = v end
    return out
end
LucidUI._validateTheme = ValidateTheme

-- Derive theme — build a full theme from just 6 colors.
function LucidUI.DeriveTheme(custom)
    local base = LucidUI.Themes.Default
    local t = {}
    for k, v in pairs(base) do t[k] = v end

    for _, f in ipairs(EDITABLE_COLORS) do
        if custom[f.key] then t[f.key] = custom[f.key] end
    end

    if not custom.SurfaceHover then
        t.SurfaceHover = Color3.new(
            math.min(t.Surface.R + 0.10, 1),
            math.min(t.Surface.G + 0.10, 1),
            math.min(t.Surface.B + 0.10, 1)
        )
    end

    t.TextSecondary = Color3.new(
        math.min(t.TextPrimary.R * 0.92, 1),
        math.min(t.TextPrimary.G * 0.92, 1),
        math.min(t.TextPrimary.B * 0.92, 1)
    )
    t.TextMuted = Color3.new(
        (t.TextPrimary.R + t.Background.R) * 0.5,
        (t.TextPrimary.G + t.Background.G) * 0.5,
        (t.TextPrimary.B + t.Background.B) * 0.5
    )
    t.ToggleOff   = t.Surface
    t.SliderTrack = t.Surface
    t.TabActive   = t.TextPrimary
    t.TabInactive = t.TextMuted
    return t
end

-- Register a custom theme at runtime.
function LucidUI.RegisterTheme(name, themeTable)
    if type(name) ~= "string" or type(themeTable) ~= "table" then
        warn("[LucidUI] RegisterTheme: invalid arguments.")
        return false
    end
    LucidUI.Themes[name] = ValidateTheme(themeTable)
    return true
end

-- List all available theme names.
function LucidUI.GetThemeNames()
    local names = {}
    for name in pairs(LucidUI.Themes) do
        if not name:match("^__") then
            table.insert(names, name)
        end
    end
    table.sort(names, function(a, b)
        if a == "Default" then return true end
        if b == "Default" then return false end
        return a:lower() < b:lower()
    end)
    return names
end

LucidUI.Themes.Default = ValidateTheme(LucidUI.Themes.Default)

