    local ORBIT_SIZE = LOGO_SIZE + 16
    local orbitHolder = Create("Frame", {
        Size = UDim2.fromOffset(ORBIT_SIZE, ORBIT_SIZE),
        Position = UDim2.fromScale(0.5, 0.5),
