        ZIndex = 7,
        Parent = track,
    })
    Corner(999, fill)

    local shimmerGrad = Create("UIGradient", {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, accent),
            ColorSequenceKeypoint.new(0.35, accent),
            ColorSequenceKeypoint.new(0.5, Color3.new(1, 1, 1)),
