        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = accent,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 28, 1, -52),
        Size = UDim2.new(1, -56, 0, 14),
        TextXAlignment = Enum.TextXAlignment.Right,
        TextTransparency = 1,
        ZIndex = 6,
        Parent = card,
    })

    Tween(overlay, 0.40 / speed, { BackgroundTransparency = 0.35 }):Play()
    Tween(blur, 0.55 / speed, { Size = 28 }):Play()
    Tween(colorFx, 0.55 / speed, { Saturation = -0.25 }):Play()
    Tween(cardScale, 0.55 / speed, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
    Tween(card, 0.50 / speed, { BackgroundTransparency = theme.BackgroundTrans or 0.15 }):Play()
    Tween(cardStroke, 0.50 / speed, { Transparency = 0.35 }):Play()
    Tween(logoLabel, 0.50 / speed, { TextTransparency = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
    Tween(orbitDot, 0.50 / speed, { BackgroundTransparency = 0 }):Play()

    task.delay(0.25 / speed, function() Tween(titleLbl, 0.40 / speed, { TextTransparency = 0 }):Play() end)
    task.delay(0.35 / speed, function()
        Tween(chip, 0.30 / speed, { BackgroundTransparency = 0.85 }):Play()
        Tween(chipStroke, 0.30 / speed, { Transparency = 0.40 }):Play()
        Tween(chipLabel, 0.30 / speed, { TextTransparency = 0 }):Play()
    end)
    task.delay(0.45 / speed, function() Tween(tagLbl, 0.40 / speed, { TextTransparency = 0 }):Play() end)
    task.delay(0.55 / speed, function()
        for _, d in ipairs(stageDots) do
            Tween(d, 0.30 / speed, { BackgroundTransparency = 0.55 }):Play()
        end
        Tween(track, 0.35 / speed, { BackgroundTransparency = 0.4 }):Play()
        Tween(statusLbl, 0.30 / speed, { TextTransparency = 0 }):Play()
        Tween(rightLbl, 0.30 / speed, { TextTransparency = 0 }):Play()
    end)

    local animStart = tick()
    local animConn = RunService.RenderStepped:Connect(function()
        if not introGui.Parent then
            pcall(function() animConn:Disconnect() end)
            return
        end
        local t = (tick() - animStart) * speed

        if strokeGrad and strokeGrad.Parent then
            strokeGrad.Rotation = (t * 60) % 360
        end
        if orbitHolder and orbitHolder.Parent then
            orbitHolder.Rotation = (t * 90) % 360
        end
        if logo and logo.Parent then
            logo.BackgroundTransparency = 0.15 + 0.05 * math.sin(t * 3)
        end
        if shimmerGrad and shimmerGrad.Parent then
            local cycle = (t % 1.4) / 1.4
            shimmerGrad.Offset = Vector2.new(-1 + cycle * 2, 0)
        end

        local bass  = (math.sin(t * 0.62) * 0.5) + 0.5
        local kick  = math.max(0, math.sin(t * 2.35)) ^ 4
        local snare = math.max(0, math.sin(t * 3.85 + 1.4)) ^ 6
        local energy = bass * 0.35 + kick * 0.45 + snare * 0.20
        energy = math.clamp(energy, 0, 1)

        local alpha = math.clamp((t - 0.15) / 0.6, 0, 1)

        local stretch = energy * 0.28
        local squash  = energy * 0.10

        local sx = (1 + stretch) * alpha
        local sy = (1 - squash)  * alpha
        if blobCore and blobCore.Parent then
            blobCore.Size = UDim2.fromScale(sx, sy)
            blobCore.Rotation = math.sin(t * 1.6) * 6 * alpha
            local coreTarget = 0.80 - energy * 0.12
            blobCore.BackgroundTransparency = 1 - (1 - coreTarget) * alpha
        end

        if blobHalo and blobHalo.Parent then
            local haloScale = 1.10 + (1 - energy) * 0.15
            blobHalo.Size = UDim2.fromScale(haloScale * alpha, haloScale * alpha)
            local haloTarget = 0.88 - energy * 0.06
            blobHalo.BackgroundTransparency = 1 - (1 - haloTarget) * alpha
        end

        if blobShine and blobShine.Parent then
            local shineTarget = 0.72 - energy * 0.15
            blobShine.BackgroundTransparency = 1 - (1 - shineTarget) * alpha
        end
    end)

    local function burstParticles()
        local GOLDEN = 2.39996323 -- golden angle in radians
        for i = 1, 14 do
            local angle = i * GOLDEN
            local radius = 100 + (i % 3) * 20 -- vary radius for organic feel
            local dx = math.cos(angle) * radius
            local dy = math.sin(angle) * radius
            local dot = Create("Frame", {
                Size = UDim2.fromOffset(5, 5),
                Position = UDim2.new(0.5, 0, 0.5, 0),
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = accent,
                BorderSizePixel = 0,
                ZIndex = 10,
                Parent = overlay,
            })
            Corner(999, dot)
            pcall(function()
                Tween(dot, 0.7 / speed, {
                    Position = UDim2.new(0.5, dx, 0.5, dy),
                    BackgroundTransparency = 1,
                    Size = UDim2.fromOffset(2, 2),
                }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
            end)
            task.delay(0.8 / speed, function() pcall(function() dot:Destroy() end) end)
        end
    end

    local function expandRing()
        local ring = Create("Frame", {
            Size = UDim2.fromOffset(60, 60),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 10,
            Parent = overlay,
        })
        Corner(999, ring)
        local ringStroke = Stroke(accent, 3, 0, ring)
        pcall(function()
            Tween(ring, 0.7 / speed, {
                Size = UDim2.fromOffset(420, 420),
            }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
            Tween(ringStroke, 0.7 / speed, {
                Transparency = 1,
                Thickness = 1,
            }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
        end)
        task.delay(0.8 / speed, function() pcall(function() ring:Destroy() end) end)
    end

    local completed = false
    local function finish()
        if completed then return end
        completed = true

        if animConn then pcall(function() animConn:Disconnect() end) end

        expandRing()
        burstParticles()

        pcall(function()
            Tween(card, 0.5 / speed, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In):Play()
            Tween(cardStroke, 0.5 / speed, { Transparency = 1 }):Play()
            Tween(logo, 0.4 / speed, { BackgroundTransparency = 1 }):Play()
            Tween(logoLabel, 0.35 / speed, { TextTransparency = 1 }):Play()
            Tween(orbitDot, 0.3 / speed, { BackgroundTransparency = 1 }):Play()
            Tween(titleLbl, 0.35 / speed, { TextTransparency = 1 }):Play()
            Tween(chip, 0.3 / speed, { BackgroundTransparency = 1 }):Play()
            Tween(chipStroke, 0.3 / speed, { Transparency = 1 }):Play()
            Tween(chipLabel, 0.3 / speed, { TextTransparency = 1 }):Play()
            Tween(tagLbl, 0.35 / speed, { TextTransparency = 1 }):Play()
            Tween(track, 0.35 / speed, { BackgroundTransparency = 1 }):Play()
            Tween(fill, 0.35 / speed, { BackgroundTransparency = 1 }):Play()
            Tween(fillGlow, 0.35 / speed, { Transparency = 1 }):Play()
            Tween(statusLbl, 0.3 / speed, { TextTransparency = 1 }):Play()
            Tween(rightLbl, 0.3 / speed, { TextTransparency = 1 }):Play()
            for _, d in ipairs(stageDots) do
                Tween(d, 0.3 / speed, { BackgroundTransparency = 1 }):Play()
            end
            Tween(blobCore, 0.6 / speed, {
                Size = UDim2.fromScale(1.6, 1.6),
                BackgroundTransparency = 1,
            }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
            Tween(blobHalo, 0.6 / speed, {
                Size = UDim2.fromScale(2.0, 2.0),
                BackgroundTransparency = 1,
            }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
            Tween(blobShine, 0.4 / speed, { BackgroundTransparency = 1 }):Play()
            Tween(cardScale, 0.55 / speed, { Scale = 1.06 }, Enum.EasingStyle.Quart, Enum.EasingDirection.In):Play()
            Tween(overlay, 0.65 / speed, { BackgroundTransparency = 1 }):Play()
            Tween(blur, 0.65 / speed, { Size = 0 }):Play()
            Tween(colorFx, 0.65 / speed, { Saturation = 0, Brightness = 0, Contrast = 0 }):Play()
        end)

        task.wait(0.7 / speed)

        if blur.Parent then pcall(function() blur:Destroy() end) end
        if colorFx.Parent then pcall(function() colorFx:Destroy() end) end
        if introGui.Parent then pcall(function() introGui:Destroy() end) end
        if LucidUI._activeIntro == introGui then LucidUI._activeIntro = nil end

        if onComplete then pcall(onComplete) end
    end

    if skipNow then
        finish()
        return introGui
    end

    if skipOnInput then
        local skipConn
        skipConn = UserInputService.InputBegan:Connect(function(input, processed)
            if processed then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
                or input.UserInputType == Enum.UserInputType.Keyboard then
                if skipConn then pcall(function() skipConn:Disconnect() end) end
                finish()
            end
        end)
        task.delay(duration + 5, function()
            if skipConn then pcall(function() skipConn:Disconnect() end) end
        end)
    end

    task.spawn(function()
        local prevPct = 0

        for index, stage in ipairs(stages) do
            if completed then return end

            statusLbl.Text = stage.text
            rightLbl.Text = string.format("%d%%", math.floor(stage.pct * 100))

            local dot = stageDots[index]
            if dot then
                Tween(dot, 0.25 / speed, { BackgroundColor3 = accent, BackgroundTransparency = 0 }):Play()
            end

            if stage.task then
                local startPct = prevPct
                local targetPct = stage.pct

                local function report(subProgress)
                    subProgress = math.clamp(subProgress or 0, 0, 1)
                    local pct = startPct + (targetPct - startPct) * subProgress
                    fill.Size = UDim2.new(pct, 0, 1, 0)
                    rightLbl.Text = string.format("%d%%", math.floor(pct * 100))
                end

                local ok, err = pcall(stage.task, report)
                if not ok then
                    warn("[LucidUI] Intro stage task failed:", err)
                end

                Tween(fill, 0.18 / speed, {
                    Size = UDim2.new(targetPct, 0, 1, 0),
                }, Enum.EasingStyle.Quint, Enum.EasingDirection.Out):Play()
                rightLbl.Text = string.format("%d%%", math.floor(targetPct * 100))
                task.wait(0.15 / speed)

            else
                local waitTime  = (stage.wait or 0.35)
                local startPct  = prevPct
                local targetPct = stage.pct

                Tween(fill, waitTime, {
                    Size = UDim2.new(targetPct, 0, 1, 0),
                }, Enum.EasingStyle.Quint, Enum.EasingDirection.Out):Play()
                Tween(fillGlow, waitTime, { Transparency = 0.35 }):Play()

                local elapsed = 0
                local step = 0.05
                while elapsed < waitTime do
                    if completed then return end
                    local sub = elapsed / waitTime
                    local pct = startPct + (targetPct - startPct) * sub
                    rightLbl.Text = string.format("%d%%", math.floor(pct * 100))
                    task.wait(step)
                    elapsed = elapsed + step
                end
            end

            prevPct = stage.pct
        end

        task.wait(0.25 / speed)
        finish()
    end)

    return introGui
end

-- ============================================================
-- Module: 05_notifications.lua
-- ============================================================
--[[
    Notifications — glass toasts in the top-right corner.

    Each toast:
      • Slides in from the right with a scale entrance
      • Has a colored accent bar on the left that adapts to text height
      • Auto-dismisses after Duration (default 4s)
      • Can be clicked to dismiss early
      • Auto-icons based on Variant (info / success / warn / error)

    [IMPROVEMENT] Queue system, variant colors, manual dismiss.
    Caps visible notifications at MaxVisible (default 4).
    Progress bar removed for cleaner look.
]]

local MAX_VISIBLE = 4
local notifQueue = {}
local notifActive = {}

-- ============================================================
-- Root container (created once, reused forever)
-- ============================================================
local function GetNotificationRoot()
    if LucidUI._notifRoot and LucidUI._notifRoot.Parent then
        return LucidUI._notifRoot
    end

    local root = Create("ScreenGui", {
        Name = "LucidUI_Notifications",
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = 200,
        Parent = PlayerGui,
    })

    Create("UIListLayout", {
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        HorizontalAlignment = Enum.HorizontalAlignment.Right,
        Parent = root,
    })

    Create("UIPadding", {
        PaddingTop = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),
        Parent = root,
    })

    LucidUI._notifRoot = root
    return root
end

-- ============================================================
-- Variant → default accent + icon mapping
-- ============================================================
local VARIANTS = {
    info    = { Color = Color3.fromRGB(90, 180, 255),  Icon = "bell"    },
    success = { Color = Color3.fromRGB(90, 210, 130),  Icon = "check"   },
    warn    = { Color = Color3.fromRGB(255, 189, 46),  Icon = "warning" },
    error   = { Color = Color3.fromRGB(255, 95, 87),   Icon = "cross"   },
    default = { Color = nil,                           Icon = nil       },
}

-- ============================================================
-- Active notification count check
-- ============================================================
local function ActiveCount()
    local n = 0
    for i = #notifActive, 1, -1 do
        if notifActive[i] and notifActive[i].Parent then
            n = n + 1
        else
            table.remove(notifActive, i)
        end
    end
    return n
end

-- ============================================================
-- Process queue
-- ============================================================
local function ProcessQueue()
    while #notifQueue > 0 and ActiveCount() < MAX_VISIBLE do
        local nextConfig = table.remove(notifQueue, 1)
        LucidUI:_renderNotification(nextConfig)
    end
end

-- ============================================================
-- Public API
-- ============================================================
function LucidUI:Notify(config)
    config = config or {}

    if type(config) == "string" then
        config = { Title = "Notice", Message = config }
    end

    if ActiveCount() >= MAX_VISIBLE then
        table.insert(notifQueue, config)
        return nil
    end

    return self:_renderNotification(config)
end

function LucidUI:ClearAllNotifications()
    for _, card in ipairs(notifActive) do
        pcall(function()
            if card and card.Parent then card:Destroy() end
        end)
    end
    notifActive = {}
    notifQueue = {}
end

-- ============================================================
-- Internal renderer
-- ============================================================
function LucidUI:_renderNotification(config)
    local theme    = config.Theme or LucidUI._lastTheme or LucidUI.Themes.Default
    local root     = GetNotificationRoot()

    -- Resolve variant styling
    local variantName = config.Variant or "default"
    local variantData = VARIANTS[variantName] or VARIANTS.default

    local title    = config.Title or "Notice"
    local message  = config.Message or ""
    local duration = config.Duration or 4
    local accent   = config.Accent or variantData.Color or theme.Accent
    local iconName = config.Icon or variantData.Icon

    -- --------------------------------------------------------
    -- Card
    -- --------------------------------------------------------
    local card = Create("TextButton", {
        Name = "NotifCard",
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.fromOffset(320, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = theme.Background,
        BackgroundTransparency = 1,
        Parent = root,
    })
    Corner(14, card)
    local stroke = Stroke(accent, 1, 0.4, card)

    local cardScale = Create("UIScale", { Scale = 0.85, Parent = card })

    -- --------------------------------------------------------
    -- Accent bar (height adjusted after layout settles)
    -- --------------------------------------------------------

local bar = Create("Frame", {
    Size = UDim2.new(0, 3, 0, 22),  -- fixed height
    Position = UDim2.new(0, 8, 0.5, 0),
    AnchorPoint = Vector2.new(0, 0.5),
    BackgroundColor3 = accent,
    BorderSizePixel = 0,
    Parent = card,
})
Corner(2, bar)

    -- --------------------------------------------------------
    -- Icon (optional)
    -- --------------------------------------------------------
    local iconLeft = 18
    if iconName then
        local iconHolder = Create("Frame", {
            Size = UDim2.fromOffset(18, 18),
            Position = UDim2.fromOffset(20, 14),
            BackgroundTransparency = 1,
            Parent = card,
        })
        if LucidUI.IconBuilders and LucidUI.IconBuilders[iconName] then
            pcall(function()
                LucidUI.IconBuilders[iconName](iconHolder, 18, accent)
            end)
        end
        iconLeft = 46
    end

    -- --------------------------------------------------------
    -- Title + message
    -- --------------------------------------------------------
    local titleLbl = Create("TextLabel", {
        Text = title,
        Font = Enum.Font.GothamBold,
        TextSize = 14,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(iconLeft, 12),
        Size = UDim2.new(1, -(iconLeft + 14), 0, 18),
        Parent = card,
    })

    local msgLbl = Create("TextLabel", {
        Text = message,
        Font = Enum.Font.Gotham,
        TextSize = 12,
        TextColor3 = theme.TextSecondary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true,
        Position = UDim2.fromOffset(iconLeft, 32),
        Size = UDim2.new(1, -(iconLeft + 14), 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        Parent = card,
    })

    -- Bottom spacer so the card has symmetric padding
    Create("Frame", {
        Size = UDim2.new(1, 0, 0, 14),
        Position = UDim2.new(0, 0, 1, 0),
        BackgroundTransparency = 1,
        Parent = card,
    })


    -- --------------------------------------------------------
    -- Track this card
    -- --------------------------------------------------------
    table.insert(notifActive, card)

    -- --------------------------------------------------------
    -- Slide in from the right + scale up
    -- --------------------------------------------------------
    card.Position = UDim2.fromOffset(340, 0)
    pcall(function()
        Tween(card, 0.30, {
            Position = UDim2.fromOffset(0, 0),
            BackgroundTransparency = theme.BackgroundTrans or 0.15,
        }, Enum.EasingStyle.Back):Play()
        Tween(cardScale, 0.35, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
    end)

    -- --------------------------------------------------------
    -- Dismiss logic
    -- --------------------------------------------------------
    local dismissed = false
    local function dismiss()
        if dismissed then return end
        dismissed = true

        pcall(function()
            Tween(card, 0.25, {
                Position = UDim2.fromOffset(340, 0),
                BackgroundTransparency = 1,
            }, Enum.EasingStyle.Quad, Enum.EasingDirection.In):Play()

            Tween(cardScale, 0.25, { Scale = 0.9 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In):Play()
            Tween(stroke,   0.25, { Transparency = 1 }):Play()
            Tween(titleLbl, 0.20, { TextTransparency = 1 }):Play()
            Tween(msgLbl,   0.20, { TextTransparency = 1 }):Play()
            Tween(bar,      0.25, { BackgroundTransparency = 1 }):Play()
        end)

        task.wait(0.30)
        if card.Parent then pcall(function() card:Destroy() end) end

        -- Remove from active list
        for i = #notifActive, 1, -1 do
            if notifActive[i] == card then
                table.remove(notifActive, i)
                break
            end
        end

        -- Process the queue
        task.defer(ProcessQueue)
    end

    -- Click to dismiss
    card.MouseButton1Click:Connect(dismiss)
    card.TouchTap:Connect(dismiss)

    -- Auto-dismiss
    task.delay(duration, dismiss)

    return card
end

-- ============================================================
-- Module: 06_window.lua
-- ============================================================
--[[
    Window — creates the main window and every layer that sits inside it.
]]

-- Preserve any pre-existing LucidUI.Window table (in case a future
-- module loads before us and patches it). If nothing exists yet,
-- create a fresh empty table. Either way, ensure __index points to
-- itself so methods added later still resolve.
LucidUI.Window = LucidUI.Window or {}
LucidUI.Window.__index = LucidUI.Window

local function TweenColor(inst, prop, target, time)
    if not inst or not inst.Parent then return end
    local current = inst[prop]
    if typeof(current) ~= "Color3" then
        inst[prop] = target
        return
    end
    pcall(function()
        TweenService:Create(
            inst,
            TweenInfo.new(time or 0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            { [prop] = target }
        ):Play()
    end)
end

local function isPrimaryPointer(input)
    return input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch
end

function LucidUI:CreateWindow(config)
    config = config or {}

    local W = setmetatable({}, LucidUI.Window)

    W.Name         = config.Name or "LucidUI"
    W.Theme        = LucidUI.Themes[config.Theme or "Default"] or LucidUI.Themes.Default
    W.ThemeName    = config.Theme or "Default"
    W.Tabs         = {}
    W.ActiveTab    = nil
    W.Visible      = true
    W.Minimized    = false
    W.Floating     = false
    W.SettingsOpen = false

    W.PillKeybind  = config.PillKeybind or Enum.KeyCode.Home
    W._closeAction = config.CloseAction or "pill"

    W._configData     = {}
    W._elementsByFlag = {}
    W._themeElements  = {}
    W._conns          = {}
    W._accentOverride = nil

    W._minWidth,  W._minHeight = 320, 240
    W._maxWidth,  W._maxHeight = 1200, 900

    W._customTheme       = nil
    W._customThemeActive = false
    W._currentConfig     = "default"
    W._backgroundUrl     = nil

    W._width  = config.Width  or 620
    W._height = config.Height or 460
    W._fullSize      = UDim2.fromOffset(W._width, W._height)
    W._collapsedSize = UDim2.fromOffset(W._width, 44)

    W._compactWidth = nil

    LucidUI._lastTheme = W.Theme
    Compat.ensureFolders()

    W.Gui = Create("ScreenGui", {
        Name = "LucidUI_" .. W.Name,
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = 100,
        Enabled = false,
        Parent = PlayerGui,
    })

    W.UIScale = Create("UIScale", { Scale = GetResponsiveScale(), Parent = W.Gui })

    do
        -- Camera can be nil if 01_helpers.lua's lookup timed out or
        -- if the executor injected before the camera spawned. Fall
        -- back to workspace.CurrentCamera at call time and skip the
        -- connection if even that is unavailable.
        local cam = Camera or workspace.CurrentCamera
        if cam then
            table.insert(W._conns, cam:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                if W.UIScale and W.UIScale.Parent then W.UIScale.Scale = GetResponsiveScale() end
                pcall(function() ClampPosition(W.Main) end)
                pcall(function() ClampPosition(W.FloatingPill) end)
            end))
        end
    end

    W.Main = Create("Frame", {
        Name = "Main",
        Size = W._fullSize,
        Position = UDim2.new(0.5, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Visible = false,
        Parent = W.Gui,
    })
    ApplyGlass(W.Main, W.Theme, { cornerRadius = 18, shadow = true })

    W._bgImage = Create("ImageLabel", {
        Name = "BackgroundImage",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Image = "",
        ImageTransparency = 1,
        ScaleType = Enum.ScaleType.Crop,
        ZIndex = 0,
        Visible = false,
        Parent = W.Main,
    })
    Corner(18, W._bgImage)

    W.Header = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 44),
        BackgroundTransparency = 1,
        ZIndex = 3,
        Parent = W.Main,
    })

    W.TitleLabel = Create("TextLabel", {
        Text = W.Name,
        Font = Enum.Font.GothamBold,
        TextSize = 16,
        TextColor3 = W.Theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(18, 0),
        Size = UDim2.new(1, -170, 1, 0),
        ZIndex = 3,
        Parent = W.Header,
    })

    local titlePx = TextService:GetTextSize(
        W.Name, 16, Enum.Font.GothamBold, Vector2.new(2000, 44)
    )
    W._compactWidth = math.clamp(titlePx.X + 120, 220, W._width)

    local pillTextPx = TextService:GetTextSize(
        W.Name, 13, Enum.Font.GothamBold, Vector2.new(2000, 32)
    )
    local pillWidth = math.clamp(pillTextPx.X + 50, 120, 280)

    local settingsBtn = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(36, 36),
        Position = UDim2.new(1, -120, 0.5, -18),
        ZIndex = 3,
        Parent = W.Header,
    })
    W._settingsBtn = settingsBtn

    local gearHolder, gearRing, gearParts, gearHole =
        BuildGearIcon(settingsBtn, 18, W.Theme.TextSecondary, W.Theme.Background)
    gearHolder.Position = UDim2.fromScale(0.5, 0.5)
    gearHolder.AnchorPoint = Vector2.new(0.5, 0.5)

    local gearRot   = 0
    local gearSpeed = 30
    table.insert(W._conns, RunService.RenderStepped:Connect(function(dt)
        if not gearRing or not gearRing.Parent then return end
        gearRot = (gearRot + dt * gearSpeed) % 360
        gearRing.Rotation = gearRot
    end))

    BindTap(settingsBtn, function() W:ToggleSettings() end)

    settingsBtn.MouseEnter:Connect(function()
        for _, p in ipairs(gearParts) do
            Tween(p, 0.15, { BackgroundColor3 = W.Theme.Accent }):Play()
        end
        gearSpeed = 120
    end)
    settingsBtn.MouseLeave:Connect(function()
        for _, p in ipairs(gearParts) do
            Tween(p, 0.15, { BackgroundColor3 = W.Theme.TextSecondary }):Play()
        end
        gearSpeed = 30
    end)

    W._gearRefs = { parts = gearParts, hole = gearHole, ring = gearRing }

    -- ==========================================
    -- MINIMIZE BUTTON
    -- ==========================================
    local minBtn = Create("TextButton", {
        Text = "",
        BackgroundColor3 = Color3.fromRGB(255, 189, 46),
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(12, 12),
        Position = UDim2.new(1, -48, 0.5, -6),
        AutoButtonColor = false,
        ZIndex = 3,
        Parent = W.Header,
    })
    Corner(999, minBtn)

    local minDot = Create("TextLabel", {
        Text = "-",
        Font = Enum.Font.GothamBold,
        TextSize = 12,
        TextColor3 = Color3.fromRGB(140, 90, 0),
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        TextTransparency = 1,
        ZIndex = 4,
        Parent = minBtn,
    })

    BindTap(minBtn, function() W:SetMinimized(not W.Minimized) end, { MoveThreshold = 25 })

    minBtn.MouseEnter:Connect(function()
        Tween(minBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 214, 100) }):Play()
        Tween(minDot, 0.15, { TextTransparency = 0 }):Play()
    end)
    minBtn.MouseLeave:Connect(function()
        Tween(minBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 189, 46) }):Play()
        Tween(minDot, 0.15, { TextTransparency = 1 }):Play()
    end)

    -- ==========================================
    -- CLOSE BUTTON
    -- ==========================================
    local closeBtn = Create("TextButton", {
        Text = "",
        BackgroundColor3 = Color3.fromRGB(255, 95, 87),
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(12, 12),
        Position = UDim2.new(1, -26, 0.5, -6),
        AutoButtonColor = false,
        ZIndex = 3,
        Parent = W.Header,
    })
    Corner(999, closeBtn)

    local closeDot = Create("TextLabel", {
        Text = "x",
        Font = Enum.Font.GothamBold,
        TextSize = 12,
        TextColor3 = Color3.fromRGB(120, 20, 20),
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        TextTransparency = 1,
        ZIndex = 4,
        Parent = closeBtn,
    })

    BindTap(closeBtn, function()
        if W._closeAction == "destroy" then
            W:Destroy()
        else
            W:MinimizeToPill()
        end
    end, { MoveThreshold = 25 })

    closeBtn.MouseEnter:Connect(function()
        Tween(closeBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 130, 120) }):Play()
        Tween(closeDot, 0.15, { TextTransparency = 0 }):Play()
    end)
    closeBtn.MouseLeave:Connect(function()
        Tween(closeBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 95, 87) }):Play()
        Tween(closeDot, 0.15, { TextTransparency = 1 }):Play()
    end)

    W._iconRefs = {
        minimize = { label = minBtn },
        close    = { label = closeBtn },
    }

    W.Separator = Create("Frame", {
        Size = UDim2.new(1, -32, 0, 1),
        Position = UDim2.fromOffset(16, 44),
        BackgroundColor3 = W.Theme.Border,
        BackgroundTransparency = W.Theme.BorderTrans + 0.03,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = W.Main,
    })

    W.TabStrip = Create("ScrollingFrame", {
        Name = "TabStrip",
        Size = UDim2.new(1, -32, 0, 34),
        Position = UDim2.fromOffset(16, 52),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 0,
        ScrollingDirection = Enum.ScrollingDirection.X,
        CanvasSize = UDim2.new(0, 0, 0, 34),
        AutomaticCanvasSize = Enum.AutomaticSize.X,
        ZIndex = 2,
        Parent = W.Main,
    })
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Parent = W.TabStrip,
    })

    W.Content = Create("Frame", {
        Name = "Content",
        Size = UDim2.new(1, -24, 1, -110),
        Position = UDim2.fromOffset(12, 94),
        BackgroundTransparency = 1,
        ClipsDescendants = true,
        ZIndex = 2,
        Parent = W.Main,
    })

    -- ============================================================
    -- Shared gesture state — header drag and resize
    -- ============================================================
    local gesture = {
        input        = nil,
        mode         = nil,
        startPos     = nil,
        startSize    = nil,
        mainStartPos = nil,
    }

    W.Header.InputBegan:Connect(function(input)
        if not isPrimaryPointer(input) then return end
        if gesture.input then return end

        -- Watch for the input ending during the 50ms debounce window.
        -- Works for both mouse and touch so quick taps don't slip
        -- through into a phantom drag on mobile.
        local cancelled = false
        local cancelConn = UserInputService.InputEnded:Connect(function(ended)
            if ended == input then cancelled = true end
        end)

        task.wait(0.05)

        if cancelConn then cancelConn:Disconnect() end
        if cancelled then return end
        if gesture.input then return end

        if W._onBeforeDragStart then W:_onBeforeDragStart() end
        gesture.input        = input
        gesture.mode         = "drag"
        gesture.startPos     = input.Position
        gesture.mainStartPos = W.Main.Position
    end)

    -- 44x44 hitbox for mobile friendliness
    local resizeHandle = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(44, 44),
        Position = UDim2.new(1, -44, 1, -44),
        ZIndex = 4,
        Parent = W.Main,
    })

    local grip1 = Create("Frame", {
        Size = UDim2.fromOffset(12, 2),
        Position = UDim2.new(1, -8, 1, -8),
        AnchorPoint = Vector2.new(1, 0.5),
        Rotation = 45,
        BackgroundColor3 = W.Theme.TextMuted,
        BackgroundTransparency = 0.5,
        BorderSizePixel = 0,
        Parent = resizeHandle,
    })
    Corner(1, grip1)

    local grip2 = Create("Frame", {
        Size = UDim2.fromOffset(8, 2),
        Position = UDim2.new(1, -8, 1, -5),
        AnchorPoint = Vector2.new(1, 0.5),
        Rotation = 45,
        BackgroundColor3 = W.Theme.TextMuted,
        BackgroundTransparency = 0.5,
        BorderSizePixel = 0,
        Parent = resizeHandle,
    })
    Corner(1, grip2)

    W._gripFrames = { grip1, grip2 }
    
    -- FIX: Store a reference so we can hide it when minimized
    W._resizeHandle = resizeHandle

    resizeHandle.InputBegan:Connect(function(input)
        if not isPrimaryPointer(input) then return end
        if gesture.input then return end
        if W._docked then return end
        gesture.input     = input
        gesture.mode      = "resize"
        gesture.startPos  = input.Position
        gesture.startSize = { X = W._width, Y = W._height }
    end)

    table.insert(W._conns, UserInputService.InputChanged:Connect(function(input)
        if input ~= gesture.input then return end

        if gesture.mode == "drag" then
            local d = input.Position - gesture.startPos
            W.Main.Position = UDim2.new(
                gesture.mainStartPos.X.Scale, gesture.mainStartPos.X.Offset + d.X,
                gesture.mainStartPos.Y.Scale, gesture.mainStartPos.Y.Offset + d.Y
            )
            if W._onDragTick then W:_onDragTick() end
        elseif gesture.mode == "resize" then
            local d = input.Position - gesture.startPos
            W._width  = math.clamp(gesture.startSize.X + d.X, W._minWidth,  W._maxWidth)
            W._height = math.clamp(gesture.startSize.Y + d.Y, W._minHeight, W._maxHeight)
            W._fullSize      = UDim2.fromOffset(W._width, W._height)
            W._collapsedSize = UDim2.fromOffset(W._width, 44)

            local tpx = TextService:GetTextSize(
                W.Name, 16, Enum.Font.GothamBold, Vector2.new(2000, 44)
            )
            W._compactWidth = math.clamp(tpx.X + 120, 220, W._width)

            if not W.Minimized then
                W.Main.Size    = UDim2.fromOffset(W._width, W._height)
                W.Content.Size = UDim2.new(1, -24, 1, -110)
            end
        end
    end))

    table.insert(W._conns, UserInputService.InputEnded:Connect(function(input)
        if input ~= gesture.input then return end
        local wasDrag = (gesture.mode == "drag")
        if gesture.mode == "drag" or gesture.mode == "resize" then
            ClampPosition(W.Main)
        end
        if wasDrag and W._onDragEnd then W:_onDragEnd() end
        gesture.input        = nil
        gesture.mode         = nil
        gesture.startPos     = nil
        gesture.startSize    = nil
        gesture.mainStartPos = nil
    end))

    -- ============================================================
    -- Global keybinds
    -- ============================================================
    table.insert(W._conns, UserInputService.InputBegan:Connect(function(input, processed)
        if processed then return end
        if LucidUI._keyListening then return end

        if input.KeyCode == Enum.KeyCode.RightShift then
            if W.Floating then
                W:RestoreFromPill()
            else
                W:SetVisible(not W.Visible)
            end
        elseif W.PillKeybind and input.KeyCode == W.PillKeybind then
            W:TogglePillMode()
        end
    end))

    -- ============================================================
    -- Settings panel
    -- ============================================================
    W.SettingsPanel = Create("CanvasGroup", {
        Name = "SettingsPanel",
        Size = UDim2.new(1, 0, 1, -45),
        Position = UDim2.new(0, 0, 0, 45),
        BackgroundColor3 = W.Theme.Background,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        Visible = false,
        GroupTransparency = 1,
        ZIndex = 5,
        Parent = W.Main,
    })
    local spCorner = Instance.new("UICorner")
    spCorner.TopLeftRadius     = UDim.new(0, 0)
    spCorner.TopRightRadius    = UDim.new(0, 0)
    spCorner.BottomLeftRadius  = UDim.new(0, 18)
    spCorner.BottomRightRadius = UDim.new(0, 18)
    spCorner.Parent = W.SettingsPanel

    local spHeader = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 40),
        BackgroundTransparency = 1,
        ZIndex = 6,
        Parent = W.SettingsPanel,
    })

    local backBtn = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(32, 32),
        Position = UDim2.fromOffset(12, 4),
        ZIndex = 7,
        Parent = spHeader,
    })
    local backLbl = Create("TextLabel", {
        Text = "<",
        Font = Enum.Font.GothamBold,
        TextSize = 22,
        TextColor3 = W.Theme.TextSecondary,
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 7,
        Parent = backBtn,
    })

    BindTap(backBtn, function()
        if W._cancelKeybindListen then pcall(W._cancelKeybindListen) end
        W:ToggleSettings(false)
    end, { MoveThreshold = 8 })

    Create("TextLabel", {
        Text = "Settings",
        Font = Enum.Font.GothamBold,
        TextSize = 16,
        TextColor3 = W.Theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(52, 0),
        Size = UDim2.new(1, -60, 1, 0),
        ZIndex = 7,
        Parent = spHeader,
    })

    Create("Frame", {
        Size = UDim2.new(1, -24, 0, 1),
        Position = UDim2.fromOffset(12, 40),
        BackgroundColor3 = W.Theme.Border,
        BackgroundTransparency = W.Theme.BorderTrans + 0.03,
        BorderSizePixel = 0,
        ZIndex = 7,
        Parent = W.SettingsPanel,
    })

    local spContent = Create("ScrollingFrame", {
        Size = UDim2.new(1, -20, 1, -50),
        Position = UDim2.fromOffset(10, 44),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = W.Theme.TextMuted,
        ScrollBarImageTransparency = 0.5,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ZIndex = 6,
        Parent = W.SettingsPanel,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = spContent,
    })
    Create("UIPadding", {
        PaddingRight = UDim.new(0, 8),
        PaddingBottom = UDim.new(0, 12),
        Parent = spContent,
    })

    W._spContent     = spContent
    W._settingsOrder = 0
    W._backArrowLbl  = backLbl

    -- ============================================================
    -- Floating pill
    -- ============================================================
    W.FloatingPill = Create("TextButton", {
        Name = "FloatingPill",
        Text = "",
        Size = UDim2.fromOffset(pillWidth, 32),
        Position = UDim2.new(0.5, 0, 0, 8),
        AnchorPoint = Vector2.new(0.5, 0),
        BackgroundColor3 = W.Theme.Background,
        BackgroundTransparency = W.Theme.BackgroundTrans,
        AutoButtonColor = false,
        Visible = false,
        ClipsDescendants = true,
        Parent = W.Gui,
    })
    Corner(16, W.FloatingPill)
    W._pillStroke = Stroke(W.Theme.Accent, 1, 0.3, W.FloatingPill)

    W._pillDot = Create("Frame", {
        Size = UDim2.fromOffset(8, 8),
        Position = UDim2.fromOffset(14, 12),
        BackgroundColor3 = W.Theme.Accent,
        BorderSizePixel = 0,
        Parent = W.FloatingPill,
    })
    Corner(4, W._pillDot)

    W._pillLabel = Create("TextLabel", {
        Text = W.Name,
        Font = Enum.Font.GothamBold,
        TextSize = 13,
        TextColor3 = W.Theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Position = UDim2.fromOffset(28, 0),
        Size = UDim2.new(1, -34, 1, 0),
        Parent = W.FloatingPill,
    })

    task.spawn(function()
        local t = 0
        while W._pillDot do
            if W._pillDot.Parent then
                t = (t + 0.03) % 2
                local pulse = 0.5 + 0.5 * math.sin(t * math.pi)
                W._pillDot.BackgroundTransparency = pulse * 0.55
            end
            task.wait(0.03)
        end
    end)

    local pillGesture = { input = nil, startPos = nil, startWindowPos = nil }

    W.FloatingPill.InputBegan:Connect(function(input)
        if not isPrimaryPointer(input) then return end
        if pillGesture.input then return end
        pillGesture.input          = input
        pillGesture.startPos       = input.Position
        pillGesture.startWindowPos = W.FloatingPill.Position
    end)

    table.insert(W._conns, UserInputService.InputChanged:Connect(function(input)
        if input ~= pillGesture.input then return end
        local d = input.Position - pillGesture.startPos
        W.FloatingPill.Position = UDim2.new(
            pillGesture.startWindowPos.X.Scale, pillGesture.startWindowPos.X.Offset + d.X,
            pillGesture.startWindowPos.Y.Scale, pillGesture.startWindowPos.Y.Offset + d.Y
        )
    end))

    table.insert(W._conns, UserInputService.InputEnded:Connect(function(input)
        if input ~= pillGesture.input then return end
        ClampPosition(W.FloatingPill)
        pillGesture.input          = nil
        pillGesture.startPos       = nil
        pillGesture.startWindowPos = nil
    end))

    BindTap(W.FloatingPill, function()
        W:RestoreFromPill()
    end, { MoveThreshold = 8 })

    table.insert(LucidUI._windows, W)

    print("[LucidUI] Window created:", W.Name)

    local entranceScale = Create("UIScale", { Scale = 0.90, Parent = W.Main })

    local function RunEntrance()
        W.Main.Visible = true
        W.Gui.Enabled  = true
        entranceScale.Scale = 0.90
        W.Main.BackgroundTransparency = 1
        Tween(entranceScale, 0.40, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
        Tween(W.Main, 0.40, { BackgroundTransparency = W.Theme.BackgroundTrans }):Play()
    end

    if W._initDocking then W:_initDocking(config) end

    if config.IntroEnabled ~= false and type(LucidUI.ShowIntro) == "function" then
        LucidUI:ShowIntro({
            Title       = config.IntroTitle or W.Name,
            Subtitle    = config.IntroSubtitle or ("v" .. LucidUI._version),
            Tagline     = config.IntroTagline or "Modern interface suite",
            Duration    = config.IntroDuration or 2.8,
            Stages      = config.IntroStages,
            Theme       = W.Theme,
            SkipOnInput = config.IntroSkipOnInput ~= false,
            OnComplete  = RunEntrance,
        })
    else
        RunEntrance()
    end

    return W
end

function LucidUI.Window:MinimizeToPill()
    if not self.FloatingPill then return end
    self.Floating = true

    local mx, my = self.Main.Position.X, self.Main.Position.Y

    local mainSlide = TweenService:Create(self.Main, Ease.In(0.22), {
        Position = UDim2.new(mx.Scale, mx.Offset, my.Scale, my.Offset - 30),
        BackgroundTransparency = 1,
    })
    mainSlide:Play()

    mainSlide.Completed:Connect(function()
        if not self.Floating then return end

        self.Main.Visible  = false
        self.Main.Position = UDim2.new(0.5, 0, 0.5, 0)

        self.FloatingPill.Visible                = true
        self.FloatingPill.Position               = UDim2.new(0.5, 0, 0, -50)
        self.FloatingPill.BackgroundTransparency = 1
        self._pillStroke.Transparency            = 1
        self._pillDot.BackgroundTransparency     = 1
        self._pillLabel.TextTransparency         = 1

        TweenService:Create(self.FloatingPill, Ease.Out(0.32), {
            Position = UDim2.new(0.5, 0, 0, 8),
        }):Play()
        TweenService:Create(self.FloatingPill, Ease.FadeIn(0.25), {
            BackgroundTransparency = self.Theme.BackgroundTrans,
        }):Play()
        TweenService:Create(self._pillStroke, Ease.FadeIn(0.28), { Transparency = 0.3 }):Play()
        TweenService:Create(self._pillLabel,  Ease.FadeIn(0.25), { TextTransparency = 0 }):Play()
        self._pillDot.BackgroundTransparency = 0
    end)
end

function LucidUI.Window:RestoreFromPill()
    if not self.FloatingPill then return end
    self.Floating = false

    -- FIX: If the window was minimized before turning into a pill,
    -- restore it to its full size instead of a tiny bar.
    if self.Minimized then
        self.Minimized = false
        self.Main.Size = UDim2.fromOffset(self._width, self._height)
        
        if not self.SettingsOpen then
            self.Content.Visible   = true
            self.Separator.Visible = true
            self.TabStrip.Visible  = true
        end
        
        if self._settingsBtn then
            self._settingsBtn.Visible = true
            if self._gearRefs then
                for _, p in ipairs(self._gearRefs.parts) do
                    p.BackgroundTransparency = 0
                end
                if self._gearRefs.hole then
                    self._gearRefs.hole.BackgroundTransparency = 0
                end
            end
        end
        
        -- FIX: Re-show the resize handle since we're back to normal size
        if self._resizeHandle then self._resizeHandle.Visible = true end
    end

    local slide = TweenService:Create(self.FloatingPill, Ease.In(0.26), {
        Position = UDim2.new(0.5, 0, 0, -50),
    })
    slide:Play()

    TweenService:Create(self.FloatingPill, Ease.FadeOut(0.20), { BackgroundTransparency = 1 }):Play()
    TweenService:Create(self._pillStroke,  Ease.FadeOut(0.20), { Transparency = 1 }):Play()
    TweenService:Create(self._pillDot,     Ease.FadeOut(0.18), { BackgroundTransparency = 1 }):Play()
    TweenService:Create(self._pillLabel,   Ease.FadeOut(0.18), { TextTransparency = 1 }):Play()

    self.Main.Visible                = true
    self.Main.Position               = UDim2.new(0.5, 0, 0.5, -20)
    self.Main.BackgroundTransparency = 1

    TweenService:Create(self.Main, Ease.Out(0.35), {
        Position = UDim2.new(0.5, 0, 0.5, 0),
        BackgroundTransparency = self.Theme.BackgroundTrans,
    }):Play()

    slide.Completed:Connect(function()
        if not self.Floating then
            self.FloatingPill.Visible = false
        end
    end)

    task.delay(0.4, function() ClampPosition(self.Main) end)
end

function LucidUI.Window:TogglePillMode()
    if self.Floating then
        self:RestoreFromPill()
    else
        self:MinimizeToPill()
    end
end

function LucidUI.Window:ToggleSettings(state)
    if state == nil then state = not self.SettingsOpen end
    self.SettingsOpen = state

    local SHOWN  = UDim2.new(0, 0, 0, 45)
    local HIDDEN = UDim2.new(0, 0, 0, 85)

    if state then
        self.TabStrip.Visible  = false
        self.Content.Visible   = false
        self.Separator.Visible = false

        self.SettingsPanel.Visible           = true
        self.SettingsPanel.Position          = HIDDEN
        self.SettingsPanel.GroupTransparency = 1

        TweenService:Create(self.SettingsPanel, Ease.Out(0.38), { Position = SHOWN }):Play()
        TweenService:Create(self.SettingsPanel, Ease.FadeIn(0.32), { GroupTransparency = 0 }):Play()

        if self._themeSlotsRefresh    then pcall(self._themeSlotsRefresh) end
        if self._themeDropdownRefresh then pcall(self._themeDropdownRefresh) end
    else
        if self._cancelKeybindListen then pcall(self._cancelKeybindListen) end

        local slide = TweenService:Create(self.SettingsPanel, Ease.In(0.26), { Position = HIDDEN })
        slide:Play()
        TweenService:Create(self.SettingsPanel, Ease.FadeOut(0.22), { GroupTransparency = 1 }):Play()

        slide.Completed:Connect(function()
            if not self.SettingsOpen then
                self.SettingsPanel.Visible = false
                if not self.Minimized then
                    self.TabStrip.Visible  = true
                    self.Content.Visible   = true
                    self.Separator.Visible = true
                end
            end
        end)
    end
end

function LucidUI.Window:Destroy()
    for _, c in ipairs(self._conns or {}) do
        if typeof(c) == "RBXScriptConnection" then c:Disconnect() end
    end
    self._conns = {}

    if LucidUI._activeSlider and LucidUI._activeSlider.Parent == self.Gui then
        LucidUI._activeSlider = nil
    end

    if self.Gui then
        self.Gui:Destroy()
        self.Gui = nil
    end

    for i, w in ipairs(LucidUI._windows) do
        if w == self then
            table.remove(LucidUI._windows, i)
            break
        end
    end

    print("[LucidUI] Window destroyed:", self.Name)
end

function LucidUI.Window:SetVisible(state)
    self.Visible = state
    if self.Gui then self.Gui.Enabled = state end
end

function LucidUI.Window:Center()
    if not self.Main then return end
    self.Main.Position = UDim2.new(0.5, 0, 0.5, 0)
    self.Main.AnchorPoint = Vector2.new(0.5, 0.5)
end

function LucidUI.Window:GetSize()
    return self._width, self._height
end

function LucidUI.Window:SetSize(w, h)
    self._width  = math.clamp(w, self._minWidth,  self._maxWidth)
    self._height = math.clamp(h, self._minHeight, self._maxHeight)
    self._fullSize = UDim2.fromOffset(self._width, self._height)
    if not self.Minimized then
        self.Main.Size = self._fullSize
    end
end

function LucidUI.Window:SetMinimized(state)
    if state == self.Minimized then return end
    self.Minimized = state

    local collapsedHeight = 44
    local targetWidth  = state and (self._compactWidth or self._width) or self._width
    local targetHeight = state and collapsedHeight or self._height

    if state then
        -- FIX: Hide the resize handle so it doesn't eat the red dot's clicks
        if self._resizeHandle then self._resizeHandle.Visible = false end
        
        if self._gearRefs then
            for _, p in ipairs(self._gearRefs.parts) do
                TweenService:Create(p, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                    { BackgroundTransparency = 1 }):Play()
            end
            if self._gearRefs.hole then
                TweenService:Create(self._gearRefs.hole, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                    { BackgroundTransparency = 1 }):Play()
            end
        end
        task.delay(0.17, function()
            if self._settingsBtn then
                self._settingsBtn.Visible = false
            end
        end)

        if self.SettingsOpen then self:ToggleSettings(false) end

        self.Content.Visible   = false
        self.Separator.Visible = false
        self.TabStrip.Visible  = false
    end

    TweenService:Create(self.Main, Ease.Out(0.30), {
        Size = UDim2.fromOffset(targetWidth, targetHeight),
    }):Play()

    if not state then
        -- FIX: Re-show the resize handle when the window is restored
        if self._resizeHandle then self._resizeHandle.Visible = true end
        
        task.delay(0.05, function()
            if self._settingsBtn then
                self._settingsBtn.Visible = true
                if self._gearRefs then
                    for _, p in ipairs(self._gearRefs.parts) do
                        p.BackgroundTransparency = 1
                        TweenService:Create(p, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                            { BackgroundTransparency = 0 }):Play()
                    end
                    if self._gearRefs.hole then
                        self._gearRefs.hole.BackgroundTransparency = 1
                        TweenService:Create(self._gearRefs.hole, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                            { BackgroundTransparency = 0 }):Play()
                    end
                end
            end
        end)

        if not self.SettingsOpen then
            task.delay(0.15, function()
                if not self.Minimized then
                    self.Content.Visible   = true
                    self.Separator.Visible = true
                    self.TabStrip.Visible  = true
                end
            end)
        end
    end

    task.delay(0.35, function() ClampPosition(self.Main) end)
end

function LucidUI.Window:SetTheme(name)
    if name == "Custom" or name == "__custom_runtime" then
        self:ApplyCustomTheme()
        return
    end
    if LucidUI.Themes[name] then
        self.Theme     = LucidUI.Themes[name]
        self.ThemeName = name
        self._customThemeActive = false
        LucidUI._lastTheme = self.Theme
        self:SetThemeObject(self.Theme)
        return
    end
    self:LoadCustomTheme(name)
end

function LucidUI.Window:SetThemeObject(t)
    if not t then return end

    TweenColor(self.Main, "BackgroundColor3", t.Background, 0.30)
    if not (self._bgImage and self._bgImage.Visible) then
        self.Main.BackgroundTransparency = t.BackgroundTrans or 0.20
    end

    TweenColor(self.TitleLabel, "TextColor3", t.TextPrimary, 0.30)
    TweenColor(self.Separator, "BackgroundColor3", t.Border, 0.30)
    TweenColor(self.SettingsPanel, "BackgroundColor3", t.Background, 0.30)

    local accent = self._accentOverride or t.Accent
    if self._pillStroke then self._pillStroke.Color = accent end

    if self.FloatingPill then
        TweenColor(self.FloatingPill, "BackgroundColor3", t.Background, 0.30)
        TweenColor(self._pillLabel, "TextColor3", t.TextPrimary, 0.30)
        TweenColor(self._pillDot, "BackgroundColor3", accent, 0.30)
    end

    if self._gearRefs then
        for _, p in ipairs(self._gearRefs.parts) do
            TweenColor(p, "BackgroundColor3", t.TextSecondary, 0.30)
        end
        TweenColor(self._gearRefs.hole, "BackgroundColor3", t.Background, 0.30)
    end

    if self._backArrowLbl then
        TweenColor(self._backArrowLbl, "TextColor3", t.TextSecondary, 0.30)
    end

    for _, g in ipairs(self._gripFrames or {}) do
        TweenColor(g, "BackgroundColor3", t.TextMuted, 0.30)
    end

    for _, tb in ipairs(self.Tabs) do
        local active = (tb == self.ActiveTab)
        local color  = active and t.TabActive or t.TabInactive
        if tb.Label then TweenColor(tb.Label, "TextColor3", color, 0.30) end
        for _, part in ipairs(tb.IconParts or {}) do
            if part:IsA("UIStroke") then
                part.Color = color
            else
                TweenColor(part, "BackgroundColor3", color, 0.30)
            end
        end
    end

    for _, fn in ipairs(self._themeElements) do
        pcall(fn, t)
    end
end

function LucidUI.Window:SetAccent(c)
    self._accentOverride = c
    self.Theme.Accent    = c

    for _, fn in ipairs(self._themeElements) do pcall(fn, self.Theme) end

    if self._pillStroke then self._pillStroke.Color = c end
    if self._pillDot    then TweenColor(self._pillDot, "BackgroundColor3", c, 0.25) end
end

function LucidUI.Window:_registerTheme(fn)
    table.insert(self._themeElements, fn)
end

-- ============================================================
-- Module: 06b_watermark.lua
-- ============================================================
-- ============================================================
-- Module: 06b_watermark.lua
-- ============================================================
--[[
    Watermark — a small floating glass pill in a screen corner.

    Shows the hub name plus a live FPS counter. Draggable, theme-aware,
    saves its config. Independent of the main window, so it stays
    visible even when the window is hidden or minimized to pill.

    [IMPROVEMENT] Fixed the fpsLabel.TextColor3:match crash bug.
    Added GetWatermark, SetPosition. FPS color now uses a smooth
    red→yellow→green gradient.

    [FIX] The highlight (top sheen) layer now re-tints with the
    theme. Previously it was hardcoded to Color3.fromRGB(255,255,255)
    which made it invisible against Light / Catppuccin Latte
    backgrounds. Now it uses theme.TextPrimary.
]]

LucidUI.Watermark = {}
LucidUI.Watermark.__index = LucidUI.Watermark

local WM_POSITIONS = {
    ["top-left"]     = { x = UDim.new(0, 12),  y = UDim.new(0, 12),  ax = 0, ay = 0 },
    ["top-right"]    = { x = UDim.new(1, -12), y = UDim.new(0, 12),  ax = 1, ay = 0 },
    ["bottom-left"]  = { x = UDim.new(0, 12),  y = UDim.new(1, -12), ax = 0, ay = 1 },
    ["bottom-right"] = { x = UDim.new(1, -12), y = UDim.new(1, -12), ax = 1, ay = 1 },
}

local function mkCorner(radius, parent)
    return Create("UICorner", { CornerRadius = UDim.new(0, radius), Parent = parent })
end

local function mkStroke(color, thickness, transparency, parent)
    return Create("UIStroke", {
        Color = color,
        Thickness = thickness or 1,
        Transparency = transparency or 0.5,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Parent = parent,
    })
end

-- [IMPROVEMENT] Smooth FPS color gradient.
local function fpsColor(fps)
    if fps >= 60 then
        return Color3.fromRGB(120, 210, 140)
    elseif fps >= 30 then
        local t = (fps - 30) / 30 -- 0 at 30fps, 1 at 60fps
        return Color3.new(1, 0.5 + 0.4 * t, 0.3 * t)
    else
        return Color3.fromRGB(255, 95, 87)
    end
end

function LucidUI.Window:SetWatermark(config)
    config = config or {}

    if self._watermark then
        pcall(function() self._watermark:Destroy() end)
        self._watermark = nil
    end

    local theme = self.Theme
    local W = setmetatable({}, LucidUI.Watermark)
    W.Window = self

    W._text      = config.Text or self.Name
    W._showFPS   = config.ShowFPS ~= false
    W._showDot   = config.ShowDot ~= false
    W._position  = config.Position or "top-left"
    W._draggable = config.Draggable ~= false
    W._color     = config.Color
    W._visible   = true

    W.Gui = Create("ScreenGui", {
        Name = "LucidUI_Watermark_" .. self.Name,
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = 150,
        Enabled = true,
        Parent = PlayerGui,
    })
    self._watermarkGui = W.Gui

    local preset = WM_POSITIONS[W._position] or WM_POSITIONS["top-left"]

    local pill = Create("Frame", {
        Name = "Watermark",
        Size = UDim2.fromOffset(160, 28),
        Position = UDim2.new(preset.x.Scale, preset.x.Offset, preset.y.Scale, preset.y.Offset),
        AnchorPoint = Vector2.new(preset.ax, preset.ay),
        BackgroundColor3 = theme.Background,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = W.Gui,
    })
    mkCorner(14, pill)
    local pillStroke = mkStroke(theme.Border, 1, 0.55, pill)
    W.Pill = pill
    W.Stroke = pillStroke

    local highlight = Create("Frame", {
        Size = UDim2.fromScale(1, 0.5),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 0.88,
        BorderSizePixel = 0,
        ZIndex = 3,
        Parent = pill,
    })
    mkCorner(14, highlight)
    Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Rotation = 90,
        Parent = highlight,
    })
    W.Highlight = highlight

    local dot
    if W._showDot then
        dot = Create("Frame", {
            Size = UDim2.fromOffset(7, 7),
            Position = UDim2.new(0, 12, 0.5, -3.5),
            BackgroundColor3 = W._color or theme.Accent,
            BorderSizePixel = 0,
            ZIndex = 5,
            Parent = pill,
        })
        mkCorner(999, dot)
        W.Dot = dot
    end

    local textX = W._showDot and 26 or 14

    local nameLabel = Create("TextLabel", {
        Text = W._text,
        Font = Enum.Font.GothamBold,
        TextSize = 12,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Position = UDim2.fromOffset(textX, 0),
        Size = UDim2.new(1, -(textX + 60), 1, 0),
        ZIndex = 4,
        Parent = pill,
    })
    W.NameLabel = nameLabel

    local fpsLabel
    if W._showFPS then
        fpsLabel = Create("TextLabel", {
            Text = "60",
            Font = Enum.Font.GothamBold,
            TextSize = 11,
            TextColor3 = theme.TextMuted,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Right,
            Position = UDim2.new(1, -10, 0, 0),
            AnchorPoint = Vector2.new(1, 0),
            Size = UDim2.fromOffset(48, 28),
            ZIndex = 4,
            Parent = pill,
        })
        W.FPSLabel = fpsLabel
    end

    local function resize()
        local namePx = TextService:GetTextSize(
            nameLabel.Text, 12, Enum.Font.GothamBold, Vector2.new(400, 28)
        ).X
        local fpsPx = fpsLabel and TextService:GetTextSize(
            fpsLabel.Text, 11, Enum.Font.GothamBold, Vector2.new(200, 28)
        ).X or 0

        local leftPad  = W._showDot and 26 or 14
        local rightPad = 10
        local gap      = 10

        local total = leftPad + namePx + (fpsPx > 0 and (gap + fpsPx) or 0) + rightPad
        total = math.clamp(total, 100, 320)

        TweenService:Create(pill, TweenInfo.new(0.20, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            { Size = UDim2.fromOffset(total, 28) }):Play()
    end
    resize()
    W._resize = resize

    -- FPS counter
    if W._showFPS then
        local frameCount = 0
        local lastUpdate = tick()

        W._fpsConn = RunService.RenderStepped:Connect(function()
            if not pill.Parent then return end
            frameCount = frameCount + 1
            local now = tick()
            if now - lastUpdate >= 0.5 then
                local fps = math.floor(frameCount / (now - lastUpdate) + 0.5)
                frameCount = 0
                lastUpdate = now
                fpsLabel.Text = tostring(fps)
                fpsLabel.TextColor3 = fpsColor(fps)
                resize()
            end
        end)
    end

    -- Dot pulse
    if W._showDot then
        task.spawn(function()
            while W.Dot and W.Dot.Parent do
                local t = tick()
                local pulse = 0.5 + 0.5 * math.sin(t * 3)
                W.Dot.BackgroundTransparency = pulse * 0.35
                task.wait(0.03)
            end
        end)
    end

    -- Drag
    if W._draggable then
        local dragging, startPos, startWindowPos, dragInput = false, nil, nil, nil

        W._dragChangeConn = UserInputService.InputChanged:Connect(function(input)
            if not dragging or input ~= dragInput then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            local d = input.Position - startPos
            pill.Position = UDim2.new(
                startWindowPos.X.Scale, startWindowPos.X.Offset + d.X,
                startWindowPos.Y.Scale, startWindowPos.Y.Offset + d.Y
            )
        end)

        W._dragEndConn = UserInputService.InputEnded:Connect(function(input)
            if input ~= dragInput then return end
            dragging  = false
            dragInput = nil

            local vp   = workspace.CurrentCamera.ViewportSize
            local pos  = pill.AbsolutePosition
            local size = pill.AbsoluteSize
            local nx = math.clamp(pos.X, 0, math.max(vp.X - size.X, 0))
            local ny = math.clamp(pos.Y, 0, math.max(vp.Y - size.Y, 0))
            pill.Position = UDim2.fromOffset(nx, ny)
        end)

        pill.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            dragging       = true
            dragInput      = input
            startPos       = input.Position
            startWindowPos = pill.Position
            pill.AnchorPoint = Vector2.new(0, 0)
        end)
    end

    -- Theme registration
    self:_registerTheme(function(t)
        if not pill.Parent then return end
        pill.BackgroundColor3 = t.Background
        pillStroke.Color      = t.Border
        nameLabel.TextColor3  = t.TextPrimary
        if W.Dot then W.Dot.BackgroundColor3 = W._color or t.Accent end
        -- [FIX] Re-tint the sheen layer so it doesn't stay hardcoded
        -- white. On Light / Latte themes, white-on-white made the
        -- highlight completely invisible.
        if W.Highlight and W.Highlight.Parent then
            W.Highlight.BackgroundColor3 = t.TextPrimary
        end
    end)

    -- Public methods
    function W:Set(text)
        W._text = tostring(text)
        nameLabel.Text = W._text
        W._resize()
    end

    function W:SetFPS(on)
        W._showFPS = on and true or false
        if fpsLabel then
            fpsLabel.Visible = W._showFPS
            W._resize()
        end
    end

    function W:SetVisible(on)
        W._visible = on and true or false
        W.Gui.Enabled = W._visible
    end

    function W:SetColor(c)
        W._color = c
        if W.Dot then W.Dot.BackgroundColor3 = c or self.Theme.Accent end
    end

    -- [IMPROVEMENT] Change position preset at runtime.
    function W:SetPosition(presetName)
        local p = WM_POSITIONS[presetName]
        if not p then return false end
        W._position = presetName
        pill.AnchorPoint = Vector2.new(p.ax, p.ay)
        pill.Position = UDim2.new(p.x.Scale, p.x.Offset, p.y.Scale, p.y.Offset)
        return true
    end

    function W:Destroy()
        if W._fpsConn      then pcall(function() W._fpsConn:Disconnect()      end) end
        if W._dragChangeConn then pcall(function() W._dragChangeConn:Disconnect() end) end
        if W._dragEndConn  then pcall(function() W._dragEndConn:Disconnect()  end) end
        W._fpsConn, W._dragChangeConn, W._dragEndConn = nil, nil, nil

        if W.Gui then
            pcall(function() W.Gui:Destroy() end)
            W.Gui = nil
        end
        if self._watermark == W then
            self._watermark = nil
            self._watermarkGui = nil
        end
    end

    W._configSnapshot = function()
        return {
            text     = W._text,
            showFPS  = W._showFPS,
            showDot  = W._showDot,
            position = W._position,
            px = pill.Position.X.Scale, py = pill.Position.Y.Scale,
            pxo = pill.Position.X.Offset, pyo = pill.Position.Y.Offset,
            ax = pill.AnchorPoint.X, ay = pill.AnchorPoint.Y,
        }
    end

    function W:RestoreFrom(saved)
        if type(saved) ~= "table" then return end
        if saved.text then W:Set(saved.text) end
        if saved.showFPS ~= nil then W:SetFPS(saved.showFPS) end
        if saved.showDot ~= nil then
            W._showDot = saved.showDot
            if W.Dot then W.Dot.Visible = saved.showDot end
        end
        if saved.px ~= nil then
            pill.Position = UDim2.new(saved.px, saved.pxo or 0, saved.py, saved.pyo or 0)
            pill.AnchorPoint = Vector2.new(saved.ax or 0, saved.ay or 0)
        end
    end

    self._watermark = W
    return W
end

function LucidUI.Window:ToggleWatermark()
    if self._watermark then
        self._watermark:SetVisible(not self._watermark._visible)
    else
        self:SetWatermark({
            Text = self.Name,
            ShowFPS = true,
        })
    end
end

function LucidUI.Window:RemoveWatermark()
    if self._watermark then
        self._watermark:Destroy()
    end
end

-- [IMPROVEMENT] Fetch the current watermark object.
function LucidUI.Window:GetWatermark()
    return self._watermark
end

-- ============================================================
-- Module: 06c_docking.lua
-- ============================================================
-- ============================================================
-- Module: 06c_docking.lua
-- ============================================================
--[[
    Docking — snap the window to screen edges and corners.

    OPT-IN: Enabled only when the user passes `Docking = true` to
    CreateWindow. Default is OFF for a cleaner mobile experience.

    During a header drag, if the window's bounds come within
    `DockThreshold` pixels of a screen edge, a preview rectangle
    shows where it will land on release. Eight zones: left, right,
    top, bottom, and the four corners.

    Releasing inside a zone tweens the window into place. A "FLOAT"
    button appears in the header so mobile users can undock by
    tapping it (or by starting a new drag).

    [IMPROVEMENT] Uses GuiService.TopbarInset for safe area, self.Gui
    size for accurate bounds, opt-in only, all connections tracked,
    FLOAT button for mobile users.

    [FIX] The top-edge detection threshold now matches the top snap
    position. Previously _computeDockZone used `thr + topInset` while
    _dockRect used `m + topInset`. With defaults (thr=30, m=12), the
    top hitbox extended 18px higher than where the window actually
    snapped — a preview would appear, then the window would jump
    lower than the preview suggested. Now both use `_dockMargin`.
]]

local GuiService = game:GetService("GuiService")

local DOCK_ZONES = {
    ["left"]         = true,
    ["right"]        = true,
    ["top"]          = true,
    ["bottom"]       = true,
    ["top-left"]     = true,
    ["top-right"]    = true,
    ["bottom-left"]  = true,
    ["bottom-right"] = true,
}

-- ============================================================
-- Init
-- ============================================================
function LucidUI.Window:_initDocking(config)
    if self._dockingInitialized then return end
    self._dockingInitialized = true

    config = config or {}

    self._dockEnabled   = config.Docking == true -- [IMPROVEMENT] opt-in
    self._dockThreshold = config.DockThreshold or 30
    self._dockMargin    = config.DockMargin    or 12
    self._dockSnapTime  = config.DockSnapTime  or 0.25

    self._docked          = nil
    self._preDockSnapshot = nil
    self._hoverDock       = nil

    -- Preview rectangle
    local preview = Create("Frame", {
        Name = "DockPreview",
        BackgroundColor3 = self.Theme.Accent,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 50,
        Parent = self.Gui,
    })
    Corner(18, preview)
    local previewStroke = Stroke(self.Theme.Accent, 2, 1, preview)

    self._dockPreview = preview
    self._dockPreviewStroke = previewStroke

    -- FLOAT undock button (mobile-friendly)
    local undockBtn = Create("TextButton", {
        Name = "UndockButton",
        Text = "FLOAT",
        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = self.Theme.TextPrimary,
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = 0.3,
        AutoButtonColor = false,
        Size = UDim2.fromOffset(60, 28),
        Position = UDim2.new(1, -70, 0.5, -14),
        Visible = false,
        ZIndex = 10,
        Parent = self.Header,
    })
    Corner(8, undockBtn)

    BindTap(undockBtn, function()
        self:Undock()
    end)

    undockBtn.MouseEnter:Connect(function()
        Tween(undockBtn, 0.15, {
            BackgroundTransparency = 0.1,
            TextColor3 = self.Theme.Accent,
        }):Play()
    end)
    undockBtn.MouseLeave:Connect(function()
        Tween(undockBtn, 0.15, {
            BackgroundTransparency = 0.3,
            TextColor3 = self.Theme.TextPrimary,
        }):Play()
    end)

    self._undockBtn = undockBtn

    self:_registerTheme(function(t)
        preview.BackgroundColor3     = t.Accent
        previewStroke.Color          = t.Accent
        undockBtn.BackgroundColor3   = t.Surface
        undockBtn.TextColor3         = t.TextPrimary
    end)
end

-- ============================================================
-- Zone math
-- ============================================================
function LucidUI.Window:_computeDockZone()
    local scrW = self.Gui.AbsoluteSize.X
    local scrH = self.Gui.AbsoluteSize.Y
    local pos  = self.Main.AbsolutePosition
    local size = self.Main.AbsoluteSize
    local thr  = self._dockThreshold
    local m    = self._dockMargin or 12
    local topInset = GuiService.TopbarInset.Height

    local nearLeft   = pos.X <= thr
    local nearRight  = pos.X + size.X >= scrW - thr
    -- [FIX] Use _dockMargin for the top threshold so the hitbox
    -- matches where _dockRect actually snaps the window. Previously
    -- used `thr` (default 30), which extended 18px past the snap
    -- line (default 12), causing the preview to appear higher than
    -- the resulting position.
    local nearTop    = pos.Y <= m + topInset
    local nearBottom = pos.Y + size.Y >= scrH - thr

    if nearTop and nearLeft     then return "top-left"     end
    if nearTop and nearRight    then return "top-right"    end
    if nearBottom and nearLeft  then return "bottom-left"  end
    if nearBottom and nearRight then return "bottom-right" end

    if nearLeft   then return "left"   end
    if nearRight  then return "right"  end
    if nearTop    then return "top"    end
    if nearBottom then return "bottom" end

    return nil
end

function LucidUI.Window:_dockRect(zone)
    local scrW = self.Gui.AbsoluteSize.X
    local scrH = self.Gui.AbsoluteSize.Y
    local m  = self._dockMargin
    local topInset = GuiService.TopbarInset.Height

    local safeTop    = m + topInset
    local safeBottom = scrH - m
    local safeLeft   = m
    local safeRight  = scrW - m

    local availW = safeRight - safeLeft
    local availH = safeBottom - safeTop
    local halfW  = availW / 2
    local halfH  = availH / 2

    local map = {
        ["left"]         = { x = safeLeft,             y = safeTop,            w = halfW, h = availH },
        ["right"]        = { x = safeRight - halfW,    y = safeTop,            w = halfW, h = availH },
        ["top"]          = { x = safeLeft,             y = safeTop,            w = availW, h = halfH },
        ["bottom"]       = { x = safeLeft,             y = safeBottom - halfH, w = availW, h = halfH },
        ["top-left"]     = { x = safeLeft,             y = safeTop,            w = halfW, h = halfH },
        ["top-right"]    = { x = safeRight - halfW,    y = safeTop,            w = halfW, h = halfH },
        ["bottom-left"]  = { x = safeLeft,             y = safeBottom - halfH, w = halfW, h = halfH },
        ["bottom-right"] = { x = safeRight - halfW,    y = safeBottom - halfH, w = halfW, h = halfH },
    }
    return map[zone]
end

-- ============================================================
-- Drag hooks
-- ============================================================
function LucidUI.Window:_onBeforeDragStart()
    if not self._docked then return end

    local snap = self._preDockSnapshot
    self._docked = nil
    self._preDockSnapshot = nil

    if snap then
        self.Main.Size = UDim2.fromOffset(snap.width, snap.height)
        -- Intentionally no ClampPosition here so the drag feels smooth.
    end
    if self._undockBtn then self._undockBtn.Visible = false end
end

function LucidUI.Window:_onDragTick()
    if not self._dockEnabled then return end

    local zone = self:_computeDockZone()
    self._hoverDock = zone

    local preview = self._dockPreview
    if not preview then return end

    if zone then
        local rect = self:_dockRect(zone)
        preview.Position = UDim2.fromOffset(rect.x, rect.y)
        preview.Size     = UDim2.fromOffset(rect.w, rect.h)
        preview.Visible  = true
        pcall(function()
            TweenService:Create(preview, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                { BackgroundTransparency = 0.72 }):Play()
            TweenService:Create(self._dockPreviewStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                { Transparency = 0.15 }):Play()
        end)
    else
        pcall(function()
            TweenService:Create(preview, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                { BackgroundTransparency = 1 }):Play()
            TweenService:Create(self._dockPreviewStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                { Transparency = 1 }):Play()
        end)

        task.delay(0.16, function()
            if preview and preview.Parent and not self._hoverDock then
                preview.Visible = false
            end
        end)
    end
end

function LucidUI.Window:_onDragEnd()
    local preview = self._dockPreview
    if preview then
        preview.Visible = false
        preview.BackgroundTransparency = 1
    end

    if not self._dockEnabled then return end

    local zone = self._hoverDock
    self._hoverDock = nil

    if zone and DOCK_ZONES[zone] then
        self:DockTo(zone)
    end
end

-- ============================================================
-- Public API
-- ============================================================
function LucidUI.Window:DockTo(zone, instant)
    if not DOCK_ZONES[zone] then return false end
    if self.Minimized then return false end

    local rect = self:_dockRect(zone)
    if not rect then return false end

    if not self._preDockSnapshot then
        self._preDockSnapshot = {
            width  = self._width,
            height = self._height,
        }
    end

    self._docked = zone
    if self._undockBtn then self._undockBtn.Visible = true end

    local info = instant
        and TweenInfo.new(0)
        or  TweenInfo.new(self._dockSnapTime, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

    pcall(function()
        TweenService:Create(self.Main, info, {
            Size     = UDim2.fromOffset(rect.w, rect.h),
            Position = UDim2.fromOffset(rect.x, rect.y),
        }):Play()
    end)

    return true
end

function LucidUI.Window:Undock(instant)
    if not self._docked then return end
    self._docked = nil
    if self._undockBtn then self._undockBtn.Visible = false end

    local snap = self._preDockSnapshot
    self._preDockSnapshot = nil

    if not snap then return end

    local info = instant
        and TweenInfo.new(0)
        or  TweenInfo.new(self._dockSnapTime, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

    local scrW = self.Gui.AbsoluteSize.X
    local scrH = self.Gui.AbsoluteSize.Y
    local targetX = math.max((scrW - snap.width) / 2, 0)
    local targetY = math.max((scrH - snap.height) / 2, 0)

    pcall(function()
        TweenService:Create(self.Main, info, {
            Size     = UDim2.fromOffset(snap.width, snap.height),
            Position = UDim2.fromOffset(targetX, targetY),
        }):Play()
    end)

    task.delay(self._dockSnapTime + 0.05, function()
        pcall(function() ClampPosition(self.Main) end)
    end)
end

function LucidUI.Window:SetDocking(enabled)
    self._dockEnabled = enabled and true or false
    if not self._dockEnabled and self._docked then
        self:Undock()
    end
    if not self._dockEnabled and self._dockPreview then
        self._dockPreview.Visible = false
    end
end

function LucidUI.Window:GetDockZone()
    return self._docked
end

-- [IMPROVEMENT] Convenience boolean check.
function LucidUI.Window:IsDocked()
    return self._docked ~= nil
end

-- ============================================================
-- Module: 06d_floatingbutton.lua
-- ============================================================
-- ============================================================
-- Module: 06d_floatingbutton.lua
-- ============================================================
--[[
    Floating Button — a draggable, always-visible button that
    survives window minimize/pill/hide.

    Also provides CreateFlagButton — a floating button linked to
    an existing UI element that auto-syncs state and appearance.

    [FIX] Badge pulse loop was an infinite no-op (set static values,
    did nothing). Now it actually breathes.

    [NEW] CreateFlagButton — see the section near the bottom.
]]

LucidUI.FloatingButton = {}
LucidUI.FloatingButton.__index = LucidUI.FloatingButton

-- ============================================================
-- Internals
-- ============================================================
local function clamp(v, lo, hi)
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function lightenColor(c, amount)
    return Color3.new(
        math.min(c.R + amount, 1),
        math.min(c.G + amount, 1),
        math.min(c.B + amount, 1)
    )
end

local function buildButtonInstance(cfg, parentGui)
    local wrap = Create("Frame", {
        Name = "FloatingButtonWrap",
        BackgroundTransparency = 1,
        Size = cfg.Size or UDim2.fromOffset(52, 52),
        Position = cfg.Position or UDim2.new(0, 20, 0.5, -26),
        AnchorPoint = cfg.AnchorPoint or Vector2.new(0, 0),
        ZIndex = cfg.ZIndex or 10,
        Parent = parentGui,
    })

    local btn = Create("TextButton", {
        Name = "FloatingButton",
        Text = "",
        BackgroundColor3 = cfg.Color or Color3.fromRGB(30, 28, 45),
        BackgroundTransparency = 0.1,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 11,
        Parent = wrap,
    })
    Corner(cfg.CornerRadius or 14, btn)

    local outerStroke = Stroke(Color3.fromRGB(0, 0, 0), 3, 0.4, btn)
    local innerStroke = Stroke(cfg.Color or Color3.fromRGB(130, 80, 255), 1.4, 0.15, btn)

    local iconLbl
    if cfg.Icon and cfg.Icon ~= "" then
        iconLbl = Create("ImageLabel", {
            Size = UDim2.new(0.7, 0, 0.7, 0),
            Position = UDim2.fromScale(0.15, 0.15),
            BackgroundTransparency = 1,
            Image = cfg.Icon,
            ScaleType = Enum.ScaleType.Fit,
            ZIndex = 12,
            Parent = btn,
        })
    else
        iconLbl = Create("TextLabel", {
            Text = cfg.Text or "•",
            Font = Enum.Font.GothamBold,
            TextSize = cfg.TextSize or 12,
            TextColor3 = Color3.fromRGB(240, 238, 255),
            BackgroundTransparency = 1,
            TextWrapped = true,
            Size = UDim2.new(1, -8, 1, -8),
            Position = UDim2.fromOffset(4, 4),
            ZIndex = 12,
            Parent = btn,
        })
    end

    local badge
    if cfg.Badge then
        badge = Create("Frame", {
            Name = "Badge",
            Size = UDim2.fromOffset(10, 10),
            Position = UDim2.new(1, -4, 0, -4),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = cfg.BadgeColor or Color3.fromRGB(255, 95, 87),
            BorderSizePixel = 0,
            ZIndex = 13,
            Parent = btn,
        })
        Corner(999, badge)
        Stroke(Color3.fromRGB(0, 0, 0), 1.5, 0.4, badge)

        task.spawn(function()
            local BASE_SIZE = 10
            local PULSE_AMPLITUDE = 3
            while badge and badge.Parent do
                local t = tick()
                local pulse = 0.5 + 0.5 * math.sin(t * 3)
                local size = BASE_SIZE + pulse * PULSE_AMPLITUDE
                badge.Size = UDim2.fromOffset(size, size)
                badge.BackgroundTransparency = pulse * 0.35
                task.wait(0.03)
            end
        end)
    end

    return wrap, btn, iconLbl, outerStroke, innerStroke, badge
end

local function buildTooltip(parentGui, text)
    local tip = Create("Frame", {
        Name = "FloatingButtonTooltip",
        Size = UDim2.fromOffset(0, 24),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundColor3 = Color3.fromRGB(20, 20, 28),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,
        ZIndex = 20,
        Parent = parentGui,
    })
    Corner(6, tip)
    Stroke(Color3.fromRGB(130, 80, 255), 1, 0.5, tip)

    local lbl = Create("TextLabel", {
        Text = text,
        Font = Enum.Font.GothamMedium,
        TextSize = 12,
        TextColor3 = Color3.fromRGB(240, 238, 255),
        BackgroundTransparency = 1,
        Size = UDim2.new(0, 0, 1, 0),
        AutomaticSize = Enum.AutomaticSize.X,
        ZIndex = 21,
        Parent = tip,
    })
    Create("UIPadding", {
        PaddingLeft = UDim.new(0, 10),
        PaddingRight = UDim.new(0, 10),
        Parent = lbl,
    })

    return tip, lbl
end

-- ============================================================
-- Public: CreateFloatingButton
-- ============================================================
function LucidUI:CreateFloatingButton(cfg)
    cfg = cfg or {}

    local gui = Create("ScreenGui", {
        Name = "LucidUI_FloatingButton_" .. tostring(math.floor(tick() * 1000) % 100000),
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = cfg.DisplayOrder or 500,
        Parent = PlayerGui,
    })

    local wrap, btn, iconLbl, outerStroke, innerStroke, badge =
        buildButtonInstance(cfg, gui)

    local tipFrame, tipLabel
    if cfg.Tooltip and cfg.Tooltip ~= "" then
        tipFrame, tipLabel = buildTooltip(gui, cfg.Tooltip)
    end

    local obj = setmetatable({}, LucidUI.FloatingButton)

    obj.Gui      = gui
    obj.Wrap     = wrap
    obj.Button   = btn
    obj.Icon     = iconLbl
    obj.OuterStroke = outerStroke
    obj.InnerStroke = innerStroke
    obj.Badge    = badge
    obj.TooltipFrame = tipFrame
    obj.TooltipLabel = tipLabel
    obj.Window   = cfg.Window
    obj._cfg     = cfg
    obj._visible = true
    obj._conns   = {}

    local theme = (cfg.Window and cfg.Window.Theme)
              or LucidUI._lastTheme
              or LucidUI.Themes.Default
    obj.Theme = theme

    local accent = cfg.Color or theme.Accent
    obj._accent = accent

    innerStroke.Color = accent
    if badge then badge.BackgroundColor3 = cfg.BadgeColor or accent end

    btn.MouseEnter:Connect(function()
        Tween(btn, 0.15, {
            BackgroundColor3 = cfg.HoverColor or lightenColor(accent, 0.15),
        }):Play()
        Tween(innerStroke, 0.15, { Transparency = 0.0 }):Play()
        if tipFrame and tipLabel then
            tipFrame.Position = UDim2.new(
                wrap.Position.X.Scale,
                wrap.Position.X.Offset + wrap.AbsoluteSize.X + 8,
                wrap.Position.Y.Scale,
                wrap.Position.Y.Offset + (wrap.AbsoluteSize.Y - 24) / 2
            )
            tipFrame.Visible = true
            tipFrame.BackgroundTransparency = 1
            tipLabel.TextTransparency = 1
            Tween(tipFrame, 0.15, { BackgroundTransparency = 0.1 }):Play()
            Tween(tipLabel, 0.15, { TextTransparency = 0 }):Play()
        end
    end)
    btn.MouseLeave:Connect(function()
        Tween(btn, 0.20, {
            BackgroundColor3 = cfg.Color or theme.Background or Color3.fromRGB(30, 28, 45),
        }):Play()
        Tween(innerStroke, 0.20, { Transparency = 0.15 }):Play()
        if tipFrame then
            Tween(tipFrame, 0.12, { BackgroundTransparency = 1 }):Play()
            if tipLabel then Tween(tipLabel, 0.12, { TextTransparency = 1 }):Play() end
            task.delay(0.15, function()
                if tipFrame and tipFrame.Parent then tipFrame.Visible = false end
            end)
        end
    end)

    local pressStartSize = wrap.Size
    btn.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        Tween(wrap, 0.08, {
            Size = UDim2.new(
                pressStartSize.X.Scale * 0.94, pressStartSize.X.Offset,
                pressStartSize.Y.Scale * 0.94, pressStartSize.Y.Offset
            ),
        }):Play()
    end)
    btn.InputEnded:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        Tween(wrap, 0.15, { Size = pressStartSize }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
    end)

    if cfg.Draggable ~= false then
        local dragging, dragStart, startPos, moved, dragInput
        local MOVE_THRESHOLD = 6

        btn.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            dragging  = true
            moved     = false
            dragStart = input.Position
            startPos  = wrap.Position
            dragInput = input
        end)

        local dragConn = UserInputService.InputChanged:Connect(function(input)
            if not dragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            if input ~= dragInput then return end

            local delta = input.Position - dragStart
            if math.abs(delta.X) > MOVE_THRESHOLD or math.abs(delta.Y) > MOVE_THRESHOLD then
                moved = true
                wrap.AnchorPoint = Vector2.new(0, 0)
                wrap.Position = UDim2.new(
                    startPos.X.Scale, startPos.X.Offset + delta.X,
                    startPos.Y.Scale, startPos.Y.Offset + delta.Y
                )
            end
        end)
        table.insert(obj._conns, dragConn)

        local endConn = UserInputService.InputEnded:Connect(function(input)
            if input ~= dragInput then return end
            dragging = false
            dragInput = nil

            if moved and cfg.SnapToEdge then
                local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
                          or Vector2.new(1920, 1080)
                local margin = cfg.SnapMargin or 12
                local curX = wrap.AbsolutePosition.X
                local curY = wrap.AbsolutePosition.Y
                local w    = wrap.AbsoluteSize.X
                local h    = wrap.AbsoluteSize.Y

                local distLeft  = curX
                local distRight = vp.X - (curX + w)
                local targetX

                if distLeft < distRight then
                    targetX = margin
                else
                    targetX = vp.X - w - margin
                end

                local targetY = clamp(curY, margin, vp.Y - h - margin)

                Tween(wrap, 0.22, {
                    Position = UDim2.fromOffset(targetX, targetY),
                }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
            end

            if not moved then
                PlayUISound("click")
                if cfg.OnClick then Compat.safeCallback(cfg.OnClick) end
            end
        end)
        table.insert(obj._conns, endConn)
    else
        BindTap(btn, function()
            PlayUISound("click")
            if cfg.OnClick then Compat.safeCallback(cfg.OnClick) end
        end)
    end

    if cfg.OnRightClick then
        btn.MouseButton2Click:Connect(function()
            Compat.safeCallback(cfg.OnRightClick)
        end)
    end

    if cfg.Window and cfg.HideWhenVisible then
        local function syncVisibility()
            local w = obj.Window
            if not w or not w.Gui then return end
            local isOpen = w.Gui.Enabled and w.Main and w.Main.Visible and not w.Floating
            if isOpen then
                obj:Hide()
            else
                obj:Show()
            end
        end

        if cfg.Window.Main then
            table.insert(cfg.Window._conns, cfg.Window.Main:GetPropertyChangedSignal("Visible"):Connect(syncVisibility))
        end
        if cfg.Window.Gui then
            table.insert(cfg.Window._conns, cfg.Window.Gui:GetPropertyChangedSignal("Enabled"):Connect(syncVisibility))
        end
        task.defer(syncVisibility)
    end

    local function applyTheme(t)
        obj.Theme = t
        local c = cfg.Color or t.Accent
        obj._accent = c
        innerStroke.Color = c
        if cfg.Icon then
            -- nothing to retint on images
        else
            if iconLbl and iconLbl:IsA("TextLabel") then
                iconLbl.TextColor3 = t.TextPrimary
            end
        end
        if badge then badge.BackgroundColor3 = cfg.BadgeColor or c end
    end

    if cfg.Window then
        cfg.Window:_registerTheme(applyTheme)
    end

    function obj:Show()
        if self._visible then return end
        self._visible = true
        self.Gui.Enabled = true
        self.Wrap.Visible = true
    end

    function obj:Hide()
        if not self._visible then return end
        self._visible = false
        self.Gui.Enabled = false
    end

    function obj:SetVisible(v)
        if v then self:Show() else self:Hide() end
    end

    function obj:SetPosition(udim2)
        self.Wrap.Position = udim2
    end

    function obj:SetIcon(id)
        if iconLbl and iconLbl:IsA("ImageLabel") then
            iconLbl.Image = id
        end
    end

    function obj:SetText(text)
        if iconLbl and iconLbl:IsA("TextLabel") then
            iconLbl.Text = tostring(text)
        end
    end

    function obj:SetColor(c)
        self._accent = c
        self.InnerStroke.Color = c
        if self.Badge then self.Badge.BackgroundColor3 = c end
    end

    function obj:SetBadge(on)
        if on and not self.Badge then
            local b = Create("Frame", {
                Name = "Badge",
                Size = UDim2.fromOffset(10, 10),
                Position = UDim2.new(1, -4, 0, -4),
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = cfg.BadgeColor or self._accent,
                BorderSizePixel = 0,
                ZIndex = 13,
                Parent = self.Button,
            })
            Corner(999, b)
            self.Badge = b

            task.spawn(function()
                local BASE_SIZE = 10
                local PULSE_AMPLITUDE = 3
                while b and b.Parent do
                    local t = tick()
                    local pulse = 0.5 + 0.5 * math.sin(t * 3)
                    local size = BASE_SIZE + pulse * PULSE_AMPLITUDE
                    b.Size = UDim2.fromOffset(size, size)
                    b.BackgroundTransparency = pulse * 0.35
                    task.wait(0.03)
                end
            end)
        elseif not on and self.Badge then
            pcall(function() self.Badge:Destroy() end)
            self.Badge = nil
        end
    end

    function obj:Destroy()
        if self._conns then
            for _, c in ipairs(self._conns) do
                if typeof(c) == "RBXScriptConnection" then
                    pcall(function() c:Disconnect() end)
                end
            end
            self._conns = {}
        end
        if self.Gui then
            pcall(function() self.Gui:Destroy() end)
            self.Gui = nil
        end
    end

    LucidUI._floatingButtons = LucidUI._floatingButtons or {}
    table.insert(LucidUI._floatingButtons, obj)

    return obj
end

-- ============================================================
-- Window-scoped wrapper
-- ============================================================
function LucidUI.Window:CreateFloatingButton(cfg)
    cfg = cfg or {}
    cfg.Window = self
    return LucidUI:CreateFloatingButton(cfg)
end

-- ============================================================
-- Flag Button — floating button linked to an existing element
-- ============================================================
--[[
    Creates a floating button that mirrors and controls an existing
    UI element (Toggle, Checkbox, Slider, Dropdown, Keybind, etc.).

    How it behaves per element type:
        boolean   → click toggles it. Button color signals state.
        number    → click cycles through Snapshots (if provided).
                    Otherwise display-only.
        string    → click cycles through CycleOptions (if provided).
                    Otherwise display-only.
        Color3    → display-only (shows "COLOR" or config.Text)
        EnumItem  → display-only (shows key name)
        table     → display-only (shows count of truthy values)

    Two-way sync: any change to the element — whether it came from
    the flag button itself, the settings panel, a LoadConfig call,
    or dev mode — is reflected back on the button within ~100 ms
    via a lightweight poll.

    For boolean toggles, note that the element's own Callback does
    NOT fire on programmatic Set (this is intentional in the base
    library to avoid double-fires on config load). If your feature
    needs to react to the flag button's click, pass OnToggle — it
    fires with the new value every time the button is pressed.

    Usage:
        local aimToggle = Combat:CreateToggle({
            Name = "Aim Assist", Flag = "aim",
            Callback = function(v) StartAim(v) end,
        })

        LucidUI:CreateFlagButton(aimToggle, {
            Text     = "AIM",
            Position = UDim2.new(1, -90, 0.4, 0),
            OnToggle = function(newValue)
                StartAim(newValue)
            end,
        })

    Options:
        Text, Position, Size, CornerRadius, Color, HoverColor
        Icon, Tooltip, SnapToEdge, SnapMargin, Draggable, DisplayOrder
            — same as CreateFloatingButton

        OnText, OffText     — custom labels for boolean states
                              (default: label text with color change only)
        Suffix              — appended to numbers ("%", "s", etc.)
        OnColor, OffColor   — button tint for active/inactive
        Interactive         — force click behavior on/off
                              (auto-detected by default)
        Snapshots           — numeric values to cycle through
                              e.g. { 16, 50, 100, 200 }
        CycleOptions        — string values to cycle through
                              e.g. { "Off", "Low", "High" }
        OnToggle            — callback(newValue) fired on each click
        OnClick             — callback() fired when non-interactive
        OnRightClick        — same as CreateFloatingButton
        Window, HideWhenVisible — same as CreateFloatingButton
]]

local function flagValuesEqual(a, b)
    if type(a) ~= type(b) then return false end
    if type(a) ~= "table" then return a == b end
    -- Tables are mutated in place, so reference equality isn't
    -- enough. Compare contents both ways.
    for k, v in pairs(a) do
        if b[k] ~= v then return false end
    end
    for k, v in pairs(b) do
        if a[k] ~= v then return false end
    end
    return true
end

function LucidUI:CreateFlagButton(element, config)
    config = config or {}

    if not element or type(element.Get) ~= "function" then
        warn("[LucidUI] CreateFlagButton: element must have a Get() method")
        return nil
    end

    local okGet, initial = pcall(function() return element:Get() end)
    if not okGet then
        warn("[LucidUI] CreateFlagButton: element.Get() failed")
        return nil
    end

    local kind = typeof(initial)

    -- Auto-detect interactivity
    local interactive = config.Interactive
    if interactive == nil then
        interactive = (kind == "boolean")
            or (kind == "number" and config.Snapshots)
            or (kind == "string" and config.CycleOptions)
    end

    -- Compute button text and active flag from a raw element value
    local function computeDisplay(value)
        local active = false
        local text   = config.Text or "BTN"

        if kind == "boolean" then
            active = value == true
            if config.OnText or config.OffText then
                text = active and (config.OnText or text) or (config.OffText or text)
            end
            -- else: label text stays put; color signals state

        elseif kind == "number" then
            local n = value or 0
            local nStr = (n == math.floor(n))
                and tostring(math.floor(n))
                or string.format("%.2f", n)
            text = nStr .. (config.Suffix or "")
            if config.Text then text = config.Text .. " " .. text end
            active = n > 0

        elseif kind == "string" then
            local s = tostring(value or "")
            text = (s ~= "" and s or "NONE")
            if config.Text then text = config.Text .. " " .. text end
            active = s ~= "" and s:lower() ~= "none"

        elseif kind == "EnumItem" then
            text = tostring(value.Name)
            active = true

        elseif kind == "Color3" then
            text = config.Text or "COLOR"
            active = true

        elseif kind == "table" then
            local n = 0
            for _, v in pairs(value) do
                if v then n = n + 1 end
            end
            text = tostring(n)
            if config.Text then text = config.Text .. " " .. text end
            active = n > 0
        end

        return text, active
    end

    -- Build the underlying floating button
    local btn = self:CreateFloatingButton({
        Text            = config.Text or "BTN",
        Icon            = config.Icon,
        Position        = config.Position,
        Size            = config.Size,
        CornerRadius    = config.CornerRadius,
        Color           = config.Color,
        HoverColor      = config.HoverColor,
        SnapToEdge      = config.SnapToEdge,
        SnapMargin      = config.SnapMargin,
        Tooltip         = config.Tooltip,
        Draggable       = config.Draggable ~= false,
        DisplayOrder    = config.DisplayOrder,
        Badge           = config.Badge,
        BadgeColor      = config.BadgeColor,
        Window          = config.Window,
        HideWhenVisible = config.HideWhenVisible,

        OnClick = function()
            if not interactive then
                if config.OnClick then Compat.safeCallback(config.OnClick) end
                return
            end

            if kind == "boolean" then
                local newValue = not element:Get()
                element:Set(newValue)
                if config.OnToggle then
                    Compat.safeCallback(config.OnToggle, newValue)
                end

            elseif kind == "number" and config.Snapshots then
                local cur = element:Get()
                local snaps = config.Snapshots
                local idx = 1
                for i, v in ipairs(snaps) do
                    if math.abs(cur - v) < 0.001 then idx = i break end
                end
                idx = (idx % #snaps) + 1
                local nextValue = snaps[idx]
                element:Set(nextValue)
                if config.OnToggle then
                    Compat.safeCallback(config.OnToggle, nextValue)
                end

            elseif kind == "string" and config.CycleOptions then
                local cur = element:Get()
                local opts = config.CycleOptions
                local idx = 1
                for i, v in ipairs(opts) do
                    if v == cur then idx = i break end
                end
                idx = (idx % #opts) + 1
                local nextValue = opts[idx]
                element:Set(nextValue)
                if config.OnToggle then
                    Compat.safeCallback(config.OnToggle, nextValue)
                end
            end
        end,

        OnRightClick = config.OnRightClick,
    })

    if not btn then return nil end

    btn.Element     = element
    btn.Kind        = kind
    btn.Interactive = interactive

    local lastValue  = initial
    local lastAccent = btn.Theme and btn.Theme.Accent

    local function applyState(value)
        local text, active = computeDisplay(value)
        btn:SetText(text)

        local accent   = btn.Theme and btn.Theme.Accent or Color3.fromRGB(130, 80, 255)
        local onColor  = config.OnColor  or accent
        local offColor = config.OffColor or config.Color or Color3.fromRGB(30, 28, 45)

        btn:SetColor(active and onColor or offColor)
        lastAccent = btn.Theme and btn.Theme.Accent
    end

    applyState(initial)

    -- Poll element state at 10 Hz. Also catches theme changes so the
    -- button keeps its active/inactive tint in sync when the user
    -- switches themes at runtime.
    local accum = 0
    local pollConn
    pollConn = RunService.RenderStepped:Connect(function(dt)
        if not btn.Gui or not btn.Gui.Parent then
            pcall(function() pollConn:Disconnect() end)
            return
        end

        accum = accum + dt
        if accum < 0.1 then return end
        accum = 0

        local okNow, current = pcall(function() return element:Get() end)
        if not okNow then
            pcall(function() pollConn:Disconnect() end)
            return
        end

        local themeAccent = btn.Theme and btn.Theme.Accent
        if not flagValuesEqual(current, lastValue) or themeAccent ~= lastAccent then
            lastValue = current
            applyState(current)
        end
    end)
    btn._pollConn = pollConn

    -- Manual re-sync
    function btn:Refresh()
        local okNow, current = pcall(function() return element:Get() end)
        if okNow then
            lastValue = current
            applyState(current)
        end
    end

    function btn:GetElement()
        return element
    end

    -- Wrap Destroy so the poll disconnects with the button
    local origDestroy = btn.Destroy
    btn.Destroy = function(self2, ...)
        if self2._pollConn then
            pcall(function() self2._pollConn:Disconnect() end)
            self2._pollConn = nil
        end
        return origDestroy(self2, ...)
    end

    return btn
end

-- ============================================================
-- Cleanup
-- ============================================================
LucidUI:OnCleanup(function()
    if LucidUI._floatingButtons then
        for _, btn in ipairs(LucidUI._floatingButtons) do
            pcall(function() btn:Destroy() end)
        end
        LucidUI._floatingButtons = {}
    end
    pcall(function()
        if PlayerGui then
            for _, gui in ipairs(PlayerGui:GetChildren()) do
                if gui:IsA("ScreenGui") and gui.Name:match("^LucidUI_FloatingButton_") then
                    pcall(function() gui:Destroy() end)
                end
            end
        end
    end)
    print("[LucidUI] FloatingButton cleaned up")
end)

-- ============================================================
-- Module: 06e_overlay.lua
-- ============================================================
-- ============================================================
-- Module: 06e_overlay.lua
-- ============================================================
--[[
    Overlay — a draggable on-screen HUD for real-time info.

    Unlike the Window, the Overlay is designed to sit in a corner
    and update constantly (FPS, player count, target status, etc.)
    without hogging the center of the screen.

    Features:
      • Drag anywhere (mouse / touch)
      • Auto-sizes to content
      • Optional title bar with collapse toggle
      • Optional accent bar
      • Rows: text, image, imagebutton, progressbar, divider
      • Theme-aware (auto-retints on theme change)
      • Position persists across theme changes
      • Snap-to-edge optional
      • Hidden when GUI disabled
      • Cleaned up on re-execute

    Standalone — no window binding required. Pass an optional
    `Window = W` for theme syncing if you want it to follow
    your hub's theme changes.

    NO tracking. NO network. NO clipboard.
]]

LucidUI.Overlay = {}
LucidUI.Overlay.__index = LucidUI.Overlay

-- ============================================================
-- Helpers
-- ============================================================
local function clamp(v, lo, hi)
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function palette(theme)
    local VP = LucidUI.VoidPalette
    return {
        bg       = (VP and VP.BgMid)     or theme.Background or Color3.fromRGB(20, 20, 26),
        bgDeep   = (VP and VP.BgDeep)    or theme.Background or Color3.fromRGB(10, 10, 14),
        surface  = (VP and VP.BgLight)   or theme.Surface    or Color3.fromRGB(30, 28, 45),
        border   = (VP and VP.BorderDim) or theme.Border     or Color3.fromRGB(50, 50, 70),
        accent   = theme.Accent          or Color3.fromRGB(130, 80, 255),
        accent2  = (VP and VP.AccentPink) or theme.Accent,
        textHigh = theme.TextPrimary     or Color3.fromRGB(240, 240, 245),
        textMid  = theme.TextSecondary   or Color3.fromRGB(180, 180, 200),
        textDim  = theme.TextMuted       or Color3.fromRGB(130, 130, 150),
    }
end

-- ============================================================
-- Row builders
-- ============================================================
local ROW_BUILDERS = {}

-- Text row: { Type = "text", Text = "...", Id = "fps", Color = optional, Align = "left"|"right"|"center" }
ROW_BUILDERS.text = function(container, cfg, P, obj)
    local lbl = Create("TextLabel", {
        Text = cfg.Text or "",
        Font = cfg.Bold and Enum.Font.GothamBold or Enum.Font.GothamMedium,
        TextSize = cfg.TextSize or 12,
        TextColor3 = cfg.Color or P.textHigh,
        BackgroundTransparency = 1,
        TextXAlignment = cfg.Align == "right" and Enum.TextXAlignment.Right
                        or cfg.Align == "center" and Enum.TextXAlignment.Center
                        or Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Size = UDim2.new(1, 0, 0, 18),
        ZIndex = 4,
        Parent = container,
    })

    if cfg.Id then
        obj._rows[cfg.Id] = {
            kind = "text",
            instance = lbl,
            setText = function(_, v) lbl.Text = tostring(v) end,
            setColor = function(_, c) lbl.TextColor3 = c end,
            getText = function() return lbl.Text end,
        }
    end

    return function(t)
        if not cfg.Color then lbl.TextColor3 = t.TextPrimary end
    end
end

-- Image row: { Type = "image", Icon = "rbxassetid://...", Height = 40, Id = "logo" }
ROW_BUILDERS.image = function(container, cfg, P, obj)
    local h = cfg.Height or 40
    local img = Create("ImageLabel", {
        Size = UDim2.new(1, 0, 0, h),
        BackgroundTransparency = 1,
        Image = cfg.Icon or "",
        ScaleType = cfg.ScaleType or Enum.ScaleType.Fit,
        ImageColor3 = cfg.Tint or Color3.fromRGB(255, 255, 255),
        ZIndex = 4,
        Parent = container,
    })

    if cfg.Id then
        obj._rows[cfg.Id] = {
            kind = "image",
            instance = img,
            setImage = function(_, id) img.Image = id end,
        }
    end

    return function(t) end
end

-- Image button row: { Type = "imagebutton", Icon = "...", Height = 40, OnClick = fn, Label = "optional" }
ROW_BUILDERS.imagebutton = function(container, cfg, P, obj)
    local h = (cfg.Height or 40) + (cfg.Label and 16 or 0)

    local btn = Create("TextButton", {
        Name = "OverlayImageButton",
        Text = "",
        BackgroundColor3 = P.surface,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Size = UDim2.new(1, 0, 0, cfg.Height or 40),
        ZIndex = 4,
        Parent = container,
    })
    Corner(8, btn)

    local stroke = Stroke(P.border, 1, 0.35, btn)

    local img = Create("ImageLabel", {
        Size = UDim2.new(0.7, 0, 0.8, 0),
        Position = UDim2.new(0.15, 0, 0.1, 0),
        BackgroundTransparency = 1,
        Image = cfg.Icon or "",
        ScaleType = Enum.ScaleType.Fit,
        ZIndex = 5,
        Parent = btn,
    })

    if cfg.Label then
        Create("TextLabel", {
            Text = cfg.Label,
            Font = Enum.Font.GothamBold,
            TextSize = 10,
            TextColor3 = P.textDim,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Center,
            Position = UDim2.new(0, 0, 1, 2),
            Size = UDim2.new(1, 0, 0, 14),
            ZIndex = 5,
            Parent = container,
        })
    end

    btn.MouseEnter:Connect(function()
        Tween(btn, 0.12, { BackgroundColor3 = P.accent, BackgroundTransparency = 0.3 }):Play()
        Tween(stroke, 0.12, { Transparency = 0 }):Play()
    end)
    btn.MouseLeave:Connect(function()
        Tween(btn, 0.12, { BackgroundColor3 = P.surface, BackgroundTransparency = 0.15 }):Play()
        Tween(stroke, 0.12, { Transparency = 0.35 }):Play()
    end)

    BindTap(btn, function()
        PlayUISound("click")
        if cfg.OnClick then Compat.safeCallback(cfg.OnClick) end
        if LucidUI.VoidStyle and LucidUI.VoidStyle.ShinePass then
            LucidUI.VoidStyle.ShinePass(btn, { duration = 0.35 })
        end
    end)

    if cfg.Id then
        obj._rows[cfg.Id] = {
            kind = "imagebutton",
            instance = btn,
            setImage = function(_, id) img.Image = id end,
        }
    end

    return function(t)
        btn.BackgroundColor3 = (LucidUI.VoidPalette and LucidUI.VoidPalette.BgLight) or t.Surface
        stroke.Color = (LucidUI.VoidPalette and LucidUI.VoidPalette.BorderDim) or t.Border
        if not cfg.Label then return end
        -- Label retint handled below
    end
end

-- Progress bar row: { Type = "progress", Id = "hp", Value = 0..1, Height = 8, ShowLabel = true, Label = "HP" }
ROW_BUILDERS.progress = function(container, cfg, P, obj)
    local showLabel = cfg.ShowLabel ~= false
    local totalH = (showLabel and 20 or 0) + (cfg.Height or 8)
    local wrapper = Create("Frame", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, totalH),
        ZIndex = 4,
        Parent = container,
    })

    local lbl, valueLbl
    if showLabel then
        lbl = Create("TextLabel", {
            Text = cfg.Label or "",
            Font = Enum.Font.GothamMedium,
            TextSize = 11,
            TextColor3 = P.textMid,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, -60, 0, 16),
            ZIndex = 5,
            Parent = wrapper,
        })
        valueLbl = Create("TextLabel", {
            Text = "",
            Font = Enum.Font.GothamBold,
            TextSize = 11,
            TextColor3 = P.accent,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Right,
            Size = UDim2.new(1, 0, 0, 16),
            ZIndex = 5,
            Parent = wrapper,
        })
    end

    local track = Create("Frame", {
        Size = UDim2.new(1, 0, 0, cfg.Height or 8),
        Position = UDim2.new(0, 0, 0, showLabel and 20 or 0),
        BackgroundColor3 = (LucidUI.VoidPalette and LucidUI.VoidPalette.BgDeep) or P.bgDeep,
        BorderSizePixel = 0,
        ZIndex = 5,
        Parent = wrapper,
    })
    Corner((cfg.Height or 8) / 2, track)

    local fill = Create("Frame", {
        Size = UDim2.new(math.clamp(cfg.Value or 0, 0, 1), 0, 1, 0),
        BackgroundColor3 = cfg.Color or P.accent,
        BorderSizePixel = 0,
        ZIndex = 6,
        Parent = track,
    })
    Corner((cfg.Height or 8) / 2, fill)

    local grad = Create("UIGradient", {
        Color = ColorSequence.new(P.accent, P.accent2),
        Rotation = 0,
        Parent = fill,
    })

    if cfg.Id then
        obj._rows[cfg.Id] = {
            kind = "progress",
            instance = wrapper,
            setValue = function(_, v)
                v = math.clamp(v or 0, 0, 1)
                Tween(fill, 0.25, { Size = UDim2.new(v, 0, 1, 0) }):Play()
                if valueLbl then
                    valueLbl.Text = tostring(math.floor(v * 100)) .. "%"
                end
            end,
            setLabel = function(_, text)
                if lbl then lbl.Text = tostring(text) end
            end,
            setColor = function(_, c)
                fill.BackgroundColor3 = c
            end,
        }
    end

    return function(t)
        if not cfg.Color then
            fill.BackgroundColor3 = t.Accent
        end
        track.BackgroundColor3 = (LucidUI.VoidPalette and LucidUI.VoidPalette.BgDeep) or t.Background
        if lbl then lbl.TextColor3 = t.TextSecondary end
        if valueLbl then valueLbl.TextColor3 = t.Accent end
        grad.Color = ColorSequence.new(
            t.Accent,
            (LucidUI.VoidPalette and LucidUI.VoidPalette.AccentPink) or t.Accent
        )
    end
end

-- Divider row: { Type = "divider" }
ROW_BUILDERS.divider = function(container, cfg, P, obj)
    local line = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 1),
        BackgroundColor3 = P.border,
        BackgroundTransparency = 0.3,
        BorderSizePixel = 0,
        ZIndex = 4,
        Parent = container,
    })
    Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.5, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Parent = line,
    })

    return function(t)
        line.BackgroundColor3 = (LucidUI.VoidPalette and LucidUI.VoidPalette.BorderDim) or t.Border
    end
end

-- Spacer row: { Type = "spacer", Height = 8 }
ROW_BUILDERS.spacer = function(container, cfg, P, obj)
    Create("Frame", {
        Size = UDim2.new(1, 0, 0, cfg.Height or 8),
        BackgroundTransparency = 1,
        ZIndex = 4,
        Parent = container,
    })
    return function(t) end
end

-- ============================================================
-- Public: CreateOverlay
-- ============================================================
--[[
    cfg = {
        Title       = "HUD",
        TitleIcon   = "rbxassetid://...",
        Collapsible = true,
        Position    = UDim2.new(0, 16, 0, 120),
        Width       = 180,
        Padding     = 10,
        Rows        = { ...see above... },
        SnapToEdge  = false,
        Draggable   = true,
        AccentBar   = true,
        Window      = nil,  -- optional; syncs theme changes
        Visible     = true,
    }
]]

function LucidUI:CreateOverlay(cfg)
    cfg = cfg or {}

    local theme = (cfg.Window and cfg.Window.Theme)
              or LucidUI._lastTheme
              or LucidUI.Themes.Default
    local P = palette(theme)

    -- Root GUI (own ScreenGui so it survives window hide)
    local gui = Create("ScreenGui", {
        Name = "LucidUI_Overlay_" .. tostring(math.floor(tick() * 1000) % 100000),
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = cfg.DisplayOrder or 300,
        Enabled = cfg.Visible ~= false,
        Parent = PlayerGui,
    })

    local obj = setmetatable({}, LucidUI.Overlay)
    obj.Gui     = gui
    obj.Theme   = theme
    obj._rows   = {}
    obj._conns  = {}
    obj._cfg    = cfg
    obj._themeFns = {}

    -- Container frame
    local container = Create("Frame", {
        Name = "Overlay",
        Size = UDim2.fromOffset(cfg.Width or 180, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        Position = cfg.Position or UDim2.new(0, 16, 0, 120),
        BackgroundColor3 = P.bg,
        BackgroundTransparency = cfg.BackgroundTransparency or 0.15,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = gui,
    })
    Corner(cfg.CornerRadius or 12, container)

    local containerStroke = Stroke(P.border, 1, 0.35, container)

    -- Subtle background gradient
    local bgGrad = Create("UIGradient", {
        Color = ColorSequence.new(P.bg, P.bgDeep),
        Rotation = 90,
        Parent = container,
    })

    -- Accent bar (VoidStyle's signature)
    local accentBar, accentGrad
    if cfg.AccentBar ~= false and LucidUI.VoidStyle then
        accentBar, accentGrad = LucidUI.VoidStyle.AccentBar(container, { height = 0.35, y = 0.325 })
    end

    -- Content list
    local list = Create("Frame", {
        Name = "List",
        Size = UDim2.new(1, -(cfg.Padding or 10) * 2, 0, 0),
        Position = UDim2.fromOffset(cfg.Padding or 10, 0),
        BackgroundTransparency = 1,
        AutomaticSize = Enum.AutomaticSize.Y,
        ZIndex = 3,
        Parent = container,
    })

    local layout = Create("UIListLayout", {
        Padding = UDim.new(0, 6),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = list,
    })

    -- Top / bottom padding
    Create("UIPadding", {
        PaddingTop    = UDim.new(0, cfg.Padding or 10),
        PaddingBottom = UDim.new(0, cfg.Padding or 10),
        Parent = list,
    })

    obj.Container = container
    obj.Content   = list
    obj.Layout    = layout

    -- ── Title bar (optional) ──────────────────────────────
    local titleBar, titleLbl, collapseBtn, titleIcon
    if cfg.Title and cfg.Title ~= "" then
        titleBar = Create("TextButton", {
            Text = "",
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 24),
            LayoutOrder = -1000,
            ZIndex = 4,
            Parent = list,
        })

        -- Icon if provided
        local iconOffset = 0
        if cfg.TitleIcon then
            titleIcon = Create("ImageLabel", {
                Size = UDim2.fromOffset(16, 16),
                Position = UDim2.fromOffset(0, 4),
                BackgroundTransparency = 1,
                Image = cfg.TitleIcon,
                ScaleType = Enum.ScaleType.Fit,
                ZIndex = 5,
                Parent = titleBar,
            })
            iconOffset = 22
        end

        titleLbl = Create("TextLabel", {
            Text = cfg.Title,
            Font = Enum.Font.GothamBold,
            TextSize = 12,
            TextColor3 = P.textHigh,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.fromOffset(iconOffset, 0),
            Size = UDim2.new(1, -(iconOffset + (cfg.Collapsible and 20 or 0)), 1, 0),
            ZIndex = 5,
            Parent = titleBar,
        })

        if cfg.Collapsible then
            collapseBtn = Create("TextButton", {
                Text = "▾",
                Font = Enum.Font.GothamBold,
                TextSize = 14,
                TextColor3 = P.textDim,
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                Size = UDim2.fromOffset(20, 20),
                Position = UDim2.new(1, -20, 0, 2),
                ZIndex = 5,
                Parent = titleBar,
            })
        end
    end

    -- ── Build rows ────────────────────────────────────────
    local order = 1
    for _, rowCfg in ipairs(cfg.Rows or {}) do
        local builder = ROW_BUILDERS[rowCfg.Type or "text"]
        if builder then
            -- Create a row wrapper frame
            local rowWrap = Create("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                LayoutOrder = order,
                ZIndex = 3,
                Parent = list,
            })
            order = order + 1

            local themeFn = builder(rowWrap, rowCfg, P, obj)
            if themeFn then
                table.insert(obj._themeFns, themeFn)
            end
        end
    end

    -- ── Drag handling ─────────────────────────────────────
    if cfg.Draggable ~= false then
        local dragging, dragStart, startPos, dragInput
        local dragTarget = titleBar or container

        dragTarget.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            dragging  = true
            dragStart = input.Position
            startPos  = container.Position
            dragInput = input
        end)

        table.insert(obj._conns, UserInputService.InputChanged:Connect(function(input)
            if not dragging or input ~= dragInput then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
                and input.UserInputType ~= Enum.UserInputType.Touch then return end

            local delta = input.Position - dragStart
            container.Position = UDim2.new(
                startPos.X.Scale, startPos.X.Offset + delta.X,
                startPos.Y.Scale, startPos.Y.Offset + delta.Y
            )
        end))

        table.insert(obj._conns, UserInputService.InputEnded:Connect(function(input)
            if input ~= dragInput then return end
            dragging = false
            dragInput = nil

            if cfg.SnapToEdge then
                local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
                          or Vector2.new(1920, 1080)
                local margin = cfg.SnapMargin or 12
                local curX = container.AbsolutePosition.X
                local curY = container.AbsolutePosition.Y
                local w    = container.AbsoluteSize.X
                local h    = container.AbsoluteSize.Y

                local distLeft  = curX
                local distRight = vp.X - (curX + w)
                local targetX
                if distLeft < distRight then
                    targetX = margin
                else
                    targetX = vp.X - w - margin
                end
                local targetY = clamp(curY, margin, math.max(vp.Y - h - margin, margin))

                Tween(container, 0.25, {
                    Position = UDim2.fromOffset(targetX, targetY),
                }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
            end
        end))
    end

    -- ── Collapse toggle ───────────────────────────────────
    local collapsed = false
    local normalSize
    if collapseBtn then
        collapseBtn.MouseButton1Click:Connect(function()
            collapsed = not collapsed
            if collapsed then
                normalSize = container.Size
                Tween(container, 0.22, {
                    Size = UDim2.fromOffset(cfg.Width or 180, 24 + (cfg.Padding or 10) * 2),
                }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
                Tween(list, 0.22, { BackgroundTransparency = 0 }):Play()
                for _, row in ipairs(list:GetChildren()) do
                    if row:IsA("GuiObject") and row ~= titleBar then
                        row.Visible = false
                    end
                end
                collapseBtn.Text = "▸"
            else
                Tween(container, 0.22, {
                    Size = normalSize or UDim2.fromOffset(cfg.Width or 180, 0),
                }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
                for _, row in ipairs(list:GetChildren()) do
                    if row:IsA("GuiObject") and row ~= titleBar then
                        row.Visible = true
                    end
                end
                collapseBtn.Text = "▾"
            end
            PlayUISound("click")
        end)
    end

    -- ── Theme application ─────────────────────────────────
    local function applyTheme(t)
        obj.Theme = t
        local TP = palette(t)
        P = TP

        container.BackgroundColor3 = TP.bg
        containerStroke.Color      = TP.border
        bgGrad.Color               = ColorSequence.new(TP.bg, TP.bgDeep)

        if titleLbl then titleLbl.TextColor3 = TP.textHigh end
        if collapseBtn then collapseBtn.TextColor3 = TP.textDim end

        if accentGrad then
            accentGrad.Color = ColorSequence.new(TP.accent, TP.accent2)
        end

        for _, fn in ipairs(obj._themeFns) do
            pcall(fn, t)
        end
    end
    obj._applyTheme = applyTheme

    if cfg.Window then
        cfg.Window:_registerTheme(applyTheme)
    end

    -- ── Public methods ────────────────────────────────────
    function obj:Set(id, value)
        local row = self._rows[id]
        if not row then return end
        if row.kind == "text" and row.setText then
            row.setText(nil, value)
        elseif row.kind == "image" and row.setImage then
            row.setImage(nil, value)
        elseif row.kind == "imagebutton" and row.setImage then
            row.setImage(nil, value)
        elseif row.kind == "progress" and row.setValue then
            row.setValue(nil, value)
        end
    end

    function obj:SetText(id, text)
        local row = self._rows[id]
        if row and row.setText then row.setText(nil, text) end
    end

    function obj:SetImage(id, image)
        local row = self._rows[id]
        if row and row.setImage then row.setImage(nil, image) end
    end

    function obj:SetColor(id, color)
        local row = self._rows[id]
        if row and row.setColor then row.setColor(nil, color) end
    end

    function obj:SetLabel(id, text)
        local row = self._rows[id]
        if row and row.setLabel then row.setLabel(nil, text) end
    end

    function obj:SetProgress(id, value)
        local row = self._rows[id]
        if row and row.setValue then row.setValue(nil, value) end
    end

    function obj:Show()   self.Gui.Enabled = true  end
    function obj:Hide()   self.Gui.Enabled = false end

    function obj:SetVisible(v)
        if v then self:Show() else self:Hide() end
    end

    function obj:SetTitle(text)
        if titleLbl then titleLbl.Text = tostring(text) end
    end

    function obj:SetPosition(udim2)
        self.Container.Position = udim2
    end

    function obj:Destroy()
        for _, c in ipairs(self._conns or {}) do
            if typeof(c) == "RBXScriptConnection" then
                pcall(function() c:Disconnect() end)
            end
        end
        self._conns = {}
        if self.Gui then
            pcall(function() self.Gui:Destroy() end)
            self.Gui = nil
        end
    end

    -- Register for global cleanup
    LucidUI._overlays = LucidUI._overlays or {}
    table.insert(LucidUI._overlays, obj)

    -- Initial theme application
    applyTheme(theme)

    return obj
end

-- ============================================================
-- Quick helper: Update overlay rows from a table
-- ============================================================
--[[
    overlay:BatchSet({
        fps     = 60,
        players = 12,
        status  = "Ready",
    })
]]
function LucidUI.Overlay:BatchSet(data)
    if type(data) ~= "table" then return end
    for id, value in pairs(data) do
        self:Set(id, value)
    end
end

-- ============================================================
-- Cleanup
-- ============================================================
LucidUI:OnCleanup(function()
    if LucidUI._overlays then
        for _, ov in ipairs(LucidUI._overlays) do
            pcall(function() ov:Destroy() end)
        end
        LucidUI._overlays = {}
    end

    -- Fallback sweep for any stragglers
    pcall(function()
        if PlayerGui then
            for _, gui in ipairs(PlayerGui:GetChildren()) do
                if gui:IsA("ScreenGui") and gui.Name:match("^LucidUI_Overlay_") then
                    pcall(function() gui:Destroy() end)
                end
            end
        end
    end)

    print("[LucidUI] Overlay cleaned up")
end)

-- ============================================================
-- Module: 06f_voidhooks.lua
-- ============================================================
-- ============================================================
-- Module: 02c_void_hooks.lua
-- ============================================================
--[[
    VoidStyle window hooks — installed AFTER 06_window.lua defines
    LucidUI.CreateWindow, LucidUI.Window.SetThemeObject, and
    LucidUI.Window.Destroy.

    Must load immediately after 06_window.lua in build order.

    Adds:
      • CreateWindow hook — applies VoidStyle theme + enhancements
      • SetThemeObject hook — re-tints glow ring + animated border
        when the theme changes at runtime
      • Destroy hook — cleans up the glow ring + animated border

    NO tracking. NO network. NO clipboard.
]]

-- Guard: bail if 06_window hasn't loaded yet
if not LucidUI or not LucidUI.CreateWindow or not LucidUI.Window then
    warn("[LucidUI] VoidHooks: 06_window not loaded — skipping")
    return
end

-- ============================================================
-- 1. CreateWindow hook
-- ============================================================
local _origCreateWindow = LucidUI.CreateWindow
function LucidUI:CreateWindow(config)
    config = config or {}

    -- Auto-select Void theme if VoidStyle is requested without a theme
    if config.VoidStyle and not config.Theme then
        config.Theme = "Void"
    end

    local W = _origCreateWindow(self, config)

    -- Resolve enhancement flags
    local enhanceGlass = config.EnhanceGlass
    local ambientGlow  = config.AmbientGlow
    local animatedBord = config.AnimatedBorder

    if config.VoidStyle then
        if enhanceGlass == nil then enhanceGlass = true end
        if ambientGlow  == nil then ambientGlow  = true end
        if animatedBord == nil then animatedBord = true end
    else
        if enhanceGlass == nil then enhanceGlass = true  end
        if ambientGlow  == nil then ambientGlow  = false end
        if animatedBord == nil then animatedBord = false end
    end

    W._voidEnhance = {
        EnhanceGlass   = enhanceGlass,
        AmbientGlow    = ambientGlow,
        AnimatedBorder = animatedBord,
        GlowIntensity  = config.GlowIntensity or 1.0,
        GlowPulse      = config.GlowPulse ~= false,
        gradientSweep  = config.GradientSweep ~= false,
    }

    task.defer(function()
        if not (W.Main and W.Main.Parent) then return end

        if W._voidEnhance.EnhanceGlass and LucidUI.EnhanceGlass then
            pcall(function()
                LucidUI.EnhanceGlass(W.Main, W.Theme, W._voidEnhance)
            end)
        end

        if W._voidEnhance.AmbientGlow and LucidUI._BuildAmbientGlow then
            pcall(function()
                LucidUI._BuildAmbientGlow(W, W.Theme, W._voidEnhance)
            end)
        end

        if W._voidEnhance.AnimatedBorder and LucidUI._BuildAnimatedBorder then
            pcall(function()
                LucidUI._BuildAnimatedBorder(W, W.Theme, W._voidEnhance)
            end)
        end
    end)

    return W
end

-- ============================================================
-- 2. SetThemeObject hook — retint on runtime theme change
-- ============================================================
local _origSetThemeObject = LucidUI.Window.SetThemeObject
function LucidUI.Window:SetThemeObject(t)
    _origSetThemeObject(self, t)

    if not self._voidEnhance then return end
    local opts = self._voidEnhance

    if opts.EnhanceGlass and self.Main and LucidUI.EnhanceGlass then
        pcall(function()
            LucidUI.EnhanceGlass(self.Main, t, opts)
        end)
    end

    if opts.AmbientGlow and self._ambientGlowLayers then
        for _, layer in ipairs(self._ambientGlowLayers) do
            if layer.frame and layer.frame.Parent then
                layer.frame.BackgroundColor3 = t.Accent or Color3.fromRGB(130, 80, 255)
            end
        end
    end

    if opts.AnimatedBorder and self._animatedBorder and self._animatedBorder.Parent then
        local accent  = t.Accent or Color3.fromRGB(130, 80, 255)
        local accent2 = Color3.new(
            math.min(accent.R + 0.3, 1),
            math.min(accent.G + 0.3, 1),
            math.min(accent.B + 0.3, 1)
        )
        self._animatedBorder.Color = accent
        if self._animatedBorderGrad then
            self._animatedBorderGrad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0,    accent),
                ColorSequenceKeypoint.new(0.35, accent2),
                ColorSequenceKeypoint.new(0.65, accent),
                ColorSequenceKeypoint.new(1,    accent2),
            })
        end
    end
end

-- ============================================================
-- 3. Destroy hook — cleanup glow ring + animated border
-- ============================================================
local _origWindowDestroy = LucidUI.Window.Destroy
function LucidUI.Window:Destroy()
    if self._ambientGlow and self._ambientGlow.Parent then
        pcall(function() self._ambientGlow:Destroy() end)
    end
    self._ambientGlow = nil
    self._ambientGlowLayers = nil

    if self._animatedBorder and self._animatedBorder.Parent then
        pcall(function() self._animatedBorder:Destroy() end)
    end
    self._animatedBorder = nil
    self._animatedBorderGrad = nil

    _origWindowDestroy(self)
end

-- ============================================================
-- 4. Cleanup registration
-- ============================================================
LucidUI:OnCleanup(function()
    print("[LucidUI] VoidHooks cleaned up")
end)

-- ============================================================
-- Module: 07_settings_a.lua
-- ============================================================
--[[
    Settings A — theme dropdown, custom theme editor, saved themes,
    low graphics mode.

    [IMPROVEMENT] Added Low Graphics Mode toggle, active theme
    checkmark, reset to default, preset swatches in the color picker,
    and pcall wrapping throughout.

    Color picker:
      _openColorPickerModal(opts) is the general-purpose picker.
      Anywhere can call it with { Label, InitialColor, OnChange }.

    Auto-contrast:
      ApplyCustomTheme checks the user's TextPrimary against their
      Background using WCAG relative luminance.
]]

-- ============================================================
-- Contrast helpers — WCAG relative luminance
-- ============================================================
local function relLuminance(c)
    local function lin(x)
        if x <= 0.03928 then return x / 12.92 end
        return ((x + 0.055) / 1.055) ^ 2.4
    end
    return 0.2126 * lin(c.R) + 0.7152 * lin(c.G) + 0.0722 * lin(c.B)
end

local function contrastRatio(c1, c2)
    local l1, l2 = relLuminance(c1), relLuminance(c2)
    if l1 < l2 then l1, l2 = l2, l1 end
    return (l1 + 0.05) / (l2 + 0.05)
end

local function autoReadableText(preferred, bg, minRatio)
    minRatio = minRatio or 4.5
    if contrastRatio(preferred, bg) >= minRatio then
        return preferred, false
    end
    local light = Color3.fromRGB(240, 240, 245)
    local dark  = Color3.fromRGB(22, 22, 26)
    if contrastRatio(light, bg) >= contrastRatio(dark, bg) then
        return light, true
    else
        return dark, true
    end
end

-- ============================================================
-- Paint bucket icon
-- ============================================================
local function BuildPaintBucketIcon(parent, size, color)
    size = size or 18

    local holder = Create("Frame", {
        Size = UDim2.fromOffset(size, size),
        BackgroundTransparency = 1,
        Parent = parent,
    })

    local barW = math.max(size * 0.08, 1)
    local parts = {}

    local handleH = size * 0.26
    local leftBar = Create("Frame", {
        Size = UDim2.fromOffset(barW, handleH),
        Position = UDim2.new(0.30, 0, 0.12, 0),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(barW / 2, leftBar)
    table.insert(parts, leftBar)

    local rightBar = Create("Frame", {
        Size = UDim2.fromOffset(barW, handleH),
        Position = UDim2.new(0.70, 0, 0.12, 0),
        AnchorPoint = Vector2.new(1, 0),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(barW / 2, rightBar)
    table.insert(parts, rightBar)

    local topBar = Create("Frame", {
        Size = UDim2.fromOffset(size * 0.40, barW),
        Position = UDim2.new(0.50, 0, 0.12, 0),
        AnchorPoint = Vector2.new(0.5, 0),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(barW / 2, topBar)
    table.insert(parts, topBar)

    local bodyW = size * 0.74
    local bodyH = size * 0.50
    local body = Create("Frame", {
        Size = UDim2.fromOffset(bodyW, bodyH),
        Position = UDim2.new(0.50, 0, 0.62, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    local bodyCorner = Instance.new("UICorner")
    bodyCorner.TopLeftRadius     = UDim.new(0, 1)
    bodyCorner.TopRightRadius    = UDim.new(0, 1)
    bodyCorner.BottomLeftRadius  = UDim.new(0, bodyW * 0.18)
    bodyCorner.BottomRightRadius = UDim.new(0, bodyW * 0.18)
    bodyCorner.Parent = body
    table.insert(parts, body)

    local dropSize = size * 0.16
    local drop = Create("Frame", {
        Size = UDim2.fromOffset(dropSize, dropSize),
        Position = UDim2.new(0.78, 0, 0.94, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(999, drop)
    table.insert(parts, drop)

    return holder, parts
end

-- ============================================================
-- Setting layout helpers
-- ============================================================
function LucidUI.Window:_addSettingFrame(frame)
    frame.LayoutOrder = self._settingsOrder
    self._settingsOrder = self._settingsOrder + 1
    frame.Parent = self._spContent
    return frame
end

function LucidUI.Window:_addSettingSection(title)
    local label = Create("TextLabel", {
        Text = title:upper(),
        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = self.Theme.TextMuted,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, 0, 0, 18),
        LayoutOrder = self._settingsOrder,
        Parent = self._spContent,
    })
    self._settingsOrder = self._settingsOrder + 1
    self:_registerTheme(function(t) label.TextColor3 = t.TextMuted end)
    return label
end

function LucidUI.Window:_ensureCustomTheme()
    if self._customTheme then return end
    self._customTheme = {
        Background   = self.Theme.Background,
        Surface      = self.Theme.Surface,
        SurfaceHover = self.Theme.SurfaceHover,
        Accent       = self.Theme.Accent,
        Border       = self.Theme.Border,
        TextPrimary  = self.Theme.TextPrimary,
    }
end

function LucidUI.Window:ApplyCustomTheme()
    self:_ensureCustomTheme()
    local base = LucidUI.Themes.Default
    local t = {}
    for k, v in pairs(base) do t[k] = v end
    for k, v in pairs(self._customTheme) do t[k] = v end

    local readablePrimary = autoReadableText(
        self._customTheme.TextPrimary,
        self._customTheme.Background,
        4.5
    )
    if readablePrimary then
        self._customTheme.TextPrimary = readablePrimary
    end
    t.TextPrimary = readablePrimary

    t.TextSecondary = Color3.new(
        math.min(t.TextPrimary.R * 0.92, 1),
        math.min(t.TextPrimary.G * 0.92, 1),
        math.min(t.TextPrimary.B * 0.92, 1)
    )

    local mutedRaw = Color3.new(
        (t.TextPrimary.R + t.Background.R) * 0.5,
        (t.TextPrimary.G + t.Background.G) * 0.5,
        (t.TextPrimary.B + t.Background.B) * 0.5
    )
    t.TextMuted = autoReadableText(mutedRaw, t.Background, 3)

    t.ToggleOff   = t.Surface
    t.SliderTrack = t.Surface
    t.TabActive   = t.TextPrimary
    t.TabInactive = t.TextMuted

    LucidUI.Themes["__custom_runtime"] = t
    self.Theme = t
    self.ThemeName = "Custom"
    self._customThemeActive = true
    LucidUI._lastTheme = t
    self:SetThemeObject(t)
end

function LucidUI.Window:SaveCustomTheme(name)
    name = name or "Custom Theme"
    self:_ensureCustomTheme()
    local data = {
        customTheme = Compat.serializeColors(self._customTheme),
        accent = self._accentOverride and {
            R = self._accentOverride.R, G = self._accentOverride.G, B = self._accentOverride.B
        } or nil,
    }
    local encoded = Compat.encode(data)
    if not encoded then return end
    Compat.ensureFolders()
    local ok = Compat.write("LucidUI/Themes/" .. name .. ".json", encoded)
    if ok then
        LucidUI:Notify({ Title = "Theme Saved", Message = name, Variant = "success" })
        if self._savedThemeSlotsRefresh then pcall(self._savedThemeSlotsRefresh) end
    else
        LucidUI:Notify({ Title = "Save Failed", Message = "No file system", Variant = "error" })
    end
end

function LucidUI.Window:LoadCustomTheme(name)
    name = name or "Custom Theme"
    local contents = Compat.read("LucidUI/Themes/" .. name .. ".json")
    if not contents then
        LucidUI:Notify({ Title = "Load Failed", Message = "Not found: " .. name, Variant = "error" })
        return
    end
    local data = Compat.decode(contents)
    if not data or not data.customTheme then return end
    local restored = Compat.deserializeColors(data.customTheme)
    if not restored then return end
    local d = LucidUI.Themes.Default
    self._customTheme = {
        Background   = restored.Background   or d.Background,
        Surface      = restored.Surface      or d.Surface,
        SurfaceHover = restored.SurfaceHover or d.SurfaceHover,
        Accent       = restored.Accent       or d.Accent,
        Border       = restored.Border       or d.Border,
        TextPrimary  = restored.TextPrimary  or d.TextPrimary,
    }
    if data.accent then
        self:SetAccent(Color3.new(data.accent.R, data.accent.G, data.accent.B))
    end
    self:ApplyCustomTheme()
    self.ThemeName = name
    LucidUI:Notify({ Title = "Theme Loaded", Message = name, Variant = "success" })
end

-- ============================================================
-- General-purpose HSV color picker modal
-- ============================================================
local PRESET_COLORS = {
    Color3.fromRGB(10, 132, 255),   -- blue
    Color3.fromRGB(90, 210, 130),   -- green
    Color3.fromRGB(255, 189, 46),   -- amber
    Color3.fromRGB(255, 95, 87),    -- red
    Color3.fromRGB(189, 147, 249),  -- purple
    Color3.fromRGB(255, 126, 219),  -- pink
    Color3.fromRGB(122, 162, 247),  -- sky
    Color3.fromRGB(255, 255, 255),  -- white
}

function LucidUI.Window:_openColorPickerModal(opts)
    opts = opts or {}
    local initialColor = opts.InitialColor or Color3.fromRGB(90, 180, 255)
    local headerLabel  = opts.Label        or "Color"
    local onChange     = opts.OnChange
    local onClose      = opts.OnClose

    if self._colorPickerModal and self._colorPickerModal.Parent then
        pcall(function() self._colorPickerModal:Destroy() end)
    end

    local base = initialColor
    local H, S, V = Color3.toHSV(base)

    local modal = Create("Frame", {
        Name = "ColorPickerModal",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.new(0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 500,
        Parent = self.Gui,
    })
    self._colorPickerModal = modal

    local backdrop = Create("TextButton", {
        Name = "Backdrop",
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 1,
        Parent = modal,
    })

    local card = Create("CanvasGroup", {
        Size = UDim2.fromOffset(360, 300),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.05,
        BorderSizePixel = 0,
        GroupTransparency = 1,
        ZIndex = 2,
        Parent = modal,
    })
    Corner(16, card)
    Stroke(self.Theme.Border, 1, 0.5, card)

    local popScale = Instance.new("UIScale")
    popScale.Scale = 0.82
    popScale.Parent = card

    local iconHolder = BuildPaintBucketIcon(card, 20, self.Theme.Accent)
    iconHolder.Position = UDim2.fromOffset(16, 14)
    iconHolder.ZIndex = 3

    Create("TextLabel", {
        Text = headerLabel,
        Font = Enum.Font.GothamBold, TextSize = 15,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(46, 14),
        Size = UDim2.new(1, -60, 0, 22),
        ZIndex = 3, Parent = card,
    })

    local closeBtn = Create("TextButton", {
        Text = "x", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        Size = UDim2.fromOffset(28, 28),
        Position = UDim2.new(1, -34, 0, 12),
        ZIndex = 3, Parent = card,
    })

    -- SV square
    local svArea = Create("Frame", {
        Size = UDim2.fromOffset(250, 155),
        Position = UDim2.fromOffset(18, 48),
        BackgroundColor3 = Color3.fromHSV(H, 1, 1),
        BorderSizePixel = 0, ClipsDescendants = true,
        ZIndex = 3, Parent = card,
    })
    Corner(10, svArea)

    local satOverlay = Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0, ZIndex = 4, Parent = svArea,
    })
    Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Rotation = 0, Parent = satOverlay,
    })

    local valOverlay = Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BorderSizePixel = 0, ZIndex = 5, Parent = svArea,
    })
    Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Rotation = 90, Parent = valOverlay,
    })

    local dot = Create("Frame", {
        Size = UDim2.fromOffset(16, 16),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(S, 1 - V),
        BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 2, BorderColor3 = Color3.new(0, 0, 0),
        ZIndex = 6, Parent = svArea,
    })
    Corner(8, dot)

    -- Hue strip
    local hueStrip = Create("Frame", {
        Size = UDim2.fromOffset(26, 155),
        Position = UDim2.new(1, -44, 0, 48),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0, ClipsDescendants = true,
        ZIndex = 3, Parent = card,
    })
    Corner(10, hueStrip)
    Create("UIGradient", {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0.000, Color3.fromRGB(255, 0, 0)),
            ColorSequenceKeypoint.new(0.167, Color3.fromRGB(255, 255, 0)),
            ColorSequenceKeypoint.new(0.333, Color3.fromRGB(0, 255, 0)),
            ColorSequenceKeypoint.new(0.500, Color3.fromRGB(0, 255, 255)),
            ColorSequenceKeypoint.new(0.667, Color3.fromRGB(0, 0, 255)),
            ColorSequenceKeypoint.new(0.833, Color3.fromRGB(255, 0, 255)),
            ColorSequenceKeypoint.new(1.000, Color3.fromRGB(255, 0, 0)),
        }),
        Rotation = 90, Parent = hueStrip,
    })
    local hueDot = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 5),
        Position = UDim2.new(0, 0, H, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 1, BorderColor3 = Color3.new(0, 0, 0),
        ZIndex = 6, Parent = hueStrip,
    })

    -- [IMPROVEMENT] Preset swatch row
    local presetRow = Create("Frame", {
        Size = UDim2.new(1, -36, 0, 24),
        Position = UDim2.fromOffset(18, 212),
        BackgroundTransparency = 1,
        ZIndex = 3, Parent = card,
    })
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        Parent = presetRow,
    })

    -- Bottom row
    local preview = Create("Frame", {
        Size = UDim2.fromOffset(32, 32),
        Position = UDim2.fromOffset(18, 246),
        BackgroundColor3 = base,
        BorderSizePixel = 0, ZIndex = 3, Parent = card,
    })
    Corner(8, preview)
    Stroke(self.Theme.Border, 1, 0.5, preview)

    local hexBox = Create("TextBox", {
        Text = string.format("#%02X%02X%02X",
            math.floor(base.R * 255),
            math.floor(base.G * 255),
            math.floor(base.B * 255)),
        Font = Enum.Font.GothamBold, TextSize = 13,
        TextColor3 = self.Theme.TextPrimary,
        BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.3,
        ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Center,
        Size = UDim2.fromOffset(120, 32),
        Position = UDim2.fromOffset(60, 246),
        ZIndex = 3, Parent = card,
    })
    Corner(8, hexBox)

    local doneBtn = Create("TextButton", {
        Text = "Done",
        Font = Enum.Font.GothamBold, TextSize = 13,
        TextColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundColor3 = self.Theme.Accent,
        AutoButtonColor = false,
        Size = UDim2.fromOffset(100, 32),
        Position = UDim2.new(1, -118, 0, 246),
        ZIndex = 3, Parent = card,
    })
    Corner(8, doneBtn)

    local function applyColor()
        local c = Color3.fromHSV(H, S, V)
        preview.BackgroundColor3 = c
        svArea.BackgroundColor3  = Color3.fromHSV(H, 1, 1)
        dot.Position             = UDim2.fromScale(S, 1 - V)
        hueDot.Position          = UDim2.new(0, 0, H, 0)
        hexBox.Text = string.format("#%02X%02X%02X",
            math.floor(c.R * 255), math.floor(c.G * 255), math.floor(c.B * 255))
        if onChange then pcall(onChange, c) end
    end

    -- Preset swatches
    for _, presetColor in ipairs(PRESET_COLORS) do
        local swatch = Create("TextButton", {
            Text = "",
            BackgroundColor3 = presetColor,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Size = UDim2.fromOffset(24, 24),
            ZIndex = 4, Parent = presetRow,
        })
        Corner(6, swatch)
        Stroke(self.Theme.Border, 1, 0.6, swatch)

        BindTap(swatch, function()
            H, S, V = Color3.toHSV(presetColor)
            applyColor()
        end)
    end

    -- SV drag
    local svDrag = false
    local function svUpdate(input)
        S = math.clamp((input.Position.X - svArea.AbsolutePosition.X) / svArea.AbsoluteSize.X, 0, 1)
        V = 1 - math.clamp((input.Position.Y - svArea.AbsolutePosition.Y) / svArea.AbsoluteSize.Y, 0, 1)
        applyColor()
    end
    svArea.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            svDrag = true; svUpdate(input)
        end
    end)
    table.insert(self._conns, UserInputService.InputChanged:Connect(function(input)
        if not svDrag then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then svUpdate(input) end
    end))
    table.insert(self._conns, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then svDrag = false end
    end))

    -- Hue drag
    local hueDrag = false
    local function hueUpdate(input)
        H = math.clamp((input.Position.Y - hueStrip.AbsolutePosition.Y) / hueStrip.AbsoluteSize.Y, 0, 1)
        applyColor()
    end
    hueStrip.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            hueDrag = true; hueUpdate(input)
        end
    end)
    table.insert(self._conns, UserInputService.InputChanged:Connect(function(input)
        if not hueDrag then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then hueUpdate(input) end
    end))
    table.insert(self._conns, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then hueDrag = false end
    end))

    -- Hex input (with validation)
    hexBox.FocusLost:Connect(function()
        local hex = hexBox.Text:gsub("#", "")
        if #hex == 6 and hex:match("^%x+$") then
            local r = tonumber(hex:sub(1, 2), 16)
            local g = tonumber(hex:sub(3, 4), 16)
            local b = tonumber(hex:sub(5, 6), 16)
            if r and g and b then
                H, S, V = Color3.toHSV(Color3.fromRGB(r, g, b))
                applyColor()
                return
            end
        end
        -- Invalid — restore current text
        hexBox.Text = string.format("#%02X%02X%02X",
            math.floor(preview.BackgroundColor3.R * 255),
            math.floor(preview.BackgroundColor3.G * 255),
            math.floor(preview.BackgroundColor3.B * 255))
    end)

    -- Pop-in
    TweenService:Create(modal, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        { BackgroundTransparency = 0.55 }):Play()
    TweenService:Create(popScale, TweenInfo.new(0.32, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
        { Scale = 1 }):Play()
    TweenService:Create(card, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        { GroupTransparency = 0 }):Play()

    -- Close
    local closing = false
    local function closeModal()
        if closing then return end
        closing = true

        local exitScale = TweenService:Create(popScale,
            TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            { Scale = 0.86 })
        exitScale:Play()
        TweenService:Create(card, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            { GroupTransparency = 1 }):Play()
        TweenService:Create(modal, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            { BackgroundTransparency = 1 }):Play()

        exitScale.Completed:Connect(function()
            if self._colorPickerModal == modal then
                self._colorPickerModal = nil
            end
            pcall(function() modal:Destroy() end)
            if onClose then pcall(onClose) end
        end)
    end

    BindTap(backdrop, closeModal)
    BindTap(closeBtn, closeModal)
    BindTap(doneBtn, closeModal)

    return modal
end

function LucidUI.Window:_openColorPicker(fieldKey, fieldLabel)
    self:_openColorPickerModal({
        Label = fieldLabel,
        InitialColor = self._customTheme[fieldKey],
        OnChange = function(c)
            self._customTheme[fieldKey] = c
            self:ApplyCustomTheme()
            if self._refreshSwatches then pcall(self._refreshSwatches) end
        end,
    })
end

-- ============================================================
-- [IMPROVEMENT] Low Graphics Mode
-- ============================================================
function LucidUI.Window:_buildPerformanceSettings()
    self:_addSettingSection("Performance")

    if self._lowGraphics == nil then
        self._lowGraphics = false
    end

    local row = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 44),
    })
    Corner(10, row)
    self:_addSettingFrame(row)

    local label = Create("TextLabel", {
        Text = "Low Graphics Mode",
        Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 4),
        Size = UDim2.new(1, -100, 0, 18),
        Parent = row,
    })

    local subLabel = Create("TextLabel", {
        Text = "Disables animations & blur (better for mobile)",
        Font = Enum.Font.Gotham, TextSize = 11,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 22),
        Size = UDim2.new(1, -100, 0, 14),
        Parent = row,
    })

    local track = Create("Frame", {
        Size = UDim2.fromOffset(44, 24),
        Position = UDim2.new(1, -58, 0.5, -12),
        BackgroundColor3 = self._lowGraphics and self.Theme.Accent or self.Theme.ToggleOff,
        BorderSizePixel = 0, Parent = row,
    })
    Corner(12, track)

    local knob = Create("Frame", {
        Size = UDim2.fromOffset(20, 20),
        Position = self._lowGraphics and UDim2.new(1, -22, 0.5, -10) or UDim2.fromOffset(2, 2),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0, Parent = track,
    })
    Corner(10, knob)

    local clickArea = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = row,
    })

    local function setLowGraphics(on)
        self._lowGraphics = on
        Tween(track, 0.22, {
            BackgroundColor3 = on and self.Theme.Accent or self.Theme.ToggleOff,
        }, Enum.EasingStyle.Quart):Play()
        Tween(knob, 0.22, {
            Position = on and UDim2.new(1, -22, 0.5, -10) or UDim2.fromOffset(2, 2),
        }, Enum.EasingStyle.Quart):Play()

        -- Disable glass animations on the main window
        if self.Main then
            local sweep = self.Main:FindFirstChild("GlassSweep", true)
            if sweep then sweep.Visible = not on end
        end
    end

    BindTap(clickArea, function()
        PlayUISound("click")
        setLowGraphics(not self._lowGraphics)
    end)

    clickArea.MouseEnter:Connect(function()
        Tween(row, 0.15, { BackgroundTransparency = math.max(self.Theme.SurfaceTrans - 0.1, 0) }):Play()
    end)
    clickArea.MouseLeave:Connect(function()
        Tween(row, 0.15, { BackgroundTransparency = self.Theme.SurfaceTrans }):Play()
    end)

    self:_registerTheme(function(t)
        row.BackgroundColor3 = t.Surface
        label.TextColor3 = t.TextPrimary
        subLabel.TextColor3 = t.TextMuted
        track.BackgroundColor3 = self._lowGraphics and t.Accent or t.ToggleOff
    end)
end

-- ============================================================
-- Theme dropdown
-- ============================================================
function LucidUI.Window:_buildThemeSettings()
    self:_addSettingSection("Theme")

    local row = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 44),
        ClipsDescendants = true,
    })
    Corner(10, row)
    local rowStroke = Stroke(self.Theme.Border, 1, self.Theme.BorderTrans + 0.05, row)
    self:_addSettingFrame(row)

    local headerBtn = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 44), Parent = row,
    })
    Create("TextLabel", {
        Text = "Active Theme", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -100, 1, 0), Parent = headerBtn,
    })
    local valueLbl = Create("TextLabel", {
        Text = self.ThemeName, Font = Enum.Font.GothamMedium, TextSize = 13,
        TextColor3 = self.Theme.Accent, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Right,
        Size = UDim2.new(1, -40, 1, 0), Parent = headerBtn,
    })
    local arrowLbl = Create("TextLabel", {
        Text = "v", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        Position = UDim2.new(1, -24, 0, 0), Size = UDim2.fromOffset(20, 44), Parent = headerBtn,
    })

    local list = Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0), Position = UDim2.fromOffset(10, 44),
        BackgroundTransparency = 1, ClipsDescendants = true, Parent = row,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = list,
    })

    local expanded = false
    local optionBtns = {}

    local function buildOptions()
        for _, b in ipairs(optionBtns) do pcall(function() b:Destroy() end) end
        optionBtns = {}

        local options = {}
        local presetNames = {}
        for name in pairs(LucidUI.Themes) do
            if not name:match("^__") and name ~= "Custom" then
                table.insert(presetNames, name)
            end
        end
        table.sort(presetNames, function(a, b)
            if a == "Default" then return true end
            if b == "Default" then return false end
            return a:lower() < b:lower()
        end)
        for _, name in ipairs(presetNames) do table.insert(options, name) end
        table.insert(options, "Custom")
        for _, name in ipairs(Compat.listThemes()) do table.insert(options, name) end

        for i, name in ipairs(options) do
            local isActive = (name == self.ThemeName)
            local opt = Create("TextButton", {
                Text = (isActive and "✓  " or "    ") .. name,
                Font = Enum.Font.GothamMedium, TextSize = 13,
                TextColor3 = isActive and self.Theme.Accent or self.Theme.TextPrimary,
                BackgroundColor3 = isActive and self.Theme.Surface or self.Theme.Background,
                BackgroundTransparency = isActive and 0.3 or 0.5,
                TextXAlignment = Enum.TextXAlignment.Left,
                AutoButtonColor = false,
                Size = UDim2.new(1, 0, 0, 32), LayoutOrder = i, Parent = list,
            })
            Corner(8, opt)
            Create("UIPadding", { PaddingLeft = UDim.new(0, 8), Parent = opt })

            opt.MouseEnter:Connect(function()
                local t = self.Theme
                Tween(opt, 0.12, { BackgroundColor3 = t.Accent, BackgroundTransparency = 0.3 }):Play()
            end)
            opt.MouseLeave:Connect(function()
                local t = self.Theme
                Tween(opt, 0.12, {
                    BackgroundColor3 = isActive and t.Surface or t.Background,
                    BackgroundTransparency = isActive and 0.3 or 0.5,
                }):Play()
            end)

            local themeName = name
            BindTap(opt, function()
                valueLbl.Text = themeName
                expanded = false
                Tween(list, 0.22, { Size = UDim2.new(1, -20, 0, 0) }):Play()
                Tween(row, 0.22, { Size = UDim2.new(1, 0, 0, 44) }):Play()
                Tween(arrowLbl, 0.2, { Rotation = 0 }):Play()
                if themeName == "Custom" then
                    self:ApplyCustomTheme()
                else
                    self:SetTheme(themeName)
                end
            end)

            table.insert(optionBtns, opt)
        end
    end

    buildOptions()
    self._themeDropdownRefresh = function() if expanded then buildOptions() end end

    BindTap(headerBtn, function()
        expanded = not expanded
        if expanded then buildOptions() end
        local h = #optionBtns * 36 + 8
        Tween(list, 0.22, { Size = UDim2.new(1, -20, 0, expanded and h or 0) }, Enum.EasingStyle.Quart):Play()
        Tween(row, 0.22, { Size = UDim2.new(1, 0, 0, expanded and (44 + h + 8) or 44) }, Enum.EasingStyle.Quart):Play()
        Tween(arrowLbl, 0.2, { Rotation = expanded and 180 or 0 }):Play()
    end)

    self:_registerTheme(function(t)
        row.BackgroundColor3 = t.Surface
        rowStroke.Color = t.Border
        valueLbl.TextColor3 = t.Accent
        arrowLbl.TextColor3 = t.TextMuted
        for _, b in ipairs(optionBtns) do
            b.BackgroundColor3 = t.Background
            b.TextColor3 = t.TextPrimary
        end
    end)
end

-- ============================================================
-- Custom theme editor
-- ============================================================
function LucidUI.Window:_buildCustomThemeSettings()
    self:_addSettingSection("Custom Theme")
    self:_ensureCustomTheme()

    local fields = {
        { key = "Background",   label = "Background"     },
        { key = "Surface",      label = "Surface"        },
        { key = "SurfaceHover", label = "Surface Hover"  },
        { key = "Accent",       label = "Accent"         },
        { key = "Border",       label = "Border"         },
        { key = "TextPrimary",  label = "Text"           },
    }
    local editorRows = {}
    local swatches   = {}

    for _, field in ipairs(fields) do
        local row = Create("Frame", {
            BackgroundColor3 = self.Theme.Surface,
            BackgroundTransparency = self.Theme.SurfaceTrans,
            Size = UDim2.new(1, 0, 0, 48),
        })
        Corner(10, row)
        self:_addSettingFrame(row)
        table.insert(editorRows, row)

        local labelLbl = Create("TextLabel", {
            Text = field.label,
            Font = Enum.Font.GothamMedium, TextSize = 14,
            TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.fromOffset(14, 0),
            Size = UDim2.new(1, -110, 1, 0),
            Parent = row,
        })

        local swatch = Create("Frame", {
            Size = UDim2.fromOffset(32, 32),
            Position = UDim2.new(1, -46, 0.5, -16),
            BackgroundColor3 = self._customTheme[field.key],
            BorderSizePixel = 0,
            Parent = row,
        })
        Corner(8, swatch)
        Stroke(self.Theme.Border, 1, 0.5, swatch)
        table.insert(swatches, { frame = swatch, key = field.key })

        local clickArea = Create("TextButton", {
            Text = "",
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            ZIndex = 5,
            Parent = row,
        })
        local fieldKey, fieldLabel = field.key, field.label
        BindTap(clickArea, function()
            self:_openColorPicker(fieldKey, fieldLabel)
        end)

        clickArea.MouseEnter:Connect(function()
            local t = self.Theme
            Tween(row, 0.12, {
                BackgroundTransparency = math.max(t.SurfaceTrans - 0.1, 0),
            }):Play()
        end)
        clickArea.MouseLeave:Connect(function()
            local t = self.Theme
            Tween(row, 0.12, { BackgroundTransparency = t.SurfaceTrans }):Play()
        end)
    end

    self._refreshSwatches = function()
        for _, s in ipairs(swatches) do
            s.frame.BackgroundColor3 = self._customTheme[s.key]
        end
    end

    local actionRow = Create("Frame", {
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 36),
    })
    self:_addSettingFrame(actionRow)
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), Parent = actionRow,
    })

    local function mkActionBtn(label, color, cb)
        local b = Create("TextButton", {
            Text = label, Font = Enum.Font.GothamBold, TextSize = 12,
            TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundColor3 = color,
            BackgroundTransparency = 0.2, AutoButtonColor = false,
            Size = UDim2.new(0.5, -3, 1, 0), Parent = actionRow,
        })
        Corner(8, b)
        BindTap(b, cb, { MoveThreshold = 8 })
        return b
    end

    mkActionBtn("Reset to Default", self.Theme.Surface, function()
        self._customTheme = {
            Background   = LucidUI.Themes.Default.Background,
            Surface      = LucidUI.Themes.Default.Surface,
            SurfaceHover = LucidUI.Themes.Default.SurfaceHover,
            Accent       = LucidUI.Themes.Default.Accent,
            Border       = LucidUI.Themes.Default.Border,
            TextPrimary  = LucidUI.Themes.Default.TextPrimary,
        }
        for _, s in ipairs(swatches) do
            s.frame.BackgroundColor3 = self._customTheme[s.key]
        end
        self:ApplyCustomTheme()
        self._refreshSwatches()
        LucidUI:Notify({ Title = "Reset", Message = "Custom theme reset to Default", Variant = "info" })
    end)

    mkActionBtn("Apply Custom", self.Theme.Accent, function()
        self:ApplyCustomTheme()
        self._refreshSwatches()
        LucidUI:Notify({ Title = "Applied", Message = "Custom theme active", Variant = "success" })
    end)

    local saveRow = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
    })
    Corner(10, saveRow)
    self:_addSettingFrame(saveRow)

    local nameBox = Create("TextBox", {
        Text = "", PlaceholderText = "theme name...",
        PlaceholderColor3 = self.Theme.TextMuted, Font = Enum.Font.Gotham, TextSize = 13,
        TextColor3 = self.Theme.TextPrimary, BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.3, ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, -120, 0, 26),
        Position = UDim2.new(0, 14, 0.5, -13), Parent = saveRow,
    })
    Corner(8, nameBox)
    Create("UIPadding", {
        PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = nameBox,
    })

    local saveBtn = Create("TextButton", {
        Text = "Save As", Font = Enum.Font.GothamBold, TextSize = 12,
        TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundColor3 = self.Theme.Accent,
        BackgroundTransparency = 0.2, AutoButtonColor = false,
        Size = UDim2.fromOffset(100, 26),
        Position = UDim2.new(1, -114, 0.5, -13), Parent = saveRow,
    })
    Corner(8, saveBtn)
    BindTap(saveBtn, function()
        local name = nameBox.Text
        if name == "" then
            LucidUI:Notify({
                Title = "Invalid", Message = "Enter a theme name",
                Variant = "error",
            })
            return
        end
        self:SaveCustomTheme(name)
        nameBox.Text = ""
    end, { MoveThreshold = 8 })

    self:_registerTheme(function(t)
        for _, r in ipairs(editorRows) do r.BackgroundColor3 = t.Surface end
        saveRow.BackgroundColor3 = t.Surface
        nameBox.BackgroundColor3 = t.Background
        nameBox.TextColor3 = t.TextPrimary
        saveBtn.BackgroundColor3 = t.Accent
    end)
end

-- ============================================================
-- Saved themes list
-- ============================================================
function LucidUI.Window:_buildSavedThemesSettings()
    self:_addSettingSection("Saved Themes")

    local savedRow = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
        ClipsDescendants = true,
    })
    Corner(10, savedRow)
    self:_addSettingFrame(savedRow)

    local savedHeader = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 40), Parent = savedRow,
    })
    Create("TextLabel", {
        Text = "Saved Themes", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -100, 1, 0),
        Parent = savedHeader,
    })
    local savedArrow = Create("TextLabel", {
        Text = "v", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        Position = UDim2.new(1, -24, 0, 0), Size = UDim2.fromOffset(20, 40),
        Parent = savedHeader,
    })

    local savedList = Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0), Position = UDim2.fromOffset(10, 40),
        BackgroundTransparency = 1, ClipsDescendants = true, Parent = savedRow,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = savedList,
    })

    local savedExpanded = false
    local savedRowFrames = {}

    local function updateListSize()
        local h = 0
        for _, f in ipairs(savedRowFrames) do
            h = h + f.Size.Y.Offset + 4
        end
        if h > 0 then h = h - 4 end
        h = h + 8

        if savedExpanded then
            Tween(savedList, 0.22, { Size = UDim2.new(1, -20, 0, h) }, Enum.EasingStyle.Quart):Play()
            Tween(savedRow, 0.22, { Size = UDim2.new(1, 0, 0, 40 + h + 8) }, Enum.EasingStyle.Quart):Play()
        end
    end

    local function rebuildSaved()
        for _, f in ipairs(savedRowFrames) do
            if f and f.Parent then pcall(function() f:Destroy() end) end
        end
        savedRowFrames = {}

        local names = Compat.listThemes()
        if #names == 0 then
            local empty = Create("TextLabel", {
                Text = "No saved themes yet",
                Font = Enum.Font.Gotham, TextSize = 12,
                TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 32),
                LayoutOrder = 1, Parent = savedList,
            })
            table.insert(savedRowFrames, empty)
            updateListSize()
            return
        end

        for i, name in ipairs(names) do
            local rowWrap = Create("Frame", {
                Size = UDim2.new(1, 0, 0, 32),
                BackgroundColor3 = self.Theme.Background,
                BackgroundTransparency = 0.5,
                LayoutOrder = i,
                Parent = savedList,
            })
            Corner(8, rowWrap)
            table.insert(savedRowFrames, rowWrap)

            local nameBtn = Create("TextButton", {
                Text = name,
                Font = Enum.Font.GothamMedium, TextSize = 13,
                TextColor3 = self.Theme.TextPrimary,
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Size = UDim2.new(1, -36, 1, 0),
                Position = UDim2.fromOffset(10, 0),
                ZIndex = 3, Parent = rowWrap,
            })

            local delBtn = Create("TextButton", {
                Text = "x",
                Font = Enum.Font.GothamBold, TextSize = 14,
                TextColor3 = Color3.fromRGB(255, 100, 100),
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                Size = UDim2.fromOffset(28, 32),
                Position = UDim2.new(1, -32, 0, 0),
                ZIndex = 3, Parent = rowWrap,
            })

            local themeName = name
            BindTap(nameBtn, function()
                savedExpanded = false
                Tween(savedList, 0.22, { Size = UDim2.new(1, -20, 0, 0) }):Play()
                Tween(savedRow, 0.22, { Size = UDim2.new(1, 0, 0, 40) }):Play()
                Tween(savedArrow, 0.2, { Rotation = 0 }):Play()
                self:LoadCustomTheme(themeName)
                if self._refreshSwatches then pcall(self._refreshSwatches) end
            end)

            BindTap(delBtn, function()
                Compat.delete("LucidUI/Themes/" .. themeName .. ".json")
                if self.ThemeName == themeName then self:SetTheme("Default") end
                rebuildSaved()
                LucidUI:Notify({ Title = "Deleted", Message = themeName, Variant = "info" })
            end, { MoveThreshold = 8 })

            nameBtn.MouseEnter:Connect(function()
                local t = self.Theme
                Tween(rowWrap, 0.12, { BackgroundColor3 = t.Accent, BackgroundTransparency = 0.3 }):Play()
            end)
            nameBtn.MouseLeave:Connect(function()
                local t = self.Theme
                Tween(rowWrap, 0.12, { BackgroundColor3 = t.Background, BackgroundTransparency = 0.5 }):Play()
            end)
        end

        updateListSize()
    end

    self._savedThemeSlotsRefresh = rebuildSaved

    BindTap(savedHeader, function()
        savedExpanded = not savedExpanded

        if savedExpanded then
            rebuildSaved()
            Tween(savedArrow, 0.2, { Rotation = 180 }):Play()
        else
            -- Explicitly collapse the panel
            Tween(savedList, 0.22, {
                Size = UDim2.new(1, -20, 0, 0),
            }, Enum.EasingStyle.Quart):Play()
            Tween(savedRow, 0.22, {
                Size = UDim2.new(1, 0, 0, 40),
            }, Enum.EasingStyle.Quart):Play()
            Tween(savedArrow, 0.2, { Rotation = 0 }):Play()
        end
    end)

    self:_registerTheme(function(t)
        savedRow.BackgroundColor3 = t.Surface
        savedArrow.TextColor3 = t.TextMuted
        for _, f in ipairs(savedRowFrames) do
            if f:IsA("Frame") then
                f.BackgroundColor3 = t.Background
            elseif f:IsA("TextLabel") then
                f.TextColor3 = t.TextMuted
            end
        end
    end)
end

-- ============================================================
-- Module: 07_settings_b.lua
-- ============================================================
--[[
    Settings B — background image, keybinds, configs, watermark,
    docking, about, BuildSettingsPanel.
]]

local function relLuminance(c)
    local function lin(x)
        if x <= 0.03928 then return x / 12.92 end
        return ((x + 0.055) / 1.055) ^ 2.4
    end
    return 0.2126 * lin(c.R) + 0.7152 * lin(c.G) + 0.0722 * lin(c.B)
end

local function contrastRatio(c1, c2)
    local l1, l2 = relLuminance(c1), relLuminance(c2)
    if l1 < l2 then l1, l2 = l2, l1 end
    return (l1 + 0.05) / (l2 + 0.05)
end

-- ============================================================
-- Background Image
-- ============================================================
function LucidUI.Window:_buildBackgroundSettings()
    self:_addSettingSection("Background Image")

    if self._bgTransparency == nil then self._bgTransparency = 0.10 end

    local urlRow = Create("Frame", {
