-- Module: 08i_credit.lua
-- ============================================================
-- ============================================================
-- Module: 08i_credit.lua
-- ============================================================
--[[
    Credit — two opt-in tools for hub authors:

      LucidUI:MainCredit(opts)   Registers an auto-built "Main" tab
                                 that becomes the first visible tab
                                 on every new window. Perfect for
                                 Discord links, donation buttons,
                                 and script-sharing pages.

      LucidUI:ShowCredit(opts)   Shows a one-time popup with your
                                 branding, anti-scam warning, and
                                 a call-to-action button. You decide
                                 when to call it — nothing fires
                                 automatically.

    Design notes:
      • Both are OFF by default. Nothing renders unless you call
        MainCredit() or ShowCredit().
      • No clipboard writes ever.
      • No auto-firing — ShowCredit only shows when you call it.
      • No HTTP. No external URLs beyond what you provide.
      • Opt-in per window via CreateWindow({ ShowCreditTab = false }).

    Usage:
        local LucidUI = loadstring(...)()
        LucidUI:MainCredit({
            Discord     = "discord.gg/yourinvite",
            Links = {
                { Name = "ScriptBlox", URL = "https://scriptblox.com/u/you" },
            },
        })

        -- Later, if you want a popup once at startup:
        task.delay(3, function()
            LucidUI:ShowCredit({
                Title    = "My Hub",
                Subtitle = "100% free — always",
                OnClose  = function() print("Dismissed") end,
            })
        end)
]]

-- ============================================================
-- Config storage
-- ============================================================
LucidUI._mainCreditOpts    = nil
LucidUI._creditTabConsumed = false

-- ============================================================
-- MainCredit — register opt-in Main tab
-- ============================================================
--[[
    opts = {
        TabName  = "Main",
        TabIcon  = "home",
        Discord  = "discord.gg/...",
        PayPal   = "paypal.me/...",
        Solana   = "wallet address",
        Links    = {
            { Name = "ScriptBlox", URL = "https://..." },
            { Name = "YouTube",    URL = "https://..." },
        },
        Warning  = "Custom anti-scam text (optional)",
        Free     = true,      -- show "100% free" banner (default true)
    }
]]

function LucidUI:MainCredit(opts)
    if type(opts) ~= "table" then opts = {} end
    self._mainCreditOpts    = opts
    self._creditTabConsumed = false
end

-- ============================================================
-- Build the Main tab content
-- ============================================================
local function buildMainTab(tab, opts)
    local theme = tab.Window.Theme

    -- ── Anti-scam banner ──────────────────────────────────
    if opts.Free ~= false then
        tab:CreateSection("Notice")

        local banner = tab:CreateBanner({
            Variant = "warn",
            Title   = "100% FREE & KEYLESS — ALWAYS",
            Text    = opts.Warning or
                "Asked for a key? You got scammed. Every feature here is "
                .. "free and open. No offerwalls, no Linkvertise, no keys.",
        })
    end

    -- ── Community section ─────────────────────────────────
    if opts.Discord and opts.Discord ~= "" then
        tab:CreateSection("Community")

        tab:CreateParagraph({
            Text = "Join the Discord for updates, new scripts, and support.",
        })

        -- Copy-to-clipboard is NOT automatic — only fires if the user
        -- explicitly clicks the button.
        tab:CreateButton({
            Name = "Copy Discord Invite  (" .. opts.Discord .. ")",
            Callback = function()
                local url = opts.Discord
                if not url:match("^https?://") then
                    url = "https://" .. url
                end
                local ok = false
                if type(setclipboard) == "function" then
                    ok = pcall(setclipboard, url)
                end
                if ok then
                    LucidUI:Notify({
                        Title = "Copied",
                        Message = "Discord invite copied to clipboard",
                        Variant = "success",
                        Duration = 3,
                    })
                else
                    LucidUI:Notify({
                        Title = "Clipboard Unavailable",
                        Message = "Your executor doesn't support setclipboard.",
                        Variant = "warn",
                        Duration = 4,
                    })
                end
            end,
        })
    end

    -- ── Support section ──────────────────────────────────
    if opts.PayPal or opts.Solana then
        tab:CreateSection("Support")

        tab:CreateParagraph({
            Text = "This script is free and always will be. If you want to say thanks, "
                .. "a coffee goes a long way.",
        })

        if opts.PayPal then
            tab:CreateButton({
                Name = "Copy PayPal Link  (" .. opts.PayPal .. ")",
                Callback = function()
                    local url = opts.PayPal
                    if not url:match("^https?://") then
                        url = "https://" .. url
                    end
                    local ok = false
                    if type(setclipboard) == "function" then
                        ok = pcall(setclipboard, url)
                    end
                    if ok then
                        LucidUI:Notify({
                            Title = "Thanks!",
                            Message = "PayPal link copied",
                            Variant = "success",
                            Duration = 3,
                        })
                    end
                end,
            })
        end

        if opts.Solana then
            tab:CreateButton({
                Name = "Copy Solana Address  (" .. opts.Solana:sub(1, 10) .. "...)",
                Callback = function()
                    local ok = false
                    if type(setclipboard) == "function" then
                        ok = pcall(setclipboard, opts.Solana)
                    end
                    if ok then
                        LucidUI:Notify({
                            Title = "Thanks!",
                            Message = "Solana address copied",
                            Variant = "success",
                            Duration = 3,
                        })
                    end
                end,
            })
        end
    end

    -- ── Links section ─────────────────────────────────────
    if opts.Links and #opts.Links > 0 then
        tab:CreateSection("Links")

        tab:CreateParagraph({
            Text = "Find all my scripts and updates on these platforms.",
        })

        for _, link in ipairs(opts.Links) do
            local name = link.Name or "Link"
            local url  = link.URL  or ""
            tab:CreateButton({
                Name = "Copy " .. name .. " Link",
                Callback = function()
                    local ok = false
                    if type(setclipboard) == "function" then
                        ok = pcall(setclipboard, url)
                    end
                    if ok then
                        LucidUI:Notify({
                            Title = name .. " Copied",
                            Message = "Link copied to clipboard",
                            Variant = "success",
                            Duration = 3,
                        })
                    end
                end,
            })
        end
    end

    -- ── Info footer ───────────────────────────────────────
    tab:CreateSection("Info")

    tab:CreateParagraph({
        Text = "LucidUI v" .. (LucidUI._version or "?")
            .. " — a modern, glass-morphism interface for Roblox.",
        Muted = true,
        TextSize = 11,
    })
end

-- ============================================================
-- Hook CreateWindow — build the Main tab as the first tab
-- ============================================================
local _origCreateWindow = LucidUI.CreateWindow
function LucidUI:CreateWindow(config)
    local W = _origCreateWindow(self, config)

    -- Only build once per window, and only if MainCredit() was called
    if self._mainCreditOpts and not self._creditTabConsumed then
        -- Per-window opt-out
        if config.ShowCreditTab ~= false then
            local opts = self._mainCreditOpts
            local icon = opts.TabIcon
            if icon == nil then icon = "home" end

            local ok, tab = pcall(function()
                return W:CreateTab({
                    Name = opts.TabName or "Main",
                    Icon = icon,
                })
            end)

            if ok and tab then
                pcall(buildMainTab, tab, opts)
            end
        end

        -- Only consume once so multiple windows don't all get it
        -- (unless the user re-calls MainCredit between them).
        self._creditTabConsumed = true
    end

    return W
end

-- ============================================================
-- ShowCredit — one-shot popup
-- ============================================================
--[[
    opts = {
        Title         = "My Hub",
        Subtitle      = "Made by You",
        Body          = "Optional custom message",
        WarningText   = "Asked for a key? You got scammed.",
        FreeBadge     = true,
        Discord       = "discord.gg/...",
        ButtonLabel   = "Copy Discord",
        ButtonAction  = function() end,   -- overrides Discord copy
        CloseLabel    = "Got it",
        OnClose       = function() end,
        Dismissible   = true,             -- allow click-outside to close
        Duration      = nil,              -- auto-close after N seconds (nil = manual)
    }
]]

function LucidUI:ShowCredit(opts)
    opts = opts or {}
    if self._creditShown and not opts.Force then
        return false -- only one per session unless Force = true
    end
    self._creditShown = true

    local theme = LucidUI._lastTheme or LucidUI.Themes.Default

    -- Root GUI
    local gui = Create("ScreenGui", {
        Name = "LucidUI_CreditPopup",
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = opts.DisplayOrder or 9999,
        Parent = PlayerGui,
    })

    -- Backdrop
    local backdrop = Create("TextButton", {
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 1,
        Parent = gui,
    })

    -- Card
    local card = Create("Frame", {
        Size = UDim2.fromOffset(opts.Width or 420, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        Position = UDim2.new(0.5, 0, 0.5, -100),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = theme.Background,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 3,
        Parent = gui,
    })
    Corner(18, card)

    local cardStroke = Stroke(theme.Accent, 1.5, 1, card)

    local cardScale = Instance.new("UIScale")
    cardScale.Scale = 0.85
    cardScale.Parent = card

    -- Content list
    local content = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        ZIndex = 4,
        Parent = card,
    })

    Create("UIPadding", {
        PaddingTop    = UDim.new(0, 22),
        PaddingBottom = UDim.new(0, 18),
        PaddingLeft   = UDim.new(0, 22),
        PaddingRight  = UDim.new(0, 22),
        Parent = content,
    })

    Create("UIListLayout", {
        Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = content,
    })

    -- ── Free badge ────────────────────────────────────────
    if opts.FreeBadge ~= false then
        local badgeRow = Create("Frame", {
            Size = UDim2.new(1, 0, 0, 34),
            BackgroundColor3 = theme.Accent,
            BackgroundTransparency = 0.82,
            BorderSizePixel = 0,
            LayoutOrder = 1,
            ZIndex = 5,
            Parent = content,
        })
        Corner(8, badgeRow)
        Stroke(theme.Accent, 1, 0.5, badgeRow)

        Create("TextLabel", {
            Text = "✓  100% FREE & KEYLESS",
            Font = Enum.Font.GothamBold,
            TextSize = 13,
            TextColor3 = theme.Accent,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Center,
            Size = UDim2.fromScale(1, 1),
            ZIndex = 6,
            Parent = badgeRow,
        })
    end

    -- ── Title ─────────────────────────────────────────────
    local titleLbl = Create("TextLabel", {
        Text = opts.Title or "LucidUI",
        Font = Enum.Font.GothamBlack,
        TextSize = 22,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Center,
        Size = UDim2.new(1, 0, 0, 30),
        LayoutOrder = 2,
        ZIndex = 5,
        Parent = content,
    })

    -- ── Subtitle ──────────────────────────────────────────
    if opts.Subtitle then
        Create("TextLabel", {
            Text = opts.Subtitle,
            Font = Enum.Font.GothamMedium,
            TextSize = 13,
            TextColor3 = theme.TextSecondary,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Center,
            Size = UDim2.new(1, 0, 0, 18),
            LayoutOrder = 3,
            ZIndex = 5,
            Parent = content,
        })
    end

    -- ── Anti-scam warning ─────────────────────────────────
    if opts.WarningText ~= false then
        Create("TextLabel", {
            Text = opts.WarningText or "Asked for a key? You got scammed.",
            Font = Enum.Font.GothamMedium,
            TextSize = 12,
            TextColor3 = Color3.fromRGB(255, 130, 130),
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextWrapped = true,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            LayoutOrder = 4,
            ZIndex = 5,
            Parent = content,
        })
    end

    -- ── Body ──────────────────────────────────────────────
    if opts.Body then
        Create("TextLabel", {
            Text = opts.Body,
            Font = Enum.Font.Gotham,
            TextSize = 12,
            TextColor3 = theme.TextMuted,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextWrapped = true,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            LayoutOrder = 5,
            ZIndex = 5,
            Parent = content,
        })
    end

    -- ── Primary action button ─────────────────────────────
    if opts.Discord or opts.ButtonAction then
        local actionBtn = Create("TextButton", {
            Text = opts.ButtonLabel or "Copy Discord Invite",
            Font = Enum.Font.GothamBold,
            TextSize = 13,
            TextColor3 = Color3.fromRGB(255, 255, 255),
            BackgroundColor3 = theme.Accent,
            BackgroundTransparency = 0.15,
            AutoButtonColor = false,
            Size = UDim2.new(1, 0, 0, 38),
            LayoutOrder = 6,
            ZIndex = 5,
            Parent = content,
        })
        Corner(8, actionBtn)

        actionBtn.MouseEnter:Connect(function()
            Tween(actionBtn, 0.15, { BackgroundTransparency = 0 }):Play()
        end)
        actionBtn.MouseLeave:Connect(function()
            Tween(actionBtn, 0.15, { BackgroundTransparency = 0.15 }):Play()
        end)

        BindTap(actionBtn, function()
            if opts.ButtonAction then
                Compat.safeCallback(opts.ButtonAction)
            elseif opts.Discord then
                local url = opts.Discord
                if not url:match("^https?://") then url = "https://" .. url end
                local ok = false
                if type(setclipboard) == "function" then
                    ok = pcall(setclipboard, url)
                end
                if ok then
                    actionBtn.Text = "✓ Copied!"
                    task.delay(2, function()
                        if actionBtn.Parent then
                            actionBtn.Text = opts.ButtonLabel or "Copy Discord Invite"
                        end
                    end)
                end
            end
        end)
    end

    -- ── Close button ──────────────────────────────────────
    local closeBtn = Create("TextButton", {
        Text = opts.CloseLabel or "Got it",
        Font = Enum.Font.GothamBold,
        TextSize = 13,
        TextColor3 = theme.TextPrimary,
        BackgroundColor3 = theme.Surface,
        BackgroundTransparency = 0.3,
        AutoButtonColor = false,
        Size = UDim2.new(1, 0, 0, 34),
        LayoutOrder = 7,
        ZIndex = 5,
        Parent = content,
    })
    Corner(8, closeBtn)

    -- ── Close logic ───────────────────────────────────────
    local closing = false
    local function closePopup()
        if closing then return end
        closing = true

        pcall(function()
            Tween(card, 0.22, { BackgroundTransparency = 1 }):Play()
            Tween(cardStroke, 0.22, { Transparency = 1 }):Play()
            Tween(cardScale, 0.22, { Scale = 0.85 }):Play()
            Tween(backdrop, 0.22, { BackgroundTransparency = 1 }):Play()

            for _, child in ipairs(content:GetDescendants()) do
                if child:IsA("TextLabel") or child:IsA("TextButton") then
                    Tween(child, 0.18, { TextTransparency = 1 }):Play()
                end
            end
        end)

        task.delay(0.25, function()
            if gui.Parent then gui:Destroy() end
            if opts.OnClose then Compat.safeCallback(opts.OnClose) end
        end)
    end

    BindTap(closeBtn, closePopup)
    if opts.Dismissible ~= false then
        BindTap(backdrop, closePopup)
    end

    -- ── Entrance animation ────────────────────────────────
    Tween(backdrop, 0.35, { BackgroundTransparency = 0.55 }):Play()
    Tween(card, 0.40, { BackgroundTransparency = theme.BackgroundTrans or 0.1 }):Play()
    Tween(cardStroke, 0.40, { Transparency = 0.4 }):Play()
    Tween(cardScale, 0.45, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()

    -- ── Auto-close timer ──────────────────────────────────
    if opts.Duration and opts.Duration > 0 then
        task.delay(opts.Duration, closePopup)
    end

    return {
        Gui = gui,
        Card = card,
        Close = closePopup,
    }
end

-- ============================================================
-- Reset helper — lets a hub author re-show the credit later
-- ============================================================
function LucidUI:ResetCreditShown()
    self._creditShown = false
end

-- ============================================================
-- Cleanup
-- ============================================================
LucidUI:OnCleanup(function()
    pcall(function()
        if PlayerGui then
            for _, gui in ipairs(PlayerGui:GetChildren()) do
                if gui:IsA("ScreenGui") and gui.Name == "LucidUI_CreditPopup" then
                    pcall(function() gui:Destroy() end)
                end
            end
        end
    end)
    print("[LucidUI] Credit cleaned up")
end)

-- ============================================================
-- Module: 08j_sidetabs.lua
-- ============================================================
-- ============================================================
-- Module: 08j_sidetabs.lua
-- ============================================================
--[[
    Side Tabs — turns LucidUI's horizontal tab strip into a vertical
    left sidebar. Matches RayVoid's `SideTabs = true` behaviour.

    Usage:
        LucidUI:CreateWindow({
            Name = "My Hub",
            SideTabs = true,                 -- default width 130
            -- OR:
            SideTabs = { Width = 150 },      -- custom width
        })

    What it changes:
      • TabStrip becomes a vertical ScrollingFrame on the left
      • Content moves to the right of the sidebar
      • Tab buttons become full-width, left-aligned
      • A subtle vertical divider sits between sidebar and content
      • Sidebar gets a faint theme-tinted background
      • Header + separator + window controls are untouched

    Also handles:
      • Theme changes (sidebar bg, divider color, tab text)
      • Window resize (re-applies the layout after LucidUI's
        default resize handler overwrites Content.Size)
      • Window minimize (no-op — dimensions already account for it)

    [FIX] convertTabStripToSidebar now re-styles every tab that
    already exists on the window. Previously it only flipped the
    UIListLayout to Vertical, which meant pre-existing tabs (like
    the auto-created MainCredit tab from 08i_credit.lua, or any
    tabs created before SetSideTabs was called at runtime) kept
    their horizontal widths and rendered as squat little boxes in
    the sidebar. Now they're all resized to (1, -8, 0, 36) and
    left-aligned to match tabs created after conversion.

    NO tracking. NO network. NO clipboard.
]]

-- ============================================================
-- Per-window layout
-- ============================================================
--[[
    Layout math (from top of W.Main):
        y = 0    : header              (height 44)
        y = 44   : separator           (height 1)
        y = 52   : sidebar + content   (8px gap after separator)
        y = H-12 : bottom margin

    Sidebar:
        x = 12, width = sw, height = H - 64

    Content:
        x = 12 + sw + 8, width = W - (12 + sw + 8) - 12 = W - (sw + 32)
        height = H - 64

    Divider (optional):
        x = 12 + sw + 4, width = 1, height = H - 64
]]

local HEADER_H = 44
local GAP      = 8
local MARGIN   = 12

local function computeLayout(W)
    local sw = W._sideTabsWidth or 130
    local sidebarX  = MARGIN
    local contentX  = MARGIN + sw + GAP
    local contentW  = -(contentX + MARGIN)   -- for UDim2.new(1, contentW, ...)
    local innerH    = -(HEADER_H + GAP + MARGIN)

    return {
        sidebarPosition  = UDim2.fromOffset(sidebarX, HEADER_H + GAP),
        sidebarSize      = UDim2.new(0, sw, 1, innerH),
        contentPosition  = UDim2.fromOffset(contentX, HEADER_H + GAP),
        contentSize      = UDim2.new(1, contentW, 1, innerH),
        dividerPosition  = UDim2.fromOffset(contentX - GAP / 2, HEADER_H + GAP),
        dividerSize      = UDim2.new(0, 1, 1, innerH),
    }
end

local function applyLayout(W)
    if not W._sideTabsMode then return end
    if W.Minimized then return end

    local L = computeLayout(W)
    W.TabStrip.Position = L.sidebarPosition
    W.TabStrip.Size     = L.sidebarSize
    W.Content.Position  = L.contentPosition
    W.Content.Size      = L.contentSize
    if W._sideTabsDivider then
        W._sideTabsDivider.Position = L.dividerPosition
        W._sideTabsDivider.Size     = L.dividerSize
    end
end

-- [FIX] Re-style a single tab button to fit the sidebar.
-- Shared between conversion-time (existing tabs) and
-- creation-time (tabs created after conversion).
local function styleTabForSidebar(tab)
    if not tab then return end
    if tab.Button then
        tab.Button.Size = UDim2.new(1, -8, 0, 36)
    end
    if tab.Label then
        tab.Label.TextXAlignment = Enum.TextXAlignment.Left
    end
end

-- ============================================================
-- Turn a horizontal TabStrip into a vertical sidebar
-- ============================================================
local function convertTabStripToSidebar(W, width)
    W._sideTabsMode  = true
    W._sideTabsWidth = width

    -- 1. Switch the tab list layout to vertical
    local list = W.TabStrip:FindFirstChildOfClass("UIListLayout")
    if list then
        list.FillDirection       = Enum.FillDirection.Vertical
        list.HorizontalAlignment = Enum.HorizontalAlignment.Left
        list.VerticalAlignment   = Enum.VerticalAlignment.Top
        list.Padding             = UDim.new(0, 6)
    end

    -- 2. Switch the scrolling direction
    W.TabStrip.ScrollingDirection = Enum.ScrollingDirection.Y
    W.TabStrip.CanvasSize         = UDim2.new(0, 0, 0, 0)
    W.TabStrip.AutomaticCanvasSize = Enum.AutomaticSize.Y
    W.TabStrip.ScrollBarThickness = 2
    W.TabStrip.ScrollBarImageColor3 = W.Theme.TextMuted
    W.TabStrip.ScrollBarImageTransparency = 0.5

    -- 3. Give the sidebar a subtle theme tint
    W.TabStrip.BackgroundColor3     = W.Theme.Surface
    W.TabStrip.BackgroundTransparency = 0.55

    -- 4. Add a thin vertical divider between sidebar and content
    local divider = Create("Frame", {
        Name = "SideTabsDivider",
        BackgroundColor3 = W.Theme.Border,
        BackgroundTransparency = (W.Theme.BorderTrans or 0.75) + 0.1,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = W.Main,
    })
    W._sideTabsDivider = divider

    -- 5. Position everything
    applyLayout(W)

    -- [FIX] 5b. Re-style every tab that already exists on this
    -- window. Without this, tabs created before conversion (which
    -- includes the auto-Main tab from 08i_credit.lua, since that
    -- hook runs before ours) keep their horizontal widths and
    -- render as tiny boxes in a 130px-wide sidebar.
    for _, tab in ipairs(W.Tabs or {}) do
        styleTabForSidebar(tab)
    end

    -- 6. Re-apply layout whenever Main resizes (window resize,
    --    minimize animation, etc.). We defer one frame because
    --    LucidUI's own resize handler runs after us and rewrites
    --    Content.Size with its hardcoded formula.
    local pending = false
    local function scheduleLayout()
        if pending then return end
        pending = true
        task.defer(function()
            pending = false
            applyLayout(W)
        end)
    end

    table.insert(W._conns, W.Main:GetPropertyChangedSignal("Size"):Connect(scheduleLayout))

    -- 7. Defensive: if Content.Size gets overwritten with a wrong
    --    formula (this happens on resize), snap it back.
    table.insert(W._conns, W.Content:GetPropertyChangedSignal("Size"):Connect(function()
        if W._fixingSideTabsSize or W.Minimized then return end
        local L = computeLayout(W)
        if W.Content.Size.X.Offset ~= L.contentSize.X.Offset then
            W._fixingSideTabsSize = true
            W.Content.Position = L.contentPosition
            W.Content.Size     = L.contentSize
            W._fixingSideTabsSize = false
        end
    end))

    -- 8. Theme hook
    W:_registerTheme(function(t)
        W.TabStrip.BackgroundColor3     = t.Surface
        W.TabStrip.ScrollBarImageColor3 = t.TextMuted
        if W._sideTabsDivider then
            W._sideTabsDivider.BackgroundColor3     = t.Border
            W._sideTabsDivider.BackgroundTransparency = (t.BorderTrans or 0.75) + 0.1
        end
    end)
end

-- ============================================================
-- Hook CreateWindow
-- ============================================================
local _origCreateWindow = LucidUI.CreateWindow
function LucidUI:CreateWindow(config)
    config = config or {}
    local W = _origCreateWindow(self, config)

    local sideCfg = config.SideTabs
    local enabled, width = false, 130

    if sideCfg == true then
        enabled = true
    elseif type(sideCfg) == "table" then
        enabled = true
        width = math.clamp(sideCfg.Width or 130, 90, 220)
    end

    if enabled then
        pcall(convertTabStripToSidebar, W, width)
    end

    return W
end

-- ============================================================
-- Hook CreateTab to make tab buttons fill the sidebar.
-- Fast-path returns immediately when side tabs aren't active,
-- so the default horizontal layout has zero overhead.
-- ============================================================
local _origCreateTab = LucidUI.Window.CreateTab
function LucidUI.Window:CreateTab(config)
    if not self._sideTabsMode then
        return _origCreateTab(self, config)
    end

    local tab = _origCreateTab(self, config)
    styleTabForSidebar(tab)
    return tab
end

-- ============================================================
-- Runtime toggle
-- ============================================================
--[[
    -- Convert an already-created window to side tabs:
    Window:SetSideTabs(true, 140)
    -- Revert:
    Window:SetSideTabs(false)
]]

function LucidUI.Window:SetSideTabs(enabled, width)
    if enabled and not self._sideTabsMode then
        convertTabStripToSidebar(self, width or 130)
        -- Note: convertTabStripToSidebar already restyles existing
        -- tabs, so we don't need a second loop here anymore.
        return true

    elseif not enabled and self._sideTabsMode then
        -- Revert to default horizontal layout
        self._sideTabsMode = false

        local list = self.TabStrip:FindFirstChildOfClass("UIListLayout")
        if list then
            list.FillDirection       = Enum.FillDirection.Horizontal
            list.VerticalAlignment   = Enum.VerticalAlignment.Center
            list.HorizontalAlignment = Enum.HorizontalAlignment.Left
        end

        self.TabStrip.ScrollingDirection  = Enum.ScrollingDirection.X
        self.TabStrip.CanvasSize          = UDim2.new(0, 0, 0, 34)
        self.TabStrip.AutomaticCanvasSize = Enum.AutomaticSize.X
        self.TabStrip.BackgroundTransparency = 1
        self.TabStrip.Size     = UDim2.new(1, -32, 0, 34)
        self.TabStrip.Position = UDim2.fromOffset(16, 52)
        self.TabStrip.ScrollBarThickness = 0

        self.Content.Position = UDim2.fromOffset(12, 94)
        self.Content.Size     = UDim2.new(1, -24, 1, -110)

        if self._sideTabsDivider then
            pcall(function() self._sideTabsDivider:Destroy() end)
            self._sideTabsDivider = nil
        end

        -- Re-style existing tabs back to auto-width
        for _, tab in ipairs(self.Tabs or {}) do
            local ts = TextService:GetTextSize(
                tab.Name or "", 13, Enum.Font.GothamMedium, Vector2.new(1000, 34)
            )
            local hasIcon = tab.IconParts and #tab.IconParts > 0
            local labelX  = hasIcon and 30 or 12
            if tab.Button then
                tab.Button.Size = UDim2.fromOffset(ts.X + labelX + 14, 34)
            end
            if tab.Label then
                tab.Label.TextXAlignment = Enum.TextXAlignment.Center
            end
        end
        return true
    end
    return false
end

-- ============================================================
-- Cleanup
-- ============================================================
LucidUI:OnCleanup(function()
    print("[LucidUI] SideTabs cleaned up")
end)

-- ============================================================
-- Module: 08k_pergameconfigs.lua
-- ============================================================
-- ============================================================
-- Module: 08k_pergameconfigs.lua
-- ============================================================
--[[
    Per-Game Configs — separate config folder per Roblox game,
    so your hub's settings don't collide between games.

    Without this module:
        LucidUI/Configs/aimbot.json    <- same file for every game

    With this module:
        LucidUI/Configs/{PlaceId}/aimbot.json   <- one per game

    Features:
      • Per-game save / load / list / delete
      • Autoload: remembers which config to load on join
      • Retry-with-backoff: if a flag isn't registered yet (because
        the game hasn't loaded or your tabs are still building),
        it waits and tries again instead of failing silently
      • Opt-in per window via CreateWindow({ PerGameConfigs = true })
      • Non-destructive: if disabled, falls back to the global system

    [FIX] ClearAutoload now deletes the autoload file rather than
    writing an empty payload. Falls back to the old behavior if the
    executor has no delfile. Also tightened configPath's filename
    sanitizer to strip spaces — some executors' writefile rejects
    paths containing spaces.

    NO tracking. NO network. NO clipboard.
]]

-- ============================================================
-- Config helpers
-- ============================================================
LucidUI.GameConfigs = {}
local GC = LucidUI.GameConfigs

local function hasFS()
    return type(makefolder) == "function"
       and type(isfolder)   == "function"
       and type(writefile)  == "function"
       and type(readfile)   == "function"
end

local function isfolderSafe(path)
    if type(isfolder) ~= "function" then return false end
    local ok, res = pcall(isfolder, path)
    return ok and res == true
end

local function isfileSafe(path)
    if type(isfile) ~= "function" then return false end
    local ok, res = pcall(isfile, path)
    return ok and res == true
end

-- Ensure a folder exists (creates nested folders one by one)
local function ensureFolder(path)
    if not hasFS() then return false end
    local parts = {}
    for segment in path:gmatch("[^/]+") do
        table.insert(parts, segment)
    end

    local built = ""
    for i, seg in ipairs(parts) do
        built = (i == 1) and seg or (built .. "/" .. seg)
        if not isfolderSafe(built) then
            local ok = pcall(makefolder, built)
            if not ok then return false end
        end
    end
    return true
end

-- ============================================================
-- Path layout
-- ============================================================
local ROOT          = "LucidUI"
local PLACE_ROOT    -- computed lazily (needs game.PlaceId)
local CONFIG_DIR    -- ROOT/{PlaceId}/Configs
local AUTOLOAD_FILE -- ROOT/{PlaceId}/autoload.json

local function ensurePaths()
    if PLACE_ROOT then return end
    local placeId = tostring(game.PlaceId)
    PLACE_ROOT    = ROOT .. "/" .. placeId
    CONFIG_DIR    = PLACE_ROOT .. "/Configs"
    AUTOLOAD_FILE = PLACE_ROOT .. "/autoload.json"

    ensureFolder(ROOT)
    ensureFolder(PLACE_ROOT)
    ensureFolder(CONFIG_DIR)
end

local function configPath(name)
    ensurePaths()
    -- [FIX] Sanitize file name. Previously allowed %s (spaces), which
    -- some executors' writefile rejects. Now only alphanumerics,
    -- underscores, hyphens, and dots survive.
    local safe = tostring(name):gsub("[^%w_%-%.]", "_")
    return CONFIG_DIR .. "/" .. safe .. ".json"
end

-- ============================================================
-- List / read / write
-- ============================================================
function GC.List()
    ensurePaths()
    if type(listfiles) ~= "function" then return {} end
    if not isfolderSafe(CONFIG_DIR) then return {} end

    local ok, files = pcall(listfiles, CONFIG_DIR)
    if not ok or type(files) ~= "table" then return {} end

    local out = {}
    for _, path in ipairs(files) do
        local name = path:match("([^/\\]+)%.json$")
        if name then table.insert(out, name) end
    end
    table.sort(out, function(a, b) return a:lower() < b:lower() end)
    return out
end

function GC.Read(name)
    ensurePaths()
    if type(readfile) ~= "function" then return nil end
    local path = configPath(name)
    if not isfileSafe(path) then return nil end

    local ok, raw = pcall(readfile, path)
    if not ok or not raw then return nil end

    local decodeOK, data = pcall(function()
        return game:GetService("HttpService"):JSONDecode(raw)
    end)
    if not decodeOK or type(data) ~= "table" then return nil end
    return data
end

function GC.Write(name, data)
    ensurePaths()
    if type(writefile) ~= "function" then return false end

    local encodeOK, raw = pcall(function()
        return game:GetService("HttpService"):JSONEncode(data)
    end)
    if not encodeOK or not raw then return false end

    local path = configPath(name)
    local ok = pcall(writefile, path, raw)
    return ok
end

function GC.Delete(name)
    ensurePaths()
    if type(delfile) ~= "function" then return false end
    local path = configPath(name)
    if not isfileSafe(path) then return false end
    return pcall(delfile, path)
end

-- ============================================================
-- Autoload
-- ============================================================
local function saveAutoload(slotName)
    ensurePaths()
    if type(writefile) ~= "function" then return false end
    local payload = game:GetService("HttpService"):JSONEncode({
        slot = slotName or "",
        savedAt = os.time(),
    })
    return pcall(writefile, AUTOLOAD_FILE, payload)
end

local function readAutoload()
    ensurePaths()
    if type(readfile) ~= "function" then return nil end
    if not isfileSafe(AUTOLOAD_FILE) then return nil end

    local ok, raw = pcall(readfile, AUTOLOAD_FILE)
    if not ok or not raw then return nil end

    local decodeOK, data = pcall(function()
        return game:GetService("HttpService"):JSONDecode(raw)
    end)
    if not decodeOK or type(data) ~= "table" then return nil end
    if type(data.slot) ~= "string" or data.slot == "" then return nil end
    return data.slot
end

function GC.SetAutoload(slotName)
    return saveAutoload(slotName)
end

function GC.GetAutoload()
    return readAutoload()
end

-- [FIX] Previously wrote an empty `{ slot = "" }` payload, which left
-- a stray autoload.json file sitting on disk forever. Now we delete
-- the file when the executor supports delfile; only fall back to the
-- empty-write path when delfile isn't available.
function GC.ClearAutoload()
    ensurePaths()

    if type(delfile) == "function" and isfileSafe(AUTOLOAD_FILE) then
        local ok = pcall(delfile, AUTOLOAD_FILE)
        if ok then return true end
        -- fall through to the legacy path on failure
    end

    -- Fallback: overwrite with an empty payload. readAutoload treats
    -- slot=="" as nil, so behaviorally equivalent — just leaves a
    -- harmless stub file behind.
    return saveAutoload(nil)
end

-- ============================================================
-- Save / Load window config to per-game slot
-- ============================================================
function GC.SaveWindow(window, name)
    if not window or not name then return false end
    if not hasFS() then return false end

    local data = {
        version     = 1,
        placeId     = game.PlaceId,
        savedAt     = os.time(),
        theme       = window._customThemeActive and "Custom" or window.ThemeName,
        windowSize  = { window._width, window._height },
        accent      = window._accentOverride and {
            R = window._accentOverride.R,
            G = window._accentOverride.G,
            B = window._accentOverride.B,
        } or nil,
        customTheme = window._customTheme and Compat.serializeColors(window._customTheme) or nil,
        bgUrl       = window._backgroundUrl,
        bgTrans     = window._bgTransparency,
        pillKeybind = window.PillKeybind and window.PillKeybind.Name or nil,
        lowGraphics = window._lowGraphics,
        elements    = window._configData or {},
    }
    return GC.Write(name, data)
end

function GC.LoadWindow(window, name, opts)
    opts = opts or {}
    if not window or not name then return false, "bad args" end
    if not hasFS() then return false, "no filesystem" end

    local data = GC.Read(name)
    if not data then return false, "not found" end

    -- Apply theme
    if data.theme then
        if data.theme == "Custom" and data.customTheme then
            local restored = Compat.deserializeColors(data.customTheme)
            if restored then
                local d = LucidUI.Themes.Default
                window._customTheme = {
                    Background   = restored.Background   or d.Background,
                    Surface      = restored.Surface      or d.Surface,
                    SurfaceHover = restored.SurfaceHover or d.SurfaceHover,
                    Accent       = restored.Accent       or d.Accent,
                    Border       = restored.Border       or d.Border,
                    TextPrimary  = restored.TextPrimary  or d.TextPrimary,
                }
                window:ApplyCustomTheme()
            end
        elseif LucidUI.Themes[data.theme] then
            window:SetTheme(data.theme)
        end
    end

    if data.accent then
        window:SetAccent(Color3.new(data.accent.R, data.accent.G, data.accent.B))
    end

    if data.windowSize then
        window._width  = math.clamp(data.windowSize[1], window._minWidth,  window._maxWidth)
        window._height = math.clamp(data.windowSize[2], window._minHeight, window._maxHeight)
        window._fullSize = UDim2.fromOffset(window._width, window._height)
        if not window.Minimized and window.Main then
            window.Main.Size = window._fullSize
        end
    end

    if data.bgTrans then window._bgTransparency = data.bgTrans end
    if data.bgUrl then window:SetBackgroundImage(data.bgUrl) end
    if data.pillKeybind then
        local key = Enum.KeyCode[data.pillKeybind]
        if key then window.PillKeybind = key end
    end

    -- Apply element values
    local applied, missing, errors = 0, {}, {}
    local elements = data.elements or {}

    for flag, value in pairs(elements) do
        local el = window._elementsByFlag and window._elementsByFlag[flag]
        if el and el.Set then
            local ok, err = pcall(function() el:Set(value) end)
            if ok then
                applied = applied + 1
            else
                table.insert(errors, { flag = flag, err = tostring(err) })
            end
        else
            table.insert(missing, flag)
        end
    end

    if opts.silent ~= true then
        local msg
        if #missing == 0 and #errors == 0 then
            msg = applied .. " element(s) loaded"
            LucidUI:Notify({
                Title = "Config Loaded",
                Message = name .. " — " .. msg,
                Variant = "success",
                Duration = 3,
            })
        else
            msg = applied .. " applied, " .. #missing .. " missing, " .. #errors .. " failed"
            LucidUI:Notify({
                Title = "Config Loaded (partial)",
                Message = name .. " — " .. msg,
                Variant = "warn",
                Duration = 5,
            })
        end
    end

    return true, {
        applied = applied,
        missing = missing,
        errors  = errors,
    }
end

-- ============================================================
-- Auto-load with retry
-- ============================================================
local function attemptAutoload(window, slot, attempt, maxRetries, onDone)
    attempt = attempt or 1
    maxRetries = maxRetries or 8

    local ok, result = GC.LoadWindow(window, slot, { silent = true })
    if not ok then
        if onDone then onDone(false) end
        return
    end

    local missing = result.missing or {}
    if #missing == 0 or attempt >= maxRetries then
        -- Done (either fully applied or out of retries)
        if #missing == 0 then
            LucidUI:Notify({
                Title = "Auto-Loaded",
                Message = slot .. " (" .. result.applied .. " element(s))",
                Variant = "success",
                Duration = 4,
            })
        else
            LucidUI:Notify({
                Title = "Auto-Load (partial)",
                Message = slot .. " — " .. #missing .. " flag(s) skipped",
                Variant = "warn",
                Duration = 5,
            })
        end
        if onDone then onDone(true, result) end
        return
    end

    -- Retry with backoff
    local wait = 0.5 + attempt * 0.4
    task.delay(wait, function()
        if not window.Gui or not window.Gui.Parent then return end
        attemptAutoload(window, slot, attempt + 1, maxRetries, onDone)
    end)
end

function GC.AutoLoadWindow(window, slotName, onDone)
    if not window or not slotName then return false end
    if not hasFS() then return false end

    -- Defer a bit so the window is fully constructed
    task.delay(1.5, function()
        if not window.Gui or not window.Gui.Parent then return end
        attemptAutoload(window, slotName, 1, 8, onDone)
    end)
    return true
end

-- ============================================================
-- Hook CreateWindow — auto-load if enabled
-- ============================================================
local _origCreateWindow = LucidUI.CreateWindow
function LucidUI:CreateWindow(config)
    config = config or {}
    local W = _origCreateWindow(self, config)

    if config.PerGameConfigs then
        W._perGameConfigs = true
        ensurePaths()

        -- Auto-load the saved slot if one exists
        local slot = readAutoload()
        if slot then
            local ok, list = pcall(GC.List)
            if ok and list then
                for _, s in ipairs(list) do
                    if s == slot then
                        GC.AutoLoadWindow(W, slot, function(success, result)
                            if not success and config.Debug then
                                print("[LucidUI] Auto-load failed for slot: " .. slot)
                            end
                        end)
                        break
                    end
                end
            end
        end

        -- Also override SaveConfig/LoadConfig to use per-game paths
        local _origSave = W.SaveConfig
        local _origLoad = W.LoadConfig

        function W:SaveConfig(name)
            if self._perGameConfigs then
                local ok = GC.SaveWindow(self, name)
                if ok then
                    LucidUI:Notify({
                        Title = "Saved (per-game)",
                        Message = name,
                        Variant = "success",
                        Duration = 3,
                    })
                else
                    LucidUI:Notify({
                        Title = "Save Failed",
                        Message = "Could not write to disk",
                        Variant = "error",
                        Duration = 3,
                    })
                end
                return ok
            end
            return _origSave and _origSave(self, name)
        end

        function W:LoadConfig(name)
            if self._perGameConfigs then
                local ok = GC.LoadWindow(self, name)
                return ok
            end
            return _origLoad and _origLoad(self, name)
        end
    end

    return W
end

-- ============================================================
-- Optional: settings UI section
-- ============================================================
function GC.BuildSettingsSection(window)
    if not window or not window._spContent then return end

    local function addSection(title)
        local label = Create("TextLabel", {
            Text = title:upper(),
            Font = Enum.Font.GothamBold,
            TextSize = 11,
            TextColor3 = window.Theme.TextMuted,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Size = UDim2.new(1, 0, 0, 18),
            LayoutOrder = window._settingsOrder,
            Parent = window._spContent,
        })
        window._settingsOrder = window._settingsOrder + 1
        window:_registerTheme(function(t) label.TextColor3 = t.TextMuted end)
        return label
    end

    local function addFrame(frame)
        frame.LayoutOrder = window._settingsOrder
        window._settingsOrder = window._settingsOrder + 1
        frame.Parent = window._spContent
        return frame
    end

    addSection("Per-Game Configs")

    -- Slot dropdown
    local slotRow = Create("Frame", {
        BackgroundColor3 = window.Theme.Surface,
        BackgroundTransparency = window.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
        ClipsDescendants = true,
    })
    Corner(10, slotRow)
    addFrame(slotRow)

    local slots = GC.List()
    if #slots == 0 then slots = { "(empty)" } end

    local currentSlot = slots[1]

    local headerBtn = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 40), Parent = slotRow,
    })
    Create("TextLabel", {
        Text = "Active Slot", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = window.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0),
        Size = UDim2.new(1, -100, 1, 0),
        Parent = headerBtn,
    })
    local slotLbl = Create("TextLabel", {
        Text = currentSlot, Font = Enum.Font.GothamMedium, TextSize = 13,
        TextColor3 = window.Theme.Accent, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Right,
        Size = UDim2.new(1, -34, 1, 0), Parent = headerBtn,
    })
    local arrowLbl = Create("TextLabel", {
        Text = "v", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = window.Theme.TextMuted, BackgroundTransparency = 1,
        Position = UDim2.new(1, -24, 0, 0),
        Size = UDim2.fromOffset(20, 40), Parent = headerBtn,
    })

    local slotList = Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        Position = UDim2.fromOffset(10, 40),
        BackgroundTransparency = 1, ClipsDescendants = true, Parent = slotRow,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = slotList,
    })

    local expanded = false
    local slotButtons = {}

    local function rebuildSlots()
        for _, b in ipairs(slotButtons) do b:Destroy() end
        slotButtons = {}
        local list = GC.List()
        if #list == 0 then list = { "(empty)" } end
        for i, name in ipairs(list) do
            local opt = Create("TextButton", {
                Text = name, Font = Enum.Font.GothamMedium, TextSize = 13,
                TextColor3 = window.Theme.TextPrimary,
                BackgroundColor3 = window.Theme.Background,
                BackgroundTransparency = 0.5, AutoButtonColor = false,
                Size = UDim2.new(1, 0, 0, 32), LayoutOrder = i, Parent = slotList,
            })
            Corner(8, opt)
            local nm = name
            BindTap(opt, function()
                currentSlot = nm
                slotLbl.Text = nm
                expanded = false
                Tween(slotList, 0.22, { Size = UDim2.new(1, -20, 0, 0) }):Play()
                Tween(slotRow, 0.22, { Size = UDim2.new(1, 0, 0, 40) }):Play()
                Tween(arrowLbl, 0.2, { Rotation = 0 }):Play()
            end)
            table.insert(slotButtons, opt)
        end
    end

    BindTap(headerBtn, function()
        expanded = not expanded
        if expanded then rebuildSlots() end
        local h = expanded and (#slotButtons * 36 + 8) or 0
        Tween(slotList, 0.22, { Size = UDim2.new(1, -20, 0, h) }):Play()
        Tween(slotRow, 0.22, { Size = UDim2.new(1, 0, 0, expanded and (40 + h + 8) or 40) }):Play()
        Tween(arrowLbl, 0.2, { Rotation = expanded and 180 or 0 }):Play()
    end)

    -- Action row
    local actionRow = Create("Frame", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 36),
    })
    addFrame(actionRow)
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        Parent = actionRow,
    })

    local function mkBtn(text, color, cb)
        local b = Create("TextButton", {
            Text = text, Font = Enum.Font.GothamBold, TextSize = 12,
            TextColor3 = Color3.fromRGB(255, 255, 255),
            BackgroundColor3 = color,
            BackgroundTransparency = 0.2, AutoButtonColor = false,
            Size = UDim2.new(0.5, -3, 1, 0),
            Parent = actionRow,
        })
        Corner(8, b)
        BindTap(b, cb, { MoveThreshold = 8 })
        return b
    end

    mkBtn("Save", window.Theme.Accent, function()
        if currentSlot == "(empty)" then
            LucidUI:Notify({
                Title = "No Slot",
                Message = "Create a slot first",
                Variant = "warn",
                Duration = 3,
            })
            return
        end
        window:SaveConfig(currentSlot)
    end)

    mkBtn("Load", window.Theme.Surface, function()
        if currentSlot == "(empty)" then return end
        window:LoadConfig(currentSlot)
    end)

    -- New slot input
    local newRow = Create("Frame", {
        BackgroundColor3 = window.Theme.Surface,
        BackgroundTransparency = window.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
    })
    Corner(10, newRow)
    addFrame(newRow)

    local inputBox = Create("TextBox", {
        Text = "",
        PlaceholderText = "new slot name...",
        PlaceholderColor3 = window.Theme.TextMuted,
        Font = Enum.Font.Gotham, TextSize = 13,
        TextColor3 = window.Theme.TextPrimary,
        BackgroundColor3 = window.Theme.Background,
        BackgroundTransparency = 0.3, ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, -120, 0, 26),
        Position = UDim2.new(0, 14, 0.5, -13),
        Parent = newRow,
    })
    Corner(8, inputBox)
    Create("UIPadding", {
        PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = inputBox,
    })

    local createBtn = Create("TextButton", {
        Text = "Create",
        Font = Enum.Font.GothamBold, TextSize = 12,
        TextColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundColor3 = window.Theme.Accent,
        BackgroundTransparency = 0.2, AutoButtonColor = false,
        Size = UDim2.fromOffset(90, 26),
        Position = UDim2.new(1, -104, 0.5, -13),
        Parent = newRow,
    })
    Corner(8, createBtn)
    BindTap(createBtn, function()
        local name = inputBox.Text
        if name == "" then return end
        GC.Write(name, { elements = {} }) -- create empty
        currentSlot = name
        slotLbl.Text = name
        inputBox.Text = ""
        rebuildSlots()
        LucidUI:Notify({
            Title = "Created",
            Message = name,
            Variant = "success",
            Duration = 3,
        })
    end, { MoveThreshold = 8 })

    -- Autoload row
    local autoRow = Create("Frame", {
        BackgroundColor3 = window.Theme.Surface,
        BackgroundTransparency = window.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 44),
    })
    Corner(10, autoRow)
    addFrame(autoRow)

    local autoLbl = Create("TextLabel", {
        Text = "Auto-load this slot on join",
        Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = window.Theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0),
        Size = UDim2.new(1, -80, 1, 0),
        Parent = autoRow,
    })

    local savedAuto = GC.GetAutoload()
    local isOn = (savedAuto == currentSlot)

    local track = Create("Frame", {
        Size = UDim2.fromOffset(44, 24),
        Position = UDim2.new(1, -58, 0.5, -12),
        BackgroundColor3 = isOn and window.Theme.Accent or window.Theme.ToggleOff,
        BorderSizePixel = 0, Parent = autoRow,
    })
    Corner(12, track)

    local knob = Create("Frame", {
        Size = UDim2.fromOffset(20, 20),
        Position = isOn and UDim2.new(1, -22, 0.5, -10) or UDim2.fromOffset(2, 2),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0, Parent = track,
    })
    Corner(10, knob)

    local autoClick = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = autoRow,
    })

    BindTap(autoClick, function()
        isOn = not isOn
        if isOn then
            GC.SetAutoload(currentSlot)
        else
            GC.ClearAutoload()
        end
        local t = window.Theme
        Tween(track, 0.22, {
            BackgroundColor3 = isOn and t.Accent or t.ToggleOff,
        }, Enum.EasingStyle.Quart):Play()
        Tween(knob, 0.22, {
            Position = isOn and UDim2.new(1, -22, 0.5, -10) or UDim2.fromOffset(2, 2),
        }, Enum.EasingStyle.Quart):Play()
    end)

    window:_registerTheme(function(t)
        slotRow.BackgroundColor3 = t.Surface
        slotLbl.TextColor3 = t.Accent
        arrowLbl.TextColor3 = t.TextMuted
        newRow.BackgroundColor3 = t.Surface
        inputBox.BackgroundColor3 = t.Background
        inputBox.TextColor3 = t.TextPrimary
        createBtn.BackgroundColor3 = t.Accent
        autoRow.BackgroundColor3 = t.Surface
        autoLbl.TextColor3 = t.TextPrimary
        track.BackgroundColor3 = isOn and t.Accent or t.ToggleOff
    end)
end

